--
-- Name: ai_usage; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ai_usage (
    usage_id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    model_code character varying(100) NOT NULL,
    actor_user_id uuid,
    cohort_id uuid,
    class_id uuid,
    project_id uuid,
    feature_code character varying(100) NOT NULL,
    context_type character varying(100) NOT NULL,
    context_id text,
    trigger_type character varying(30) NOT NULL,
    tier_code character varying(30),
    tier_policy_id uuid,
    grading_policy_id uuid,
    calibration_version_id uuid,
    attribution_status character varying(30) NOT NULL,
    unallocated_reason_code character varying(100),
    class_attribution_status character varying(30) DEFAULT 'NOT_APPLICABLE'::character varying NOT NULL,
    class_unallocated_reason_code character varying(100),
    request_id text NOT NULL,
    trace_id text NOT NULL,
    idempotency_key text NOT NULL,
    input_token_count bigint DEFAULT 0 NOT NULL,
    output_token_count bigint DEFAULT 0 NOT NULL,
    cached_token_count bigint DEFAULT 0 NOT NULL,
    pricing_status character varying(30) NOT NULL,
    input_unit_price numeric(18,6),
    output_unit_price numeric(18,6),
    cached_input_unit_price numeric(18,6),
    currency_code character varying(3),
    estimated_cost numeric(18,6),
    actual_cost numeric(18,6),
    status character varying(30) NOT NULL,
    failure_code character varying(100),
    latency_ms integer NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT ck_ai_usage_actual_cost_min CHECK ((actual_cost >= (0)::numeric)),
    CONSTRAINT ck_ai_usage_attribution_status CHECK (((attribution_status)::text = ANY ((ARRAY['ALLOCATED'::character varying, 'PARTIALLY_ALLOCATED'::character varying, 'UNALLOCATED'::character varying])::text[]))),
    CONSTRAINT ck_ai_usage_cached_input_unit_price_min CHECK ((cached_input_unit_price >= (0)::numeric)),
    CONSTRAINT ck_ai_usage_cached_token_count_range CHECK (((cached_token_count >= 0) AND (cached_token_count <= input_token_count))),
    CONSTRAINT ck_ai_usage_class_attribution_status CHECK (((class_attribution_status)::text = ANY ((ARRAY['ALLOCATED'::character varying, 'NOT_APPLICABLE'::character varying, 'UNALLOCATED'::character varying])::text[]))),
    CONSTRAINT ck_ai_usage_class_unallocated_reason_code CHECK (((class_unallocated_reason_code)::text = ANY ((ARRAY['CLASS_MEMBERSHIP_NOT_FOUND'::character varying, 'CLASS_CONTEXT_UNRESOLVED'::character varying, 'CLASS_PATH_CONFLICT'::character varying])::text[]))),
    CONSTRAINT ck_ai_usage_context_type CHECK (((context_type)::text = ANY ((ARRAY['SUBMISSION'::character varying, 'CURRICULUM_VERSION'::character varying, 'CURRICULUM_ANALYSIS'::character varying, 'ANALYSIS_JOB'::character varying, 'CODE_ANALYSIS'::character varying, 'ASSESSMENT_SESSION'::character varying, 'ASSESSMENT_PROBLEM'::character varying, 'PROBLEM_STAGE'::character varying, 'INTERVIEW_BRIEF'::character varying, 'REPORT_GENERATION_ITEM'::character varying, 'REPORT_SNAPSHOT'::character varying, 'INTERVENTION'::character varying])::text[]))),
    CONSTRAINT ck_ai_usage_currency_code CHECK (((currency_code)::text = 'USD'::text)),
    CONSTRAINT ck_ai_usage_estimated_cost_min CHECK ((estimated_cost >= (0)::numeric)),
    CONSTRAINT ck_ai_usage_failure_code CHECK (((failure_code)::text = ANY ((ARRAY['TIMEOUT'::character varying, 'RATE_LIMITED'::character varying, 'PROVIDER_ERROR'::character varying, 'INVALID_JSON'::character varying, 'CONTEXT_OVERFLOW'::character varying, 'NO_AVAILABLE_MODEL_INSTANCE'::character varying, 'MODEL_INSTANCE_QUOTA_EXHAUSTED'::character varying, 'MODEL_CREDENTIAL_INVALID'::character varying])::text[]))),
    CONSTRAINT ck_ai_usage_feature_code CHECK (((feature_code)::text = ANY ((ARRAY['CODE_ANALYSIS'::character varying, 'CURRICULUM_ANALYSIS'::character varying, 'CODE_SESSION'::character varying, 'ANSWER_EVALUATION'::character varying, 'INTERVIEW_BRIEF_GENERATION'::character varying, 'REPORT_GENERATION'::character varying])::text[]))),
    CONSTRAINT ck_ai_usage_feature_code_2 CHECK ((((feature_code)::text <> 'CODE_SESSION'::text) OR ((tier_code IS NOT NULL) AND (tier_policy_id IS NOT NULL)))),
    CONSTRAINT ck_ai_usage_feature_code_3 CHECK ((((feature_code)::text <> ALL ((ARRAY['INTERVIEW_BRIEF_GENERATION'::character varying, 'REPORT_GENERATION'::character varying])::text[])) OR ((tier_code IS NULL) AND (tier_policy_id IS NULL)))),
    CONSTRAINT ck_ai_usage_input_token_count_min CHECK ((input_token_count >= 0)),
    CONSTRAINT ck_ai_usage_input_unit_price_min CHECK ((input_unit_price >= (0)::numeric)),
    CONSTRAINT ck_ai_usage_latency_ms_min CHECK ((latency_ms >= 0)),
    CONSTRAINT ck_ai_usage_output_token_count_min CHECK ((output_token_count >= 0)),
    CONSTRAINT ck_ai_usage_output_unit_price_min CHECK ((output_unit_price >= (0)::numeric)),
    CONSTRAINT ck_ai_usage_pricing_status CHECK (((pricing_status)::text = ANY ((ARRAY['PRICED'::character varying, 'UNPRICED'::character varying, 'ACTUAL_COST_ONLY'::character varying])::text[]))),
    CONSTRAINT ck_ai_usage_status CHECK (((status)::text = ANY ((ARRAY['SUCCEEDED'::character varying, 'FAILED'::character varying, 'PARTIAL'::character varying])::text[]))),
    CONSTRAINT ck_ai_usage_tier_code CHECK (((tier_code)::text = ANY ((ARRAY['ACCURACY_FIRST'::character varying, 'BALANCED'::character varying, 'COST_FIRST'::character varying])::text[]))),
    CONSTRAINT ck_ai_usage_trigger_type CHECK (((trigger_type)::text = ANY ((ARRAY['USER'::character varying, 'SCHEDULED'::character varying, 'EVENT'::character varying, 'RETRY'::character varying, 'BATCH'::character varying])::text[]))),
    CONSTRAINT ck_ai_usage_unallocated_reason_code CHECK (((unallocated_reason_code)::text = ANY ((ARRAY['ORG_COMMON'::character varying, 'COHORT_UNRESOLVED'::character varying, 'PROJECT_UNRESOLVED'::character varying, 'CONTEXT_UNRESOLVED'::character varying])::text[])))
);


--
-- Name: TABLE ai_usage; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.ai_usage IS 'AI를 한 번 호출할 때마다 남기는 영수증 같은 실행 원장입니다. 어느 기관에서 어떤 기능을 어떤 논리 모델 코드로 실행했는지, 토큰과 비용, 성공·실패, 기수·반·프로젝트 귀속을 호출 당시 모습으로 보존합니다. | 정의서명: AiUsage | 제약·비고: • APPEND-ONLY 원장, idempotency_key UNIQUE • feature_code: CODE_ANALYSIS / CURRICULUM_ANALYSIS / CODE_SESSION / ANSWER_EVALUATION / INTERVIEW_BRIEF_GENERATION / REPORT_GENERATION • trigger_type: USER / SCHEDULED / EVENT / RETRY / BATCH • attribution_status: ALLOCATED / PARTIALLY_ALLOCATED / UNALLOCATED • class_attribution_status: ALLOCATED / NOT_APPLICABLE / UNALLOCATED • pricing_status: PRICED / UNPRICED / ACTUAL_COST_ONLY • CODE_SESSION이면 tier_code·tier_policy_id 필수이며 INTERVIEW_BRIEF_GENERATION·REPORT_GENERATION이면 둘 다 NULL • ANSWER_EVALUATION이면 grading_policy_id·calibration_version_id 필수 • PRICED이면 입력·출력 단가·currency_code=''USD''·estimated_cost 필수 • UNPRICED이면 단가·통화·추정 비용 NULL, 호출·토큰 원장은 보존 • class_id·project_id가 있으면 cohort_id 필수이며 기관·기수 경로 일치 • cla';


