--
-- Name: analysis_job; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_job (
    job_id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    assessment_round_id uuid NOT NULL,
    team_id uuid NOT NULL,
    submission_id uuid NOT NULL,
    analysis_id uuid,
    question_focus_version_no integer,
    batch_key text NOT NULL,
    job_type character varying(100) NOT NULL,
    execution_no integer NOT NULL,
    status character varying(100) NOT NULL,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    failure_reason text,
    trace_id text NOT NULL,
    external_job_id uuid,
    extraction_scope_id uuid,
    requested_model_id uuid,
    question_budget smallint,
    request_payload jsonb,
    request_payload_hash character(64),
    payload_schema_version integer,
    failure_code character varying(100),
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT ck_analysis_job_execution_no CHECK ((execution_no > 0)),
    CONSTRAINT ck_analysis_job_failure_code CHECK ((((status)::text <> 'FAILED'::text) OR (failure_code IS NOT NULL))),
    CONSTRAINT ck_analysis_job_failure_code_2 CHECK (((failure_code IS NULL) OR ((failure_code)::text = ANY ((ARRAY['SOURCE_UNREACHABLE'::character varying, 'UNSUPPORTED_LANGUAGE'::character varying, 'ANALYSIS_TIMEOUT'::character varying, 'MODEL_ERROR'::character varying, 'TEMPORARY_ERROR'::character varying, 'INVALID_REPOSITORY_URL'::character varying, 'REPO_NOT_FOUND'::character varying, 'REPOSITORY_ACCESS_DENIED'::character varying, 'BRANCH_NOT_FOUND'::character varying, 'UNSUPPORTED_HOST'::character varying, 'FILE_TOO_LARGE'::character varying, 'ARCHIVE_INVALID'::character varying, 'EMPTY_CODE'::character varying, 'PROHIBITED_FILE'::character varying, 'GIT_LOG_MISSING'::character varying])::text[])))),
    CONSTRAINT ck_analysis_job_payload_schema_version CHECK (((payload_schema_version IS NULL) OR (payload_schema_version >= 1))),
    CONSTRAINT ck_analysis_job_question_budget CHECK (((question_budget IS NULL) OR (question_budget > 0))),
    CONSTRAINT ck_analysis_job_request_payload CHECK (((request_payload IS NULL) OR (jsonb_typeof(request_payload) = 'object'::text))),
    CONSTRAINT ck_analysis_job_request_payload_hash CHECK (((request_payload_hash IS NULL) OR (request_payload_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT ck_analysis_job_status CHECK (((status)::text = ANY ((ARRAY['QUEUED'::character varying, 'RUNNING'::character varying, 'SUCCEEDED'::character varying, 'PARTIAL'::character varying, 'FAILED'::character varying])::text[]))),
    CONSTRAINT ck_analysis_job_status_2 CHECK (((((status)::text = 'QUEUED'::text) AND (started_at IS NULL) AND (completed_at IS NULL) AND (failure_reason IS NULL)) OR (((status)::text = 'RUNNING'::text) AND (started_at IS NOT NULL) AND (completed_at IS NULL) AND (failure_reason IS NULL)) OR (((status)::text = ANY ((ARRAY['SUCCEEDED'::character varying, 'PARTIAL'::character varying])::text[])) AND (started_at IS NOT NULL) AND (completed_at IS NOT NULL) AND (failure_reason IS NULL)) OR (((status)::text = 'FAILED'::text) AND (started_at IS NOT NULL) AND (completed_at IS NOT NULL) AND (failure_reason IS NOT NULL))))
);


--
-- Name: TABLE analysis_job; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.analysis_job IS '제출 마감 후 현재 Submission의 확정 분석 입력·귀속·공통 문제 또는 개인 기여도·질문 생성을 단계별로 추적하는 실행·재시도 원장입니다. | 정의서명: AnalysisJob | 제약·비고: • 상태: QUEUED / RUNNING / SUCCEEDED / PARTIAL / FAILED • execution_no > 0, UNIQUE(batch_key, job_type, execution_no) • 같은 batch_key + job_type의 QUEUED/RUNNING 활성 실행은 최대 1건입니다. • 재시도는 기존 행을 갱신하지 않고 execution_no+1의 새 행으로 보존합니다. • batch_key는 assessment_round_id·team_id·submission_id와 실행 목적을 안정적으로 포함합니다. • 작업 생성 시 회차의 현재 유효 질문 초점 전체 집합 version_no를 고정하고 재시도는 원본 버전을 사용합니다. • analysis_id는 성공 결과가 생성된 작업에서만 연결될 수 있으며 같은 회차·팀·source_submission_id 경로와 일치해야 합니다. • 실행 상태·시작·완료·실패는 AnalysisJob이 소유하고 CodeAnalysis에는 실행 상태를 중복 저장하지 않습니다. • AiUsage는 context_type=ANALYSIS_JOB, context_id=job_id 또는 작업 결과 맥락으로 논리 연결합니다. • failure_code는 분석 실행 실패 6종과 저장소 접근 실패 5종, ZIP 검증 실패 5종을 합한 16종입니다. 저장소 접근 주체가 AI 서버로 확정되어 저장소 사유를 별도 필드로 받지 않고 분석 실패 코드에 통합했고(2026-08-06, S-03), ZIP 검증 실패 5종도 같은 이유로 추가했습니다(2026-08-07, S-15). 저장소 5종은 RepositoryVerification.failure_code와, ZIP 5종은 SubmissionArtifact.validation_failure_code와 문자열이 동일하며 해당 사유일 때는 두 곳에 같은 값을 기록합니다.';


