--

COMMENT ON COLUMN public.analysis_job.created_at IS '202 접수 전후를 포함한 작업 생성 시각이다.';


--
-- Name: app_user; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.app_user (
    user_id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid,
    email public.citext NOT NULL,
    normalized_email character varying(320) NOT NULL,
    name character varying(200),
    password_hash character varying(128),
    status character varying(30) DEFAULT 'PENDING'::character varying NOT NULL,
    inactivated_at timestamp with time zone,
    inactivated_by uuid,
    inactivated_reason_code character varying(30),
    inactivated_reason text,
    is_email_verified boolean DEFAULT false NOT NULL,
    email_verified_at timestamp with time zone,
    failed_login_count integer DEFAULT 0 NOT NULL,
    login_blocked_until timestamp with time zone,
    last_login_at timestamp with time zone,
    password_changed_at timestamp with time zone,
    commit_email character varying(320),
    commit_email_normalized character varying(320),
    commit_email_status character varying(30),
    commit_email_verification_method character varying(30),
    commit_email_verified_by uuid,
    commit_email_verified_at timestamp with time zone,
    commit_email_updated_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    deleted_at timestamp with time zone,
    row_version integer DEFAULT 0 NOT NULL,
    role_code character varying(30) NOT NULL,
    CONSTRAINT ck_app_user_commit_email_status CHECK (((commit_email_status)::text = ANY ((ARRAY['PENDING'::character varying, 'VERIFIED'::character varying, 'UNVERIFIED'::character varying])::text[]))),
    CONSTRAINT ck_app_user_commit_email_updated_at CHECK ((((commit_email IS NULL) AND (commit_email_normalized IS NULL) AND (commit_email_status IS NULL) AND (commit_email_verification_method IS NULL) AND (commit_email_verified_by IS NULL) AND (commit_email_verified_at IS NULL) AND (commit_email_updated_at IS NULL)) OR ((commit_email IS NOT NULL) AND (commit_email_normalized IS NOT NULL) AND (commit_email_status IS NOT NULL) AND (commit_email_updated_at IS NOT NULL)))),
    CONSTRAINT ck_app_user_commit_email_verification_method CHECK (((commit_email_verification_method)::text = ANY ((ARRAY['OAUTH'::character varying, 'MANAGER_CONFIRMED'::character varying])::text[]))),
    CONSTRAINT ck_app_user_commit_email_verified_at CHECK (((((commit_email_status)::text = 'VERIFIED'::text) AND (commit_email_verified_at IS NOT NULL)) OR (((commit_email_status)::text IS DISTINCT FROM 'VERIFIED'::text) AND (commit_email_verified_at IS NULL)))),
    CONSTRAINT ck_app_user_failed_login_count CHECK ((failed_login_count >= 0)),
    CONSTRAINT ck_app_user_inactivated_reason_code CHECK (((inactivated_reason_code)::text = ANY ((ARRAY['RESIGNED'::character varying, 'ADMIN_SUSPENDED'::character varying, 'CONTRACT_ENDED'::character varying, 'SECURITY_ACTION'::character varying, 'OTHER'::character varying])::text[]))),
    CONSTRAINT ck_app_user_is_email_verified CHECK ((((is_email_verified = true) AND (email_verified_at IS NOT NULL)) OR ((is_email_verified = false) AND (email_verified_at IS NULL)))),
    CONSTRAINT ck_app_user_role_code CHECK (((role_code)::text = ANY ((ARRAY['SUPER_ADMIN'::character varying, 'OPERATOR'::character varying, 'MANAGER'::character varying, 'TRAINEE'::character varying])::text[]))),
    CONSTRAINT ck_app_user_row_version CHECK ((row_version >= 0)),
    CONSTRAINT ck_app_user_status CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'ACTIVE'::character varying, 'INACTIVE'::character varying])::text[]))),
    CONSTRAINT ck_app_user_status_2 CHECK ((((status)::text = 'PENDING'::text) OR ((name IS NOT NULL) AND (password_hash IS NOT NULL) AND (password_changed_at IS NOT NULL)))),
    CONSTRAINT ck_app_user_status_3 CHECK (((((status)::text = 'INACTIVE'::text) AND (inactivated_at IS NOT NULL) AND (inactivated_by IS NOT NULL) AND (inactivated_reason_code IS NOT NULL)) OR ((status)::text <> 'INACTIVE'::text)))
);


--
-- Name: TABLE app_user; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.app_user IS '플랫폼의 로그인 계정 원장입니다. 사용자 역할과 기관 소속, 계정 생명주기, 이메일 소유 확인, 로그인 지연·비밀번호 변경 기준을 관리하고 교육생 계정에는 현재 Git 커밋 이메일 검증 상태를 함께 보존합니다. | 정의서명: AppUser | 제약·비고: • 상태: PENDING / ACTIVE / INACTIVE • org_id NULL은 기관 미소속 SUPER_ADMIN만 허용하고 OPERATOR·MANAGER·TRAINEE는 기관 소속이 필수입니다. • normalized_email은 로그인·중복 판정용 전체 UNIQUE 값이며 email은 표시·연락용 원문입니다. • PENDING은 명단 등록 후 아직 활성화하지 않은 TRAINEE에만 사용하며 name·password_hash·password_changed_at이 NULL일 수 있습니다. • ACTIVE·INACTIVE는 name·password_hash·password_changed_at이 모두 필수입니다. • ACTIVE이면 is_email_verified=TRUE이고 email_verified_at이 필수입니다. • is_email_verified=TRUE이면 email_verified_at이 필수이고, FALSE이면 email_verified_at은 NULL이어야 합니다. • INACTIVE이면 inactivated_at·inactivated_by·inactivated_reason_code가 필수입니다. • 비활성화 사유: RESIGNED / ADMIN_SUSPENDED / CONTRACT_ENDED / SECURITY_ACTION / OTHER • AUTH_THROTTLED는 계정 상태가 아니라 failed_login_count와 login_blocked_until로 표현합니다. • login_blocked_until';


