--
-- Name: measurement_attempt; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.measurement_attempt (
    attempt_id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    cohort_id uuid NOT NULL,
    assessment_round_id uuid NOT NULL,
    project_id uuid NOT NULL,
    user_id uuid NOT NULL,
    assessment_contract_version character varying(30) DEFAULT 'MEAS_V1'::character varying NOT NULL,
    source_submission_id uuid,
    code_analysis_id uuid,
    attempt_type character varying(100) NOT NULL,
    source_attempt_id uuid,
    attempt_sequence_no integer NOT NULL,
    assigned_at timestamp with time zone,
    assigned_by uuid,
    review_source_report_id uuid,
    review_source_report_snapshot_id uuid,
    review_due_at timestamp with time zone,
    status character varying(100) NOT NULL,
    terminal_reason_code character varying(100),
    terminal_at timestamp with time zone,
    analysis_completed_at timestamp with time zone,
    assessment_open_at timestamp with time zone,
    assessment_close_at timestamp with time zone,
    validity_review_status character varying(100) NOT NULL,
    validity_trigger_reason_code character varying(100),
    validity_decision_reason_code character varying(100),
    validity_decision_note text,
    validity_review_started_at timestamp with time zone,
    validity_reviewed_by uuid,
    validity_reviewed_at timestamp with time zone,
    row_version integer DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    outcome_type_code character varying(100),
    outcome_verdict jsonb,
    outcome_policy_version integer,
    outcome_judged_at timestamp with time zone,
    CONSTRAINT ck_measurement_attempt_assessment_close_at CHECK (((assessment_close_at IS NULL) OR ((assessment_open_at IS NOT NULL) AND (assessment_close_at > assessment_open_at)))),
    CONSTRAINT ck_measurement_attempt_attempt_sequence_no CHECK ((attempt_sequence_no > 0)),
    CONSTRAINT ck_measurement_attempt_attempt_type CHECK (((attempt_type)::text = ANY ((ARRAY['INITIAL'::character varying, 'RETRY'::character varying, 'REVIEW'::character varying])::text[]))),
    CONSTRAINT ck_measurement_attempt_attempt_type_2 CHECK (((((attempt_type)::text = 'INITIAL'::text) AND (source_attempt_id IS NULL) AND (assigned_at IS NULL) AND (assigned_by IS NULL) AND (review_source_report_id IS NULL) AND (review_source_report_snapshot_id IS NULL) AND (review_due_at IS NULL)) OR (((attempt_type)::text = 'RETRY'::text) AND (source_attempt_id IS NOT NULL) AND (review_source_report_id IS NULL) AND (review_source_report_snapshot_id IS NULL) AND (review_due_at IS NULL)) OR (((attempt_type)::text = 'REVIEW'::text) AND (source_attempt_id IS NOT NULL) AND (assigned_at IS NOT NULL) AND (assigned_by IS NOT NULL) AND (review_source_report_id IS NOT NULL) AND (review_source_report_snapshot_id IS NOT NULL) AND (review_due_at IS NOT NULL)))),
    CONSTRAINT ck_measurement_attempt_outcome_initial_only CHECK ((((attempt_type)::text = 'INITIAL'::text) OR ((outcome_type_code IS NULL) AND (outcome_verdict IS NULL) AND (outcome_policy_version IS NULL) AND (outcome_judged_at IS NULL)))),
    CONSTRAINT ck_measurement_attempt_outcome_set CHECK ((((outcome_judged_at IS NULL) AND (outcome_type_code IS NULL) AND (outcome_verdict IS NULL) AND (outcome_policy_version IS NULL)) OR ((outcome_judged_at IS NOT NULL) AND (outcome_verdict IS NOT NULL) AND (outcome_policy_version > 0) AND (jsonb_typeof(outcome_verdict) = 'object'::text)))),
    CONSTRAINT ck_measurement_attempt_outcome_type_code CHECK (((outcome_type_code IS NULL) OR ((outcome_type_code)::text = ANY ((ARRAY['STAGE_DECLINE'::character varying, 'PERSISTENT_LOW'::character varying, 'INVALID_ATTEMPT'::character varying, 'CONTRIBUTION_UNDERSTANDING_GAP'::character varying, 'LOW_PARTICIPATION'::character varying, 'EXCELLENT_TRAINEE'::character varying])::text[])))),
    CONSTRAINT ck_measurement_attempt_status CHECK (((status)::text = ANY ((ARRAY['NOT_STARTED'::character varying, 'SUBMITTED'::character varying, 'ANALYZING'::character varying, 'SESSION_READY'::character varying, 'SESSION_IN_PROGRESS'::character varying, 'COMPLETED'::character varying, 'FAILED'::character varying, 'EXPIRED'::character varying])::text[]))),
    CONSTRAINT ck_measurement_attempt_status_2 CHECK (((((status)::text = ANY ((ARRAY['COMPLETED'::character varying, 'FAILED'::character varying, 'EXPIRED'::character varying])::text[])) AND (terminal_reason_code IS NOT NULL) AND (terminal_at IS NOT NULL)) OR (((status)::text <> ALL ((ARRAY['COMPLETED'::character varying, 'FAILED'::character varying, 'EXPIRED'::character varying])::text[])) AND (terminal_reason_code IS NULL) AND (terminal_at IS NULL)))),
    CONSTRAINT ck_measurement_attempt_terminal_reason_code CHECK (((terminal_reason_code)::text = ANY ((ARRAY['COMPLETED'::character varying, 'NOT_SUBMITTED'::character varying, 'ANALYSIS_FAILED'::character varying, 'INSUFFICIENT_PROBLEM_EVIDENCE'::character varying, 'INSUFFICIENT_OWN_COMMIT_EVIDENCE'::character varying, 'NOT_ATTENDED'::character varying, 'SESSION_INCOMPLETE'::character varying, 'REVIEW_NOT_COMPLETED'::character varying, 'INVALID'::character varying])::text[]))),
    CONSTRAINT ck_measurement_attempt_validity_decision_reason_code CHECK (((validity_decision_reason_code IS NULL) OR ((validity_decision_reason_code)::text = ANY ((ARRAY['REVIEWED_NO_VIOLATION'::character varying, 'REVIEWED_VIOLATION_CONFIRMED'::character varying, 'REVIEWED_INSUFFICIENT_EVIDENCE'::character varying])::text[])))),
    CONSTRAINT ck_measurement_attempt_validity_decision_status_match CHECK (((validity_decision_reason_code IS NULL) OR (((validity_decision_reason_code)::text = 'REVIEWED_VIOLATION_CONFIRMED'::text) AND ((validity_review_status)::text = 'CONFIRMED_INVALID'::text)) OR (((validity_decision_reason_code)::text = ANY ((ARRAY['REVIEWED_NO_VIOLATION'::character varying, 'REVIEWED_INSUFFICIENT_EVIDENCE'::character varying])::text[])) AND ((validity_review_status)::text = 'RESTORED_VALID'::text)))),
    CONSTRAINT ck_measurement_attempt_validity_review_status CHECK (((validity_review_status)::text = ANY ((ARRAY['NOT_REQUIRED'::character varying, 'PENDING'::character varying, 'CONFIRMED_INVALID'::character varying, 'RESTORED_VALID'::character varying])::text[]))),
    CONSTRAINT ck_measurement_attempt_validity_review_status_2 CHECK (((((validity_review_status)::text = ANY ((ARRAY['NOT_REQUIRED'::character varying, 'PENDING'::character varying])::text[])) AND (validity_decision_reason_code IS NULL) AND (validity_reviewed_by IS NULL) AND (validity_reviewed_at IS NULL)) OR (((validity_review_status)::text = ANY ((ARRAY['CONFIRMED_INVALID'::character varying, 'RESTORED_VALID'::character varying])::text[])) AND (validity_decision_reason_code IS NOT NULL) AND (validity_reviewed_by IS NOT NULL) AND (validity_reviewed_at IS NOT NULL)))),
    CONSTRAINT ck_measurement_attempt_validity_trigger_reason_code CHECK (((validity_trigger_reason_code IS NULL) OR ((validity_trigger_reason_code)::text = ANY ((ARRAY['EXCESSIVE_WINDOW_LEAVE'::character varying, 'EXCESSIVE_CONNECTION_LOSS'::character varying, 'MANAGER_MANUAL_FLAG'::character varying])::text[]))))
);


--
-- Name: TABLE measurement_attempt; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.measurement_attempt IS '교육생의 프로젝트 회차별 최초 응시·재시험·다시 보기 수행과 제출·분석·응시 창·종료·무효 확인 현재 상태를 관리하는 개인 수행 SSOT입니다. | 정의서명: MeasurementAttempt | 제약·비고: • attempt_type: INITIAL / RETRY / REVIEW • 상태: NOT_STARTED / SUBMITTED / ANALYZING / SESSION_READY / SESSION_IN_PROGRESS / COMPLETED / FAILED / EXPIRED • UNIQUE(assessment_round_id, user_id) WHERE attempt_type=''INITIAL'' • attempt_sequence_no > 0이며 source_attempt_id가 있으면 같은 사용자·프로젝트·회차의 선행 수행이어야 합니다. • INITIAL은 source_attempt_id·assigned_at·assigned_by·review_source_*·review_due_at이 NULL입니다. • RETRY는 source_attempt_id가 동일 회차 INITIAL 또는 선행 RETRY를 참조하고 재시험 정책에 따른 순번을 가집니다. • REVIEW는 source_attempt_id, assigned_at, assigned_by, review_source_report_id, review_source_report_snapshot_id, review_due_at이 필수입니다. • 회차 OPEN 전환 시 유효 참여 교육생별 INITIAL 수행을 멱등 생성합니다. • 같은 팀의 유효 수행은 동일 source_submission_id와 code_analysis_id를 공유하지만 답변·세션·결과는 개인별로 분리합니다. • analysis_completed_at 확정 시 assessmen • 개인 응시 창은 회차 ProjectAssessmentRound의 공통 창에서 파생하여 실행 당시 값으로 고정합니다: assessment_open_at = MAX(analysis_completed_at, round.assessment_open_at), assessment_close_at = round.assessment_due_at이며 매니저 예외 연장 시에만 후자가 달라집니다. 고정 이후에는 회차 공통 창이 변경되어도 소급하지 않습니다.';


