-- Name: project_assessment_round; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.project_assessment_round (
    assessment_round_id uuid DEFAULT gen_random_uuid() NOT NULL,
    project_id uuid NOT NULL,
    org_id uuid NOT NULL,
    cohort_id uuid NOT NULL,
    concept_set_id uuid,
    round_no integer NOT NULL,
    round_name character varying(200) NOT NULL,
    analysis_role_code character varying(100),
    trigger_type character varying(100) NOT NULL,
    scheduled_at timestamp with time zone,
    submission_due_at timestamp with time zone NOT NULL,
    assessment_open_at timestamp with time zone,
    assessment_due_at timestamp with time zone,
    report_publish_mode character varying(100) NOT NULL,
    report_publish_not_before_at timestamp with time zone,
    is_final boolean NOT NULL,
    status character varying(100) NOT NULL,
    created_by uuid NOT NULL,
    updated_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    deleted_at timestamp with time zone,
    CONSTRAINT ck_project_assessment_round_analysis_role_code CHECK (((analysis_role_code)::text = ANY ((ARRAY['BASELINE'::character varying, 'INTERVENTION_CHECK'::character varying, 'GROWTH_CONFIRMATION'::character varying, 'AD_HOC'::character varying])::text[]))),
    CONSTRAINT ck_project_assessment_round_assessment_open_at CHECK (((assessment_open_at IS NULL) OR (assessment_open_at >= submission_due_at))),
    CONSTRAINT ck_project_assessment_round_assessment_window CHECK (((assessment_due_at IS NULL) OR (assessment_open_at IS NULL) OR (assessment_due_at > assessment_open_at))),
    CONSTRAINT ck_project_assessment_round_report_publish_mode CHECK (((report_publish_mode)::text = 'ROUND_BATCH'::text)),
    CONSTRAINT ck_project_assessment_round_report_publish_not_before_at CHECK (((report_publish_not_before_at IS NULL) OR ((report_publish_not_before_at >= submission_due_at) AND ((assessment_due_at IS NULL) OR (report_publish_not_before_at >= assessment_due_at))))),
    CONSTRAINT ck_project_assessment_round_round_no CHECK ((round_no > 0)),
    CONSTRAINT ck_project_assessment_round_status CHECK (((status)::text = ANY ((ARRAY['PLANNED'::character varying, 'OPEN'::character varying, 'CLOSED'::character varying, 'COMPLETED'::character varying])::text[])))
);


--
-- Name: TABLE project_assessment_round; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.project_assessment_round IS '프로젝트 내부의 코드 제출 마감과 분석 실행 단위를 식별하는 공통 회차 원장입니다. 미니프로젝트는 활성 회차를 정확히 1건만 가지며, 빅프로젝트는 분석 역할이 다른 회차를 1건 이상 운영합니다. 회차 공통 응시 창(assessment_open_at·assessment_due_at)은 본 테이블이 소유하고, 교육생별 확정 창과 매니저 예외 연장은 MeasurementAttempt가 소유합니다. | 정의서명: ProjectAssessmentRound | 제약·비고: • 상태: PLANNED / OPEN / CLOSED / COMPLETED • CLOSED는 회차 공통 응시 마감을 뜻하며 개인 연장 건은 예외로 남을 수 있습니다. • assessment_open_at은 submission_due_at 이후여야 하고 assessment_due_at은 그보다 뒤여야 합니다. • PLANNED가 아닌 상태에서는 두 값이 모두 확정되어 있어야 합니다. • report_publish_not_before_at은 assessment_due_at 이후여야 합니다. • 삭제되지 않은 범위에서 프로젝트별 회차 번호·회차명을 유일하게 유지합니다. • 프로젝트별 삭제되지 않은 최종 회차는 최대 1건입니다. • MINI_PROJECT는 활성 회차 정확히 1건, round_no=1, is_final=TRUE를 요구합니다. • MINI_PROJECT는 OPEN 전이 또는 AnalysisJob 생성 전 concept_set_id를 확정하고 분석 시작 이후 변경하지 않습니다. • BIG_PROJECT는 concept_set_id=NULL, analysis_role_code NOT NULL이며 기본 분석 역할 3개는 프로젝트별 최대 1건입니다. • 분류별 회차 수·경로·기간·개념 세트 조건은 지연 제약 트리거 또는 잠금 기반 서비스 검증으로 강제합니다. • 계획 문제 슬롯 3건의 생성 상태가 모두 확정되고 GENERATED 문제마다 L1~L4 질문 4건과 힌트가 준비된 뒤 세션을 개방합니다. NOT_GENERATED 문제에는 단계 데이터를 요구하지 않습니다.';


