--
-- Name: reminder_dispatch; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.reminder_dispatch (
    dispatch_id uuid DEFAULT gen_random_uuid() NOT NULL,
    assessment_round_id uuid NOT NULL,
    team_id uuid,
    user_id uuid NOT NULL,
    org_id uuid NOT NULL,
    analysis_job_id uuid,
    report_id uuid,
    trigger_type character varying(100) NOT NULL,
    reason_code character varying(100) NOT NULL,
    message_template_code character varying(100) NOT NULL,
    dispatch_batch_id uuid NOT NULL,
    request_idempotency_key text,
    request_fingerprint character(64),
    request_id uuid,
    correlation_id uuid,
    channel character varying(30) NOT NULL,
    status character varying(30) DEFAULT 'PENDING'::character varying NOT NULL,
    suppression_reason_code character varying(100),
    requested_by uuid,
    requested_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    sent_at timestamp with time zone,
    failure_code character varying(100),
    failure_reason text,
    retry_count integer DEFAULT 0 NOT NULL,
    dedupe_key text NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT ck_reminder_dispatch_channel CHECK (((channel)::text = ANY ((ARRAY['EMAIL'::character varying, 'SMS'::character varying, 'PUSH'::character varying])::text[]))),
    CONSTRAINT ck_reminder_dispatch_failure_code CHECK (((failure_code)::text = ANY ((ARRAY['PROVIDER_ERROR'::character varying, 'TIMEOUT'::character varying, 'RATE_LIMITED'::character varying, 'INVALID_RECIPIENT'::character varying, 'TEMPLATE_ERROR'::character varying, 'CHANNEL_UNAVAILABLE'::character varying, 'SOURCE_NOT_READY'::character varying, 'SOURCE_PATH_CONFLICT'::character varying, 'UNKNOWN_ERROR'::character varying])::text[]))),
    CONSTRAINT ck_reminder_dispatch_failure_reason CHECK (((((status)::text = 'FAILED'::text) AND (failure_code IS NOT NULL) AND (failure_reason IS NOT NULL)) OR (((status)::text <> 'FAILED'::text) AND (failure_code IS NULL) AND (failure_reason IS NULL)))),
    CONSTRAINT ck_reminder_dispatch_message_template_code CHECK (((message_template_code)::text = ANY ((ARRAY['TEAM_SUBMISSION_MISSING_V1'::character varying, 'TEAM_ANALYSIS_FAILED_V1'::character varying, 'INDIVIDUAL_ASSESSMENT_NOT_STARTED_V1'::character varying, 'ANALYSIS_COMPLETED_V1'::character varying, 'REPORT_PUBLISHED_V1'::character varying, 'REPORT_RELEASED_V1'::character varying, 'REVIEW_ASSIGNED_V1'::character varying])::text[]))),
    CONSTRAINT ck_reminder_dispatch_reason_code CHECK (((reason_code)::text = ANY ((ARRAY['TEAM_SUBMISSION_MISSING'::character varying, 'TEAM_ANALYSIS_FAILED'::character varying, 'INDIVIDUAL_ASSESSMENT_NOT_STARTED'::character varying, 'ANALYSIS_COMPLETED'::character varying, 'REPORT_PUBLISHED'::character varying, 'REPORT_RELEASED'::character varying, 'REVIEW_ASSIGNED'::character varying])::text[]))),
    CONSTRAINT ck_reminder_dispatch_retry_count CHECK ((retry_count >= 0)),
    CONSTRAINT ck_reminder_dispatch_sent_at CHECK (((((status)::text = 'SENT'::text) AND (sent_at IS NOT NULL)) OR (((status)::text <> 'SENT'::text) AND (sent_at IS NULL)))),
    CONSTRAINT ck_reminder_dispatch_status CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'SENT'::character varying, 'FAILED'::character varying, 'SUPPRESSED'::character varying])::text[]))),
    CONSTRAINT ck_reminder_dispatch_suppression_reason_code CHECK (((suppression_reason_code)::text = ANY ((ARRAY['NUDGE_TARGET_NOT_ELIGIBLE'::character varying, 'NUDGE_TARGET_STATE_CHANGED'::character varying, 'NUDGE_MANAGER_ASSIGNMENT_EXPIRED'::character varying, 'NUDGE_SUBMISSION_DEADLINE_PASSED'::character varying, 'NUDGE_ASSESSMENT_WINDOW_CLOSED'::character varying, 'NUDGE_DUPLICATE_SUPPRESSED'::character varying, 'NOTIFICATION_DUPLICATE_SUPPRESSED'::character varying, 'NUDGE_RECIPIENT_CHANNEL_UNAVAILABLE'::character varying])::text[]))),
    CONSTRAINT ck_reminder_dispatch_trigger_type CHECK (((trigger_type)::text = ANY ((ARRAY['USER_REQUESTED'::character varying, 'SYSTEM_EVENT'::character varying])::text[])))
);


--
-- Name: TABLE reminder_dispatch; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.reminder_dispatch IS '매니저가 요청한 미제출·분석 실패·미응시 독촉과 시스템이 발생시킨 분석 준비 완료·리포트 발행/공개·다시 보기 배정 알림을 수신자별로 기록하는 발송 원장입니다. 외부 발송 성공·실패·억제·재시도만 소유하며 제출·분석·응시·리포트의 업무 상태를 변경하지 않습니다. | 정의서명: ReminderDispatch | 제약·비고: • assessment_round_id는 모든 발송의 필수 프로젝트 평가 회차 FK입니다. • trigger_type: USER_REQUESTED / SYSTEM_EVENT • reason_code: TEAM_SUBMISSION_MISSING / TEAM_ANALYSIS_FAILED / INDIVIDUAL_ASSESSMENT_NOT_STARTED / ANALYSIS_COMPLETED / REPORT_PUBLISHED / REPORT_RELEASED / REVIEW_ASSIGNED • message_template_code는 사유별 버전형 템플릿 7종을 사용하고 사용자 자유 문구를 저장하지 않습니다. • USER_REQUESTED이면 requested_by·request_idempotency_key·request_fingerprint가 필수입니다. • SYSTEM_EVENT이면 requested_by·request_idempotency_key·request_fingerprint는 NULL이며 원천 이벤트 식별값으로 배치와 dedupe_key를 구성합니다. • request_id·correlation_id는 API·로그 추적용이며 발송 결과 재조회 식별자는 dispatch_batch_id입니다. • 같은 org_id·requested_by·request_idempotency_key는 하나의 요청 지문과 dispatch_batch_id에만 대응해야 합니다. • TEAM_S';


