CREATE TABLE public.report (
    report_id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    cohort_id uuid NOT NULL,
    class_id uuid,
    user_id uuid,
    assessment_round_id uuid,
    report_type character varying(100) NOT NULL,
    lifecycle_status character varying(30) NOT NULL,
    scheduled_publish_at timestamp with time zone,
    published_at timestamp with time zone,
    trainee_release_status character varying(100) NOT NULL,
    trainee_disclosure_scope character varying(100),
    trainee_released_at timestamp with time zone,
    trainee_released_by uuid,
    CONSTRAINT ck_report_assessment_round_id CHECK (((((report_type)::text = ANY ((ARRAY['COHORT_CURRICULUM_DIAGNOSIS'::character varying, 'COHORT_OUTCOME'::character varying])::text[])) AND (class_id IS NULL) AND (user_id IS NULL) AND (assessment_round_id IS NULL)) OR ((user_id IS NOT NULL) AND (assessment_round_id IS NOT NULL) AND (class_id IS NULL)) OR ((class_id IS NOT NULL) AND (assessment_round_id IS NOT NULL) AND (user_id IS NULL)))),
    CONSTRAINT ck_report_lifecycle_status CHECK (((lifecycle_status)::text = ANY ((ARRAY['DRAFT'::character varying, 'ACTIVE'::character varying, 'SUPERSEDED'::character varying])::text[]))),
    CONSTRAINT ck_report_published_at CHECK (((scheduled_publish_at IS NULL) OR (published_at IS NULL) OR (published_at >= scheduled_publish_at))),
    CONSTRAINT ck_report_report_type CHECK (((report_type)::text = ANY ((ARRAY['COHORT_SUMMARY'::character varying, 'CHECKPOINT'::character varying, 'TRAINEE_FINAL'::character varying, 'COHORT_CURRICULUM_DIAGNOSIS'::character varying, 'COHORT_OUTCOME'::character varying])::text[]))),
    CONSTRAINT ck_report_trainee_disclosure_scope CHECK (((trainee_disclosure_scope)::text = ANY ((ARRAY['PRIVATE'::character varying, 'SUMMARY'::character varying, 'FULL'::character varying])::text[]))),
    CONSTRAINT ck_report_trainee_release_status CHECK (((trainee_release_status)::text = ANY ((ARRAY['NOT_CONFIGURED'::character varying, 'WITHHELD'::character varying, 'RELEASED'::character varying])::text[]))),
    CONSTRAINT ck_report_trainee_release_status_2 CHECK (((((trainee_release_status)::text = 'NOT_CONFIGURED'::text) AND (trainee_disclosure_scope IS NULL) AND (trainee_released_at IS NULL) AND (trainee_released_by IS NULL)) OR (((trainee_release_status)::text = 'WITHHELD'::text) AND ((trainee_disclosure_scope)::text = 'PRIVATE'::text) AND (trainee_released_at IS NULL) AND (trainee_released_by IS NULL)) OR (((trainee_release_status)::text = 'RELEASED'::text) AND ((trainee_disclosure_scope)::text = ANY ((ARRAY['SUMMARY'::character varying, 'FULL'::character varying])::text[])) AND (trainee_released_at IS NOT NULL) AND (trainee_released_by IS NOT NULL))))
);


--
-- Name: TABLE report; Type: COMMENT; Schema: public; Owner: -
