--
-- Name: curriculum_reanalysis_impact_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.curriculum_reanalysis_impact_view AS
 SELECT m.org_id,
    m.material_id,
    v.version_id,
    COALESCE(x.linked_project_count, 0) AS linked_project_count,
    COALESCE(x.affected_round_count, 0) AS affected_round_count,
    COALESCE(x.running_round_count, 0) AS running_round_count,
    COALESCE(x.started_trainee_count, 0) AS started_trainee_count,
    COALESCE(x.generated_problem_count, 0) AS generated_problem_count,
    COALESCE(x.generated_report_count, 0) AS generated_report_count,
    COALESCE(x.published_report_count, 0) AS published_report_count,
    (COALESCE(x.affected_rounds, '[]'::jsonb))::text AS affected_rounds,
    ((COALESCE(x.started_trainee_count, 0) > 0) OR (COALESCE(x.published_report_count, 0) > 0)) AS requires_confirmation,
    array_remove(ARRAY[
        CASE
            WHEN (COALESCE(x.started_trainee_count, 0) > 0) THEN 'ASSESSMENT_ALREADY_STARTED'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (COALESCE(x.published_report_count, 0) > 0) THEN 'REPORT_ALREADY_PUBLISHED'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (COALESCE(x.running_round_count, 0) > 0) THEN 'ROUND_IN_PROGRESS'::text
            ELSE NULL::text
        END], NULL::text) AS confirmation_reason_codes,
    'COMPLETE'::character varying(20) AS aggregation_status,
    CURRENT_TIMESTAMP AS calculated_at
   FROM ((public.curriculum_version v
     JOIN public.curriculum_material m ON ((m.material_id = v.material_id)))
     LEFT JOIN LATERAL ( SELECT (count(DISTINCT p.project_id))::integer AS linked_project_count,
            (count(DISTINCT r.assessment_round_id))::integer AS affected_round_count,
            (count(DISTINCT r.assessment_round_id) FILTER (WHERE ((r.status)::text = ANY ((ARRAY['OPEN'::character varying, 'RUNNING'::character varying])::text[]))))::integer AS running_round_count,
            (count(DISTINCT ma.user_id) FILTER (WHERE ((ma.status)::text <> 'NOT_STARTED'::text)))::integer AS started_trainee_count,
            (count(DISTINCT ap.problem_id))::integer AS generated_problem_count,
            (count(DISTINCT rpt.report_id))::integer AS generated_report_count,
            (count(DISTINCT rpt.report_id) FILTER (WHERE (rpt.published_at IS NOT NULL)))::integer AS published_report_count,
            jsonb_agg(DISTINCT jsonb_build_object('assessmentRoundId', r.assessment_round_id, 'projectId', p.project_id, 'projectName', p.name, 'roundNo', r.round_no, 'roundName', r.round_name, 'status', r.status)) FILTER (WHERE (r.assessment_round_id IS NOT NULL)) AS affected_rounds
           FROM (((((public.project_curriculum pc
             JOIN public.project p ON ((p.project_id = pc.project_id)))
             LEFT JOIN public.project_assessment_round r ON (((r.project_id = p.project_id) AND (r.deleted_at IS NULL))))
             LEFT JOIN public.measurement_attempt ma ON ((ma.assessment_round_id = r.assessment_round_id)))
             LEFT JOIN public.assessment_problem ap ON (((ap.measurement_attempt_id = ma.attempt_id) OR (ap.code_analysis_id = ma.code_analysis_id))))
             LEFT JOIN public.report rpt ON ((rpt.assessment_round_id = r.assessment_round_id)))
          WHERE (pc.curriculum_version_id = v.version_id)) x ON (true))
  WHERE (m.deleted_at IS NULL);


