    CONSTRAINT ck_curriculum_teaches_mapping_mapping_status CHECK (((mapping_status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'REVIEW_REQUIRED'::character varying, 'INACTIVE'::character varying])::text[]))),
