--

COMMENT ON COLUMN public.project_verification_concept_set.change_reason IS '개념 세트 교체 사유이다.';


--
-- Name: COLUMN project_verification_concept_set.created_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.project_verification_concept_set.created_at IS '개념 세트 생성 시각이다.';


--
-- Name: curriculum_version_project_usage_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.curriculum_version_project_usage_view AS
 SELECT m.org_id,
    m.material_id,
    v.version_id,
    v.version_no,
    (m.title)::text AS curriculum_title,
    p.project_id,
    p.sequence_no AS project_sequence_no,
    p.name AS project_name,
    p.project_category,
    p.lifecycle_status AS project_status,
    p.cohort_id,
    co.name AS cohort_name,
    (
        CASE
            WHEN (pc.project_curriculum_id IS NULL) THEN 'NOT_SELECTED'::text
            WHEN ((v.status)::text = 'ACTIVE'::text) THEN 'SELECTED_ACTIVE'::text
            ELSE 'SELECTED_INACTIVE'::text
        END)::character varying(100) AS current_version_selection_status,
    cs.concept_set_id AS active_concept_set_id,
    COALESCE(con.selected_mapping_count, 0) AS selected_mapping_count,
    COALESCE(con.items, '[]'::jsonb) AS selected_concepts,
    rd.assessment_round_id AS display_round_id,
    rd.round_no AS display_round_no,
    rd.round_name AS display_round_name,
    rd.status AS display_round_status,
    COALESCE(st.eligible_count, 0) AS eligible_trainee_count,
    COALESCE(st.attempted_count, 0) AS attempted_trainee_count,
    COALESCE(st.completed_count, 0) AS completed_trainee_count,
    ((p.lifecycle_status)::text <> 'CLOSED'::text) AS can_open_project,
    (
        CASE
            WHEN ((p.lifecycle_status)::text = 'CLOSED'::text) THEN 'PROJECT_CLOSED'::text
            WHEN ((v.status)::text <> 'ACTIVE'::text) THEN 'CURRICULUM_VERSION_INACTIVE'::text
            ELSE NULL::text
        END)::character varying(100) AS open_block_reason_code,
    'COMPLETE'::character varying(20) AS aggregation_status,
    CURRENT_TIMESTAMP AS as_of_at
   FROM ((((((((public.curriculum_material m
     JOIN public.curriculum_version v ON ((v.material_id = m.material_id)))
     JOIN public.project_curriculum pc ON ((pc.curriculum_version_id = v.version_id)))
     JOIN public.project p ON (((p.project_id = pc.project_id) AND (p.deleted_at IS NULL))))
     JOIN public.cohort co ON ((co.cohort_id = p.cohort_id)))
     LEFT JOIN LATERAL ( SELECT x.concept_set_id,
            x.project_id,
            x.org_id,
            x.version_no,
            x.status,
            x.effective_from,
            x.effective_to,
            x.created_by,
            x.change_reason,
            x.created_at
           FROM public.project_verification_concept_set x
          WHERE ((x.project_id = p.project_id) AND ((x.status)::text = 'ACTIVE'::text))
          ORDER BY x.version_no DESC
         LIMIT 1) cs ON (true))
     LEFT JOIN LATERAL ( SELECT (count(*))::integer AS selected_mapping_count,
            jsonb_agg(jsonb_build_object('projectConceptId', x.project_concept_id, 'teachesId', x.teaches_id, 'mappingId', x.source_mapping_id, 'sequenceNo', x.sequence_no, 'name', t.canonical_name) ORDER BY x.sequence_no) AS items
           FROM (public.project_verification_concept x
             LEFT JOIN public.teaches t ON ((t.teaches_id = x.teaches_id)))
          WHERE (x.concept_set_id = cs.concept_set_id)) con ON (true))
     LEFT JOIN LATERAL ( SELECT x.assessment_round_id,
            x.project_id,
            x.org_id,
            x.cohort_id,
            x.concept_set_id,
            x.round_no,
            x.round_name,
            x.analysis_role_code,
            x.trigger_type,
            x.scheduled_at,
            x.submission_due_at,
            x.assessment_open_at,
            x.assessment_due_at,
            x.report_publish_mode,
            x.report_publish_not_before_at,
            x.is_final,
            x.status,
            x.created_by,
            x.updated_by,
            x.created_at,
            x.updated_at,
            x.deleted_at
           FROM public.project_assessment_round x
          WHERE ((x.project_id = p.project_id) AND (x.deleted_at IS NULL))
          ORDER BY
                CASE
                    WHEN ((x.status)::text = ANY ((ARRAY['OPEN'::character varying, 'PLANNED'::character varying])::text[])) THEN 0
                    ELSE 1
                END, x.round_no DESC
         LIMIT 1) rd ON (true))
     LEFT JOIN LATERAL ( SELECT (( SELECT count(*) AS count
                   FROM public.project_membership pm
                  WHERE ((pm.project_id = p.project_id) AND ((pm.status)::text = 'ACTIVE'::text))))::integer AS eligible_count,
            (count(DISTINCT ma.user_id) FILTER (WHERE (ma.attempt_id IS NOT NULL)))::integer AS attempted_count,
            (count(DISTINCT ma.user_id) FILTER (WHERE ((ma.status)::text = 'COMPLETED'::text)))::integer AS completed_count
           FROM public.measurement_attempt ma
          WHERE (ma.assessment_round_id = rd.assessment_round_id)) st ON (true))
  WHERE (m.deleted_at IS NULL);


--
-- Name: interview; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.interview (
    interview_id uuid DEFAULT gen_random_uuid() NOT NULL,
    candidate_id uuid NOT NULL,
    org_id uuid NOT NULL,
    cohort_id uuid NOT NULL,
    class_id uuid NOT NULL,
    target_user_id uuid NOT NULL,
    assessment_round_id uuid NOT NULL,
    assignee_id uuid NOT NULL,
    status character varying(100) NOT NULL,
    planned_at timestamp with time zone,
    started_at timestamp with time zone,
    started_by uuid,
    completed_at timestamp with time zone,
    completed_by uuid,
    result_summary text,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    row_version integer DEFAULT 0 NOT NULL,
    CONSTRAINT ck_interview_status CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'IN_PROGRESS'::character varying, 'COMPLETED'::character varying])::text[]))),
    CONSTRAINT ck_interview_status_2 CHECK (((((status)::text = 'PENDING'::text) AND (started_at IS NULL) AND (started_by IS NULL) AND (completed_at IS NULL) AND (completed_by IS NULL)) OR (((status)::text = 'IN_PROGRESS'::text) AND (started_at IS NOT NULL) AND (started_by IS NOT NULL) AND (completed_at IS NULL) AND (completed_by IS NULL)) OR (((status)::text = 'COMPLETED'::text) AND (started_at IS NOT NULL) AND (started_by IS NOT NULL) AND (completed_at IS NOT NULL) AND (completed_by IS NOT NULL) AND (completed_at >= started_at))))
);


--
-- Name: TABLE interview; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.interview IS '매니저가 면담 후보에서 확정한 교육생 면담의 담당자·예정·시작·종결 상태를 관리하는 원장입니다. | 정의서명: Interview | 제약·비고: • InterviewCandidate 1:0..1이며 candidate_id UNIQUE입니다. • status: PENDING / IN_PROGRESS / COMPLETED • PENDING은 시작·종결 시각과 처리자가 NULL입니다. • IN_PROGRESS는 started_at·started_by가 필수이고 종결 속성은 NULL입니다. • COMPLETED는 시작·종결 시각과 started_by·completed_by가 필수입니다. • 후보가 ELIGIBLE이고 현재 자격·배정 범위가 유효할 때만 생성하며 후보 상태 INTERVIEW_CREATED와 원자적으로 커밋합니다. • 화면은 진행 중 단계를 노출하지 않고 [저장하고 종결] 한 번으로 면담을 마치므로 PENDING→COMPLETED 직행 전이를 허용합니다. IN_PROGRESS는 건너뛸 수 있는 선택 상태입니다. • 직행 종결 시에도 ck_interview_status_2의 COMPLETED 조건을 만족해야 하므로 started_at·started_by를 같은 트랜잭션에서 함께 채웁니다. started_at은 매니저가 브리프를 연 시각을 알 수 없으면 completed_at과 같은 값으로 기록하고 started_by는 completed_by와 같습니다. • 직행 종결은 InterviewStatusHistory에 PENDING→COMPLETED 1행으로 남기며 존재하지 않은 IN_PROGRESS 전이를 만들어 넣지 않습니다. • InterviewSource·InterviewBrief·InterviewActivity·InterviewCause의 부모입니다.';


