-- Name: interview_brief; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.interview_brief (
    brief_id uuid DEFAULT gen_random_uuid() NOT NULL,
    interview_id uuid NOT NULL,
    org_id uuid NOT NULL,
    cohort_id uuid NOT NULL,
    user_id uuid NOT NULL,
    assessment_round_id uuid NOT NULL,
    brief_type character varying(100) NOT NULL,
    version_no integer NOT NULL,
    is_first_interview boolean NOT NULL,
    brief_generation_policy_version integer NOT NULL,
    status character varying(100) NOT NULL,
    manager_note text,
    opening_remark_text text,
    opening_remark_generated_at timestamp with time zone,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by uuid,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    confirmed_by uuid,
    confirmed_at timestamp with time zone,
    row_version integer DEFAULT 0 NOT NULL,
    last_request_id uuid,
    last_request_fingerprint character varying(128),
    CONSTRAINT ck_interview_brief_brief_type CHECK (((brief_type)::text = ANY ((ARRAY['STANDARD'::character varying, 'INVALID_ATTEMPT'::character varying])::text[]))),
    CONSTRAINT ck_interview_brief_last_request_id CHECK ((((last_request_id IS NULL) AND (last_request_fingerprint IS NULL)) OR ((last_request_id IS NOT NULL) AND (last_request_fingerprint IS NOT NULL)))),
    CONSTRAINT ck_interview_brief_opening_remark_text CHECK ((((opening_remark_text IS NULL) AND (opening_remark_generated_at IS NULL)) OR ((opening_remark_text IS NOT NULL) AND (opening_remark_generated_at IS NOT NULL)))),
    CONSTRAINT ck_interview_brief_status CHECK (((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'CONFIRMED'::character varying, 'SUPERSEDED'::character varying])::text[]))),
    CONSTRAINT ck_interview_brief_status_2 CHECK (((((status)::text = 'DRAFT'::text) AND (confirmed_by IS NULL) AND (confirmed_at IS NULL)) OR (((status)::text = 'CONFIRMED'::text) AND (confirmed_by IS NOT NULL) AND (confirmed_at IS NOT NULL)) OR ((status)::text = 'SUPERSEDED'::text))),
    CONSTRAINT ck_interview_brief_version_no CHECK ((version_no > 0))
);


--
-- Name: TABLE interview_brief; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.interview_brief IS '면담 여는 말과 확인 질문 집합·첫 면담 여부·생성 정책과 저장·확정 버전을 관리합니다. Report와 독립된 INTV 원장입니다. | 정의서명: InterviewBrief | 제약·비고: • UNIQUE(interview_id, version_no), version_no > 0 • status: DRAFT / CONFIRMED / SUPERSEDED • 면담별 현재 DRAFT와 CONFIRMED는 각각 최대 1건입니다. • DRAFT는 confirmed_by·confirmed_at이 NULL이고 CONFIRMED는 둘 다 필수입니다. • 새 DRAFT 생성만으로 기존 CONFIRMED를 대체하지 않으며 새 버전 확정 성공 시에만 이전 CONFIRMED를 SUPERSEDED로 전환합니다. • PENDING 면담에서만 초기화·저장·확정을 허용하고 IN_PROGRESS·COMPLETED에서는 읽기 전용입니다. 단 PENDING→COMPLETED 직행 종결 트랜잭션 안에서는 상태 전이 직전에 마지막 확정을 허용합니다. 종결이 커밋된 뒤에는 예외 없이 읽기 전용입니다. • 면담 종결 후에는 새 DRAFT·새 버전을 만들지 않습니다. 종결된 면담을 다시 열어 수정하는 대상은 브리프(여는 말·확인 질문)가 아니라 면담 기록인 InterviewCause와 InterviewActivity이며, 브리프 버전은 종결 시점 그대로 고정됩니다. • 면담 시작 또는 직행 종결 직전 같은 면담의 CONFIRMED 브리프 정확히 1건과 선택 항목 1건 이상, 원천 정합성을 잠금 재검증합니다. • 첫 면담 여부와 브리프 생성 정책 버전을 생성 시점에 고정합니다. • 여는 말과 확인 질문은 같은 AI 호출 1회로 생성하며 AiUsage 1행과 브리프 1버전이 1:1 대응합니다. • opening_remark_text와 opening_remark_generated_at은 함께 존재하거나 함께 NULL입니다. • org_id·cohort_id·user_id·assessment_round_id는 RLS와 조회 성능을 위한 의도적 비정규화이며 Interview 경로와 일치해야 합니다. • 면담에서 난이도를 기록하지 않으므로 난이도 척도 버전을 보유하지 않습니다. • 요청 ID와 지문으로 저장·확정 멱등성을 검증하며 같은 ID의 다른 payload를 거부합니다.';


