--
-- Name: interview_candidate_reason; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.interview_candidate_reason (
    candidate_reason_id uuid DEFAULT gen_random_uuid() NOT NULL,
    candidate_id uuid NOT NULL,
    reason_code character varying(100) NOT NULL,
    evaluation_status character varying(100) NOT NULL,
    not_applicable_reason_code character varying(100),
    reason_status character varying(100) NOT NULL,
    effective_from timestamp with time zone NOT NULL,
    effective_to timestamp with time zone,
    resolution_code character varying(100),
    source_assessment_round_id uuid NOT NULL,
    source_attempt_id uuid,
    source_session_id uuid,
    source_problem_id uuid,
    source_problem_stage_id uuid,
    reason_summary text,
    policy_version integer NOT NULL,
    detected_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    row_version integer DEFAULT 0 NOT NULL,
    CONSTRAINT ck_interview_candidate_reason_evaluation_status CHECK (((evaluation_status)::text = ANY ((ARRAY['MATCHED'::character varying, 'NOT_MATCHED'::character varying, 'NOT_APPLICABLE'::character varying, 'UNAVAILABLE'::character varying])::text[]))),
    CONSTRAINT ck_interview_candidate_reason_evaluation_status_2 CHECK (((((evaluation_status)::text = 'NOT_APPLICABLE'::text) AND (not_applicable_reason_code IS NOT NULL)) OR (((evaluation_status)::text <> 'NOT_APPLICABLE'::text) AND (not_applicable_reason_code IS NULL)))),
    CONSTRAINT ck_interview_candidate_reason_not_applicable_reason_code CHECK (((not_applicable_reason_code)::text = ANY ((ARRAY['FIRST_MINI_PROJECT'::character varying, 'INSUFFICIENT_LONGITUDINAL_HISTORY'::character varying])::text[]))),
    CONSTRAINT ck_interview_candidate_reason_reason_code CHECK (((reason_code)::text = ANY ((ARRAY['STAGE_DECLINE'::character varying, 'PERSISTENT_LOW'::character varying, 'INVALID_ATTEMPT'::character varying, 'CONTRIBUTION_UNDERSTANDING_GAP'::character varying, 'LOW_PARTICIPATION'::character varying])::text[]))),
    CONSTRAINT ck_interview_candidate_reason_reason_status CHECK (((reason_status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'RESOLVED'::character varying, 'SUPERSEDED'::character varying])::text[]))),
    CONSTRAINT ck_interview_candidate_reason_reason_status_2 CHECK (((((reason_status)::text = 'ACTIVE'::text) AND (effective_to IS NULL) AND (resolution_code IS NULL)) OR (((reason_status)::text = 'RESOLVED'::text) AND (effective_to IS NOT NULL) AND (resolution_code IS NOT NULL) AND (effective_to > effective_from)) OR ((reason_status)::text = 'SUPERSEDED'::text))),
    CONSTRAINT ck_interview_candidate_reason_reason_status_3 CHECK (((effective_to IS NULL) OR (effective_to > effective_from)))
);


--
-- Name: TABLE interview_candidate_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.interview_candidate_reason IS '하나의 면담 후보에 동시에 일치할 수 있는 복수 위험 유형과 평가 상태·수명주기·MEAS 원천 추적을 보존합니다. | 정의서명: InterviewCandidateReason | 제약·비고: • reason_code: STAGE_DECLINE / PERSISTENT_LOW / INVALID_ATTEMPT / CONTRIBUTION_UNDERSTANDING_GAP / LOW_PARTICIPATION • evaluation_status: MATCHED / NOT_MATCHED / NOT_APPLICABLE / UNAVAILABLE • reason_status: ACTIVE / RESOLVED / SUPERSEDED • 동일 후보·사유·원천의 ACTIVE 행 중복을 금지합니다. • ACTIVE에서는 effective_to·resolution_code가 NULL이고 RESOLVED에서는 둘 다 필수입니다. • 첫 미니프로젝트 단계 하락은 NOT_APPLICABLE/FIRST_MINI_PROJECT, 지속 저점은 이력 부족 시 NOT_APPLICABLE/INSUFFICIENT_LONGITUDINAL_HISTORY입니다. • CONFIRMED_INVALID에서 INVALID_ATTEMPT ACTIVE 사유를 멱등 생성하고 RESTORED_VALID에서는 삭제하지 않고 RESOLVED로 전환합니다. • 평가 실패·준비 중에는 placeholder 후보 사유를 만들지 않고 View 원천 상태로 표현합니다. • 유형 판정의 원장은 MeasurementAttempt.outcome_type_code·outcome_verdict이며 이 테이블은 그 판정에서 파생한 면담 후보 사유입니다. 판정식을 여기에 다시 구현하지 않고 outcome_verdict.types의 MATCHED·NOT_APPLICABLE 항목만 옮겨 적습니다. • 같은 이유로 policy_version은 MeasurementAttempt.outcome_policy_version을 그대로 복사합니다. • 등재는 INITIAL 수행이 판정된 뒤에만 수행하며 동일 후보·사유·source_attempt_id의 ACTIVE 행을 중복 생성하지 않습니다. • resolution_code: VALIDITY_RESTORED(무효 확인이 RESTORED_VALID로 뒤집힘) / RETRY_PASSED(재시험에서 게이트를 만든 문제가 전부 2단 이상 도달). 폐쇄형 목록이 확정되기 전이라 임의 DB CHECK로 고정하지 않습니다.';


