-- Name: interview_source; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.interview_source (
    interview_source_id uuid DEFAULT gen_random_uuid() NOT NULL,
    interview_id uuid NOT NULL,
    source_type character varying(100) NOT NULL,
    candidate_reason_id uuid,
    attempt_id uuid,
    session_id uuid,
    problem_id uuid,
    problem_stage_id uuid,
    observation_note_id uuid,
    source_summary_snapshot jsonb,
    source_status_snapshot jsonb,
    source_row_version_snapshot jsonb,
    validity_review_status_snapshot jsonb,
    validity_decision_reason_code_snapshot jsonb,
    source_captured_at timestamp with time zone NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT ck_interview_source_source_type CHECK ((num_nonnulls(candidate_reason_id, attempt_id, session_id, problem_id, problem_stage_id, observation_note_id) = 1)),
    CONSTRAINT ck_interview_source_source_type_2 CHECK (((((source_type)::text = 'CANDIDATE_REASON'::text) AND (candidate_reason_id IS NOT NULL)) OR (((source_type)::text = 'MEASUREMENT_ATTEMPT'::text) AND (attempt_id IS NOT NULL)) OR (((source_type)::text = 'ASSESSMENT_SESSION'::text) AND (session_id IS NOT NULL)) OR (((source_type)::text = 'ASSESSMENT_PROBLEM'::text) AND (problem_id IS NOT NULL)) OR (((source_type)::text = 'PROBLEM_STAGE'::text) AND (problem_stage_id IS NOT NULL)) OR (((source_type)::text = 'OBSERVATION_NOTE'::text) AND (observation_note_id IS NOT NULL)))),
    CONSTRAINT ck_interview_source_source_type_value CHECK (((source_type)::text = ANY ((ARRAY['CANDIDATE_REASON'::character varying, 'MEASUREMENT_ATTEMPT'::character varying, 'ASSESSMENT_SESSION'::character varying, 'ASSESSMENT_PROBLEM'::character varying, 'PROBLEM_STAGE'::character varying, 'OBSERVATION_NOTE'::character varying])::text[]))),
    CONSTRAINT ck_interview_source_type_slot_match CHECK (((((source_type)::text = 'CANDIDATE_REASON'::text) AND (candidate_reason_id IS NOT NULL)) OR (((source_type)::text = 'MEASUREMENT_ATTEMPT'::text) AND (attempt_id IS NOT NULL)) OR (((source_type)::text = 'ASSESSMENT_SESSION'::text) AND (session_id IS NOT NULL)) OR (((source_type)::text = 'ASSESSMENT_PROBLEM'::text) AND (problem_id IS NOT NULL)) OR (((source_type)::text = 'PROBLEM_STAGE'::text) AND (problem_stage_id IS NOT NULL)) OR (((source_type)::text = 'OBSERVATION_NOTE'::text) AND (observation_note_id IS NOT NULL))))
);


--
-- Name: TABLE interview_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.interview_source IS '면담 확정 당시 후보 사유·MEAS 결과·수동 관찰 근거와 원천 상태 스냅샷을 보존하여 이후 원천 해소와 당시 판단을 함께 재현합니다. | 정의서명: InterviewSource | 제약·비고: • Interview 1:N • source_type별 허용 형식화 FK 중 정확히 1건만 채우도록 CHECK 또는 지연 제약으로 강제합니다. • 원천과 Interview의 기관·기수·교육생·평가 회차 경로가 일치해야 합니다. • 후보 사유·무효 확인·답변 결과가 이후 변경되더라도 포착 당시 요약·상태·행 버전을 수정하지 않습니다. • InterviewBriefItem은 같은 interview_id의 InterviewSource만 참조할 수 있습니다. • ProblemStage의 질문·힌트·각 답변 원문을 자동 복제하지 않고 접근 가능한 요약·상태·행 버전 스냅샷만 보존합니다. • source_type은 폐쇄형 6종이며 참조 테이블 이름을 값으로 씁니다(2026-08-15 확정, ck_interview_source_source_type_value). • source_type과 채워진 FK가 서로 가리키는 대상이 같아야 합니다(ck_interview_source_source_type_2). • 근거 없는 브리프 질문은 InterviewSource 행을 만들지 않고 InterviewBriefItem에서 source_type GENERAL·RAPPORT + interview_source_id NULL로 표현합니다.';


