--
-- Name: problem_stage; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.problem_stage (
    problem_stage_id uuid DEFAULT gen_random_uuid() NOT NULL,
    session_id uuid NOT NULL,
    problem_id uuid NOT NULL,
    source_problem_stage_id uuid,
    axis_code character varying(10) NOT NULL,
    question_sequence_no integer NOT NULL,
    question_text text NOT NULL,
    question_answer_text text,
    question_score smallint,
    question_passed boolean,
    first_hint_text text NOT NULL,
    first_hint_answer_text text,
    first_hint_score smallint,
    first_hint_passed boolean,
    second_hint_text text NOT NULL,
    second_hint_answer_text text,
    second_hint_score smallint,
    second_hint_passed boolean,
    status character varying(30) DEFAULT 'PREPARED'::character varying NOT NULL,
    question_presented_at timestamp with time zone,
    question_answered_at timestamp with time zone,
    first_hint_presented_at timestamp with time zone,
    first_hint_answered_at timestamp with time zone,
    second_hint_presented_at timestamp with time zone,
    second_hint_answered_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    row_version bigint DEFAULT 0 NOT NULL,
    is_flagged boolean DEFAULT false NOT NULL,
    question_away_count integer DEFAULT 0 NOT NULL,
    question_away_seconds integer DEFAULT 0 NOT NULL,
    question_first_keystroke_delay_ms integer,
    first_hint_away_count integer DEFAULT 0 NOT NULL,
    first_hint_away_seconds integer DEFAULT 0 NOT NULL,
    first_hint_first_keystroke_delay_ms integer,
    second_hint_away_count integer DEFAULT 0 NOT NULL,
    second_hint_away_seconds integer DEFAULT 0 NOT NULL,
    second_hint_first_keystroke_delay_ms integer,
    problem_closed_at timestamp with time zone,
    problem_close_reason_code character varying(30),
    question_request_id uuid,
    first_hint_request_id uuid,
    second_hint_request_id uuid,
    CONSTRAINT ck_problem_stage_axis_code CHECK (((axis_code)::text = ANY ((ARRAY['L1'::character varying, 'L2'::character varying, 'L3'::character varying, 'L4'::character varying])::text[]))),
    CONSTRAINT ck_problem_stage_close_reason CHECK ((((problem_closed_at IS NULL) AND (problem_close_reason_code IS NULL)) OR ((problem_closed_at IS NOT NULL) AND (problem_close_reason_code IS NOT NULL) AND ((problem_close_reason_code)::text = ANY ((ARRAY['HINTS_EXHAUSTED'::character varying, 'CURSOR_MOVED'::character varying, 'PROBLEM_TIME_LIMIT'::character varying, 'SESSION_ENDED'::character varying])::text[]))))),
    CONSTRAINT ck_problem_stage_first_hint_answer_text CHECK ((((first_hint_answer_text IS NULL) AND (first_hint_score IS NULL) AND (first_hint_passed IS NULL) AND (first_hint_answered_at IS NULL)) OR ((first_hint_answer_text IS NOT NULL) AND (first_hint_score IS NOT NULL) AND (first_hint_passed IS NOT NULL) AND (first_hint_answered_at IS NOT NULL)))),
    CONSTRAINT ck_problem_stage_first_hint_away_count CHECK ((first_hint_away_count >= 0)),
    CONSTRAINT ck_problem_stage_first_hint_away_seconds CHECK ((first_hint_away_seconds >= 0)),
    CONSTRAINT ck_problem_stage_first_hint_first_keystroke_delay_ms CHECK (((first_hint_first_keystroke_delay_ms IS NULL) OR (first_hint_first_keystroke_delay_ms >= 0))),
    CONSTRAINT ck_problem_stage_first_hint_passed CHECK (((first_hint_passed IS NULL) OR (first_hint_score IS NOT NULL))),
    CONSTRAINT ck_problem_stage_first_hint_score CHECK (((first_hint_score IS NULL) OR ((first_hint_score >= 0) AND (first_hint_score <= 5)))),
    CONSTRAINT ck_problem_stage_first_hint_score_2 CHECK (((first_hint_passed IS NULL) OR ((first_hint_passed = true) AND (first_hint_score >= 3)) OR ((first_hint_passed = false) AND (first_hint_score < 3)))),
    CONSTRAINT ck_problem_stage_question_answer_text CHECK ((((question_answer_text IS NULL) AND (question_score IS NULL) AND (question_passed IS NULL) AND (question_answered_at IS NULL)) OR ((question_answer_text IS NOT NULL) AND (question_score IS NOT NULL) AND (question_passed IS NOT NULL) AND (question_answered_at IS NOT NULL)))),
    CONSTRAINT ck_problem_stage_question_away_count CHECK ((question_away_count >= 0)),
    CONSTRAINT ck_problem_stage_question_away_seconds CHECK ((question_away_seconds >= 0)),
    CONSTRAINT ck_problem_stage_question_first_keystroke_delay_ms CHECK (((question_first_keystroke_delay_ms IS NULL) OR (question_first_keystroke_delay_ms >= 0))),
    CONSTRAINT ck_problem_stage_question_passed CHECK (((question_passed IS NULL) OR (question_score IS NOT NULL))),
    CONSTRAINT ck_problem_stage_question_score CHECK (((question_score IS NULL) OR ((question_score >= 0) AND (question_score <= 5)))),
    CONSTRAINT ck_problem_stage_question_score_2 CHECK (((question_passed IS NULL) OR ((question_passed = true) AND (question_score >= 3)) OR ((question_passed = false) AND (question_score < 3)))),
    CONSTRAINT ck_problem_stage_row_version CHECK ((row_version >= 0)),
    CONSTRAINT ck_problem_stage_second_hint_answer_text CHECK ((((second_hint_answer_text IS NULL) AND (second_hint_score IS NULL) AND (second_hint_passed IS NULL) AND (second_hint_answered_at IS NULL)) OR ((second_hint_answer_text IS NOT NULL) AND (second_hint_score IS NOT NULL) AND (second_hint_passed IS NOT NULL) AND (second_hint_answered_at IS NOT NULL)))),
    CONSTRAINT ck_problem_stage_second_hint_away_count CHECK ((second_hint_away_count >= 0)),
    CONSTRAINT ck_problem_stage_second_hint_away_seconds CHECK ((second_hint_away_seconds >= 0)),
    CONSTRAINT ck_problem_stage_second_hint_first_keystroke_delay_ms CHECK (((second_hint_first_keystroke_delay_ms IS NULL) OR (second_hint_first_keystroke_delay_ms >= 0))),
    CONSTRAINT ck_problem_stage_second_hint_passed CHECK (((second_hint_passed IS NULL) OR (second_hint_score IS NOT NULL))),
    CONSTRAINT ck_problem_stage_second_hint_presented_at CHECK (((second_hint_presented_at IS NULL) OR (first_hint_presented_at IS NOT NULL))),
    CONSTRAINT ck_problem_stage_second_hint_score CHECK (((second_hint_score IS NULL) OR ((second_hint_score >= 0) AND (second_hint_score <= 5)))),
    CONSTRAINT ck_problem_stage_second_hint_score_2 CHECK (((second_hint_passed IS NULL) OR ((second_hint_passed = true) AND (second_hint_score >= 3)) OR ((second_hint_passed = false) AND (second_hint_score < 3)))),
    CONSTRAINT ck_problem_stage_source_problem_stage_id CHECK (((source_problem_stage_id IS NULL) OR (source_problem_stage_id <> problem_stage_id))),
    CONSTRAINT ck_problem_stage_status CHECK (((status)::text = ANY ((ARRAY['PREPARED'::character varying, 'IN_PROGRESS'::character varying, 'PASSED'::character varying, 'NOT_PASSED'::character varying, 'NOT_REACHED'::character varying, 'NOT_ANSWERED'::character varying])::text[]))),
    CONSTRAINT ck_problem_stage_status_2 CHECK (((((status)::text = 'PASSED'::text) AND ((question_passed IS TRUE) OR (first_hint_passed IS TRUE) OR (second_hint_passed IS TRUE))) OR (((status)::text = 'NOT_PASSED'::text) AND (question_answer_text IS NOT NULL) AND (question_passed IS NOT TRUE) AND (first_hint_passed IS NOT TRUE) AND (second_hint_passed IS NOT TRUE)) OR (((status)::text = ANY ((ARRAY['NOT_REACHED'::character varying, 'NOT_ANSWERED'::character varying])::text[])) AND (question_answer_text IS NULL) AND (question_score IS NULL) AND (question_passed IS NULL) AND (first_hint_answer_text IS NULL) AND (first_hint_score IS NULL) AND (first_hint_passed IS NULL) AND (second_hint_answer_text IS NULL) AND (second_hint_score IS NULL) AND (second_hint_passed IS NULL)) OR ((status)::text = ANY ((ARRAY['PREPARED'::character varying, 'IN_PROGRESS'::character varying])::text[]))))
);


--
-- Name: TABLE problem_stage; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.problem_stage IS '교육생별 평가 세션에서 실제 생성된 문제의 L1~L4 단계에 사용할 질문과 힌트 2개를 사전 저장하고, 질문·각 힌트에 대한 답변·0~5점·통과 여부를 같은 행에 누적 기록합니다. 별도 답변 시도 행은 생성하지 않습니다. | 정의서명: ProblemStage | 제약·비고: • UNIQUE(session_id, problem_id, axis_code) • UNIQUE(session_id, problem_id, question_sequence_no) • axis_code: L1 / L2 / L3 / L4, question_sequence_no: 1 / 2 / 3 / 4 고정 생성 • INITIAL·RETRY는 generation_status=''GENERATED''인 문제마다 세션별 L1~L4 4행을 사전 생성합니다. 총 행 수는 generated_problem_count × 4이며 REVIEW는 지정된 원본 단계만 생성합니다. • generation_status=''NOT_GENERATED''인 문제에는 ProblemStage·단계별 질문·단계별 힌트를 생성하지 않습니다. • 각 단계는 assessment_problem.source_snippet_key를 통해 Submission.code_snippets의 동일한 대표 코드 원문을 사용하며 단계별 코드 근거를 별도로 복제하지 않습니다. • 세션 READY 전 계획 문제 슬롯 3건의 generation_status가 모두 확정되어야 하고, GENERATED 문제의 question_text·first_hint_text·second_hint_text가 모두 존재해야 합니다. • question_score·first_hint_score·second_hint_score는 NULL 또는 0~5이며 답변·통과 여부·답변 일시와 함께 확정합니다. • 기본 ';


