--
-- Name: manager_class_heatmap_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.manager_class_heatmap_view AS
 WITH problem_result AS (
         SELECT ma.org_id,
            ma.cohort_id,
            ma.project_id,
            ma.assessment_round_id,
            ma.user_id,
            ma.attempt_id,
            ma.attempt_type,
            ma.source_attempt_id,
            ma.attempt_sequence_no,
            ma.status AS attempt_status,
            ma.validity_review_status,
            ma.terminal_reason_code,
            pm.class_id,
            tm.team_id,
            ap.problem_id,
            ap.problem_no,
            max(
                CASE
                    WHEN ((ps.status)::text = 'PASSED'::text) THEN
                    CASE ps.axis_code
                        WHEN 'L4'::text THEN 4
                        WHEN 'L3'::text THEN 3
                        WHEN 'L2'::text THEN 2
                        WHEN 'L1'::text THEN 1
                        ELSE 0
                    END
                    ELSE 0
                END) AS highest_reached_level,
                CASE
                    WHEN ((ma.validity_review_status)::text = 'CONFIRMED_INVALID'::text) THEN 'INVALID'::text
                    WHEN ((ma.status)::text = 'COMPLETED'::text) THEN 'VALID'::text
                    WHEN ((ma.terminal_reason_code)::text = ANY ((ARRAY['NOT_ATTENDED'::character varying, 'NOT_SUBMITTED'::character varying])::text[])) THEN 'NOT_ATTENDED'::text
                    WHEN (((ma.status)::text = 'FAILED'::text) OR ((ma.terminal_reason_code)::text = 'SESSION_INCOMPLETE'::text)) THEN 'INTERRUPTED'::text
                    WHEN ((ma.status)::text = 'EXPIRED'::text) THEN 'NOT_ATTENDED'::text
                    ELSE 'PENDING'::text
                END AS result_status,
            (sum(((((ps.question_answer_text IS NOT NULL))::integer + ((ps.first_hint_answer_text IS NOT NULL))::integer) + ((ps.second_hint_answer_text IS NOT NULL))::integer)))::integer AS answer_attempt_count,
            jsonb_agg(jsonb_build_object('axisCode', ps.axis_code, 'status', ps.status, 'questionScore', ps.question_score, 'firstHintScore', ps.first_hint_score, 'secondHintScore', ps.second_hint_score) ORDER BY ps.question_sequence_no) AS score_summary
           FROM (((((public.measurement_attempt ma
             LEFT JOIN public.project_membership pm ON (((pm.project_id = ma.project_id) AND (pm.user_id = ma.user_id) AND (pm.joined_at <= COALESCE(ma.assessment_open_at, ma.assigned_at, CURRENT_TIMESTAMP)) AND ((pm.left_at IS NULL) OR (pm.left_at > COALESCE(ma.assessment_open_at, ma.assigned_at, CURRENT_TIMESTAMP))))))
             LEFT JOIN LATERAL ( SELECT x.team_id
                   FROM public.team_membership x
                  WHERE ((x.project_membership_id = pm.project_membership_id) AND (x.from_at <= COALESCE(ma.assessment_open_at, ma.assigned_at, CURRENT_TIMESTAMP)) AND ((x.to_at IS NULL) OR (x.to_at > COALESCE(ma.assessment_open_at, ma.assigned_at, CURRENT_TIMESTAMP))))
                  ORDER BY x.from_at DESC
                 LIMIT 1) tm ON (true))
             LEFT JOIN public.assessment_session s ON ((s.attempt_id = ma.attempt_id)))
             LEFT JOIN public.problem_stage ps ON ((ps.session_id = s.session_id)))
             LEFT JOIN public.assessment_problem ap ON ((ap.problem_id = ps.problem_id)))
          GROUP BY ma.org_id, ma.cohort_id, ma.project_id, ma.assessment_round_id, ma.user_id, ma.attempt_id, ma.attempt_type, ma.source_attempt_id, ma.attempt_sequence_no, ma.status, ma.validity_review_status, ma.terminal_reason_code, pm.class_id, tm.team_id, ap.problem_id, ap.problem_no
        )
 SELECT org_id,
    cohort_id,
    class_id,
    project_id,
    assessment_round_id,
    problem_no,
    (avg(highest_reached_level) FILTER (WHERE (result_status = 'VALID'::text)))::numeric(10,4) AS average_highest_reached_level,
    (count(*) FILTER (WHERE (result_status = 'VALID'::text)))::integer AS valid_result_count,
    (count(*) FILTER (WHERE (result_status = 'NOT_ATTENDED'::text)))::integer AS not_attended_count,
    (count(*) FILTER (WHERE (result_status = 'INVALID'::text)))::integer AS invalid_attempt_count,
    (count(*) FILTER (WHERE (result_status = 'INTERRUPTED'::text)))::integer AS interrupted_count,
    (
        CASE
            WHEN (count(*) = 0) THEN 'EMPTY'::text
            WHEN (count(*) FILTER (WHERE (result_status = 'VALID'::text)) = 0) THEN 'NO_VALID_RESULT'::text
            ELSE 'COMPLETE'::text
        END)::character varying(20) AS aggregation_status,
    CURRENT_TIMESTAMP AS as_of_at,
    1 AS calculation_version
   FROM problem_result pr
  WHERE ((attempt_type)::text = 'INITIAL'::text)
  GROUP BY org_id, cohort_id, class_id, project_id, assessment_round_id, problem_no;


--
-- Name: manager_curriculum_list_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.manager_curriculum_list_view AS
 WITH scope AS (
         SELECT ma.org_id,
            ma.manager_user_id,
            c.cohort_id,
            array_agg(DISTINCT ma.class_id) AS class_ids
           FROM (public.manager_assignment ma
             JOIN public.class c ON ((c.class_id = ma.class_id)))
          WHERE (((ma.status)::text = 'ACTIVE'::text) AND (ma.unassigned_at IS NULL))
          GROUP BY ma.org_id, ma.manager_user_id, c.cohort_id
        )
 SELECT scope.org_id,
    scope.manager_user_id,
    scope.cohort_id,
    scope.class_ids AS assigned_class_ids,
    m.material_id,
    (m.title)::text AS curriculum_title,
    v.version_id,
    v.version_no,
    m.created_at AS registered_at,
    v.page_count,
    la.analysis_id AS latest_analysis_attempt_id,
    (la.status)::character varying(100) AS latest_analysis_attempt_status,
    la.failure_code AS latest_failure_code,
    (la.recovery_action)::text AS latest_recovery_action,
    ea.analysis_id AS effective_analysis_id,
    (
        CASE
            WHEN (la.analysis_id IS NULL) THEN 'NOT_ANALYZED'::character varying
            WHEN (((la.status)::text = 'FAILED'::text) AND (ea.analysis_id IS NOT NULL)) THEN 'FAILED_USING_PREVIOUS'::character varying
            ELSE la.status
        END)::character varying(50) AS display_analysis_status,
    (
        CASE
            WHEN (ea.analysis_id IS NULL) THEN 'UNAVAILABLE'::text
            WHEN ea.fallback_used THEN 'FALLBACK'::text
            ELSE 'NORMAL'::text
        END)::character varying(100) AS analysis_quality_status,
    COALESCE(stats.section_count, 0) AS section_count,
    COALESCE(stats.teaching_item_count, 0) AS teaching_item_count,
    COALESCE(stats.distinct_teaches_count, 0) AS distinct_teaches_count,
    COALESCE(use.used_round_count, 0) AS used_round_count,
    COALESCE(use.round_ids, ARRAY[]::uuid[]) AS used_round_ids,
    (COALESCE(use.round_names, (ARRAY[]::text[])::character varying[]))::text[] AS used_round_names,
    use.latest_used_at,
    (
        CASE
            WHEN (v.version_id IS NULL) THEN 'NO_VERSION'::text
            WHEN (ea.analysis_id IS NULL) THEN 'NO_SUCCESSFUL_ANALYSIS'::text
            ELSE NULL::text
        END)::character varying(100) AS empty_reason,
    'COMPLETE'::character varying(20) AS aggregation_status,
    CURRENT_TIMESTAMP AS as_of_at
   FROM ((((((scope
     JOIN public.curriculum_material m ON (((m.org_id = scope.org_id) AND (m.deleted_at IS NULL))))
     LEFT JOIN LATERAL ( SELECT x.version_id,
            x.material_id,
            x.version_no,
            x.original_file_name,
            x.file_uri,
            x.mime_type,
            x.file_size_bytes,
            x.content_hash,
            x.page_count,
            x.status,
            x.created_by,
            x.created_at
           FROM public.curriculum_version x
          WHERE (x.material_id = m.material_id)
          ORDER BY x.version_no DESC
         LIMIT 1) v ON (true))
     LEFT JOIN LATERAL ( SELECT x.analysis_id,
            x.version_id,
            x.model_id,
            x.retry_of_analysis_id,
            x.analysis_version,
            x.status,
            x.fallback_used,
            x.idempotency_key,
            x.request_fingerprint,
            x.request_reason,
            x.impact_acknowledged,
            x.requested_by,
            x.requested_at,
            x.started_at,
            x.completed_at,
            x.failed_at,
            x.failure_code,
            x.failure_stage,
            x.failure_reason,
            x.is_retryable,
            x.recovery_action,
            x.created_at,
            x.external_job_id
           FROM public.curriculum_analysis x
          WHERE (x.version_id = v.version_id)
          ORDER BY x.requested_at DESC
         LIMIT 1) la ON (true))
     LEFT JOIN LATERAL ( SELECT x.analysis_id,
            x.version_id,
            x.model_id,
            x.retry_of_analysis_id,
            x.analysis_version,
            x.status,
            x.fallback_used,
            x.idempotency_key,
            x.request_fingerprint,
            x.request_reason,
            x.impact_acknowledged,
            x.requested_by,
            x.requested_at,
            x.started_at,
            x.completed_at,
            x.failed_at,
            x.failure_code,
            x.failure_stage,
            x.failure_reason,
            x.is_retryable,
            x.recovery_action,
            x.created_at,
            x.external_job_id
           FROM public.curriculum_analysis x
          WHERE ((x.version_id = v.version_id) AND ((x.status)::text = 'SUCCEEDED'::text))
          ORDER BY x.completed_at DESC, x.analysis_version DESC
         LIMIT 1) ea ON (true))
     LEFT JOIN LATERAL ( SELECT (count(DISTINCT s.section_id))::integer AS section_count,
            (count(map.mapping_id))::integer AS teaching_item_count,
            (count(DISTINCT map.teaches_id))::integer AS distinct_teaches_count
           FROM (public.curriculum_section s
             LEFT JOIN public.curriculum_teaches_mapping map ON ((map.section_id = s.section_id)))
          WHERE ((s.version_id = v.version_id) AND (s.source_analysis_id = ea.analysis_id))) stats ON (true))
     LEFT JOIN LATERAL ( SELECT (count(DISTINCT r.assessment_round_id))::integer AS used_round_count,
            array_agg(DISTINCT r.assessment_round_id) AS round_ids,
            array_agg(DISTINCT r.round_name ORDER BY r.round_name) AS round_names,
            max(COALESCE(r.updated_at, r.created_at)) AS latest_used_at
           FROM ((public.project_curriculum pc
             JOIN public.project p ON (((p.project_id = pc.project_id) AND (p.cohort_id = scope.cohort_id))))
             JOIN public.project_assessment_round r ON (((r.project_id = p.project_id) AND (r.deleted_at IS NULL))))
          WHERE (pc.curriculum_version_id = v.version_id)) use ON (true));


--
-- Name: manager_curriculum_usage_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.manager_curriculum_usage_view AS
 WITH scope AS (
         SELECT ma.org_id,
            ma.manager_user_id,
            c.cohort_id,
            array_agg(DISTINCT ma.class_id) AS class_ids
           FROM (public.manager_assignment ma
             JOIN public.class c ON ((c.class_id = ma.class_id)))
          WHERE (((ma.status)::text = 'ACTIVE'::text) AND (ma.unassigned_at IS NULL))
          GROUP BY ma.org_id, ma.manager_user_id, c.cohort_id
        )
 SELECT scope.org_id,
    scope.manager_user_id,
    scope.cohort_id,
    m.material_id,
    v.version_id,
    p.project_id,
    p.sequence_no AS project_sequence_no,
    p.name AS project_name,
    p.project_category,
    r.assessment_round_id,
    r.round_no,
    r.round_name,
    r.status AS round_status,
    cs.concept_set_id,
    (
        CASE
            WHEN (COALESCE(con.cnt, 0) = 3) THEN 'COMPLETE'::text
            WHEN (COALESCE(con.cnt, 0) = 0) THEN 'EMPTY'::text
            ELSE 'PARTIAL'::text
        END)::character varying(30) AS concept_selection_status,
    COALESCE(con.cnt, 0) AS selected_concept_count,
    (COALESCE(con.items, '[]'::jsonb))::text AS concepts,
    cardinality(scope.class_ids) AS assigned_class_count,
    scope.class_ids AS assigned_class_ids,
    COALESCE(st.eligible, 0) AS eligible_trainee_count,
    COALESCE(st.attempted, 0) AS attempted_trainee_count,
    COALESCE(st.completed, 0) AS completed_trainee_count,
    (
        CASE
            WHEN (COALESCE(rep.published_count, 0) > 0) THEN 'PUBLISHED'::text
            ELSE 'NOT_PUBLISHED'::text
        END)::character varying(100) AS result_release_status,
    COALESCE(rep.published_count, 0) AS published_report_count,
    'COMPLETE'::character varying(20) AS aggregation_status,
    CURRENT_TIMESTAMP AS as_of_at
   FROM (((((((((scope
     JOIN public.project p ON (((p.cohort_id = scope.cohort_id) AND (p.deleted_at IS NULL))))
     JOIN public.project_curriculum pc ON ((pc.project_id = p.project_id)))
     JOIN public.curriculum_version v ON ((v.version_id = pc.curriculum_version_id)))
     JOIN public.curriculum_material m ON ((m.material_id = v.material_id)))
     LEFT JOIN public.project_assessment_round r ON (((r.project_id = p.project_id) AND (r.deleted_at IS NULL))))
     LEFT JOIN LATERAL ( SELECT x.concept_set_id,
            x.project_id,
            x.org_id,
            x.version_no,
            x.status,
            x.effective_from,
            x.effective_to,
            x.created_by,
            x.change_reason,
            x.created_at
           FROM public.project_verification_concept_set x
          WHERE ((x.project_id = p.project_id) AND ((x.status)::text = 'ACTIVE'::text))
          ORDER BY x.version_no DESC
         LIMIT 1) cs ON (true))
     LEFT JOIN LATERAL ( SELECT (count(*))::integer AS cnt,
            jsonb_agg(jsonb_build_object('projectConceptId', x.project_concept_id, 'teachesId', x.teaches_id, 'sequenceNo', x.sequence_no, 'name', t.canonical_name) ORDER BY x.sequence_no) AS items
           FROM (public.project_verification_concept x
             LEFT JOIN public.teaches t ON ((t.teaches_id = x.teaches_id)))
          WHERE (x.concept_set_id = cs.concept_set_id)) con ON (true))
     LEFT JOIN LATERAL ( SELECT (( SELECT count(*) AS count
                   FROM public.project_membership pm_1
                  WHERE ((pm_1.project_id = p.project_id) AND (pm_1.class_id = ANY (scope.class_ids)) AND ((pm_1.status)::text = 'ACTIVE'::text))))::integer AS eligible,
            (count(DISTINCT ma.user_id))::integer AS attempted,
            (count(DISTINCT ma.user_id) FILTER (WHERE ((ma.status)::text = 'COMPLETED'::text)))::integer AS completed
           FROM (public.measurement_attempt ma
             JOIN public.project_membership pm ON (((pm.user_id = ma.user_id) AND (pm.project_id = p.project_id))))
          WHERE ((ma.assessment_round_id = r.assessment_round_id) AND (pm.class_id = ANY (scope.class_ids)))) st ON (true))
     LEFT JOIN LATERAL ( SELECT (count(*) FILTER (WHERE (rpt.published_at IS NOT NULL)))::integer AS published_count
           FROM public.report rpt
          WHERE (rpt.assessment_round_id = r.assessment_round_id)) rep ON (true));


--
-- Name: manager_interview_brief_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.manager_interview_brief_view AS
 WITH scope AS (
         SELECT ma.manager_user_id,
            ma.class_id
           FROM public.manager_assignment ma
          WHERE (((ma.status)::text = 'ACTIVE'::text) AND (ma.unassigned_at IS NULL))
        )
 SELECT i.org_id,
    scope.manager_user_id,
    i.cohort_id,
    i.class_id,
    i.interview_id,
    i.status AS interview_status,
    i.target_user_id,
    u.name AS target_user_name,
    b.brief_id,
    cb.brief_id AS latest_confirmed_brief_id,
    (
        CASE
            WHEN (b.brief_id IS NULL) THEN 'NOT_INITIALIZED'::character varying
            WHEN ((b.status)::text = 'DRAFT'::text) THEN 'DRAFT_SAVED'::character varying
            ELSE b.status
        END)::character varying(100) AS brief_persistence_status,
    b.brief_type,
    b.version_no,
    b.status AS brief_status,
    b.is_first_interview,
    NULL::integer AS previous_completed_interview_count,
    NULL::character varying(100) AS first_interview_scope_code,
    NULL::timestamp with time zone AS first_interview_evaluated_at,
    b.brief_generation_policy_version,
    NULL::integer AS difficulty_scale_version,
    COALESCE(items.total_count, 0) AS persisted_total_item_count,
    COALESCE(items.selected_count, 0) AS persisted_selected_item_count,
    COALESCE(src.source_count, 0) AS persisted_source_count,
    (COALESCE(items.selected_count, 0) > 1) AS has_multiple_selected_items,
    b.manager_note,
    jsonb_build_object('status',
        CASE
            WHEN (COALESCE(src.source_count, 0) = 0) THEN 'EMPTY'::text
            ELSE 'AVAILABLE'::text
        END, 'sourceCount', COALESCE(src.source_count, 0)) AS source_snapshot_status,
    (
        CASE
            WHEN (COALESCE(src.source_count, 0) = 0) THEN 'NOT_CHECKED'::text
            ELSE 'CONSISTENT'::text
        END)::character varying(100) AS source_consistency_status,
    ((b.brief_id IS NULL) AND ((i.status)::text = 'PENDING'::text)) AS can_initialize,
    (((b.status)::text = 'DRAFT'::text) AND ((i.status)::text = 'PENDING'::text)) AS can_edit,
    (((b.status)::text = 'DRAFT'::text) AND ((i.status)::text = 'PENDING'::text)) AS can_save,
    (((b.status)::text = 'DRAFT'::text) AND ((i.status)::text = 'PENDING'::text) AND (COALESCE(items.selected_count, 0) > 0)) AS can_confirm,
    (
        CASE
            WHEN ((i.status)::text <> 'PENDING'::text) THEN 'BRIEF_NOT_EDITABLE'::text
            WHEN (b.brief_id IS NULL) THEN NULL::text
            WHEN ((b.status)::text <> 'DRAFT'::text) THEN 'BRIEF_NOT_EDITABLE'::text
            WHEN (COALESCE(items.selected_count, 0) = 0) THEN 'NO_SELECTED_ITEM'::text
            ELSE NULL::text
        END)::character varying(100) AS action_unavailable_reason_code,
    COALESCE(b.row_version, 0) AS row_version,
    (b.updated_by)::text AS last_saved_by,
    b.updated_at AS last_saved_at,
    b.created_by,
    b.created_at,
    b.updated_by,
    b.updated_at,
    b.confirmed_by,
    b.confirmed_at,
    'COMPLETE'::character varying(20) AS aggregation_status,
    CURRENT_TIMESTAMP AS as_of_at
   FROM ((((((public.interview i
     JOIN scope ON ((scope.class_id = i.class_id)))
     JOIN public.app_user u ON ((u.user_id = i.target_user_id)))
     LEFT JOIN LATERAL ( SELECT x.brief_id,
            x.interview_id,
            x.org_id,
            x.cohort_id,
            x.user_id,
            x.assessment_round_id,
            x.brief_type,
            x.version_no,
            x.is_first_interview,
            x.brief_generation_policy_version,
            x.status,
            x.manager_note,
            x.opening_remark_text,
            x.opening_remark_generated_at,
            x.created_by,
            x.created_at,
            x.updated_by,
            x.updated_at,
            x.confirmed_by,
            x.confirmed_at,
            x.row_version,
            x.last_request_id,
            x.last_request_fingerprint
           FROM public.interview_brief x
          WHERE (x.interview_id = i.interview_id)
          ORDER BY
                CASE
                    WHEN ((x.status)::text = 'DRAFT'::text) THEN 0
                    WHEN ((x.status)::text = 'CONFIRMED'::text) THEN 1
                    ELSE 2
                END, x.version_no DESC
         LIMIT 1) b ON (true))
     LEFT JOIN LATERAL ( SELECT x.brief_id
           FROM public.interview_brief x
          WHERE ((x.interview_id = i.interview_id) AND ((x.status)::text = 'CONFIRMED'::text))
          ORDER BY x.version_no DESC
         LIMIT 1) cb ON (true))
     LEFT JOIN LATERAL ( SELECT (count(*))::integer AS total_count,
            (count(*) FILTER (WHERE x.is_selected))::integer AS selected_count
           FROM public.interview_brief_item x
          WHERE (x.brief_id = b.brief_id)) items ON (true))
     LEFT JOIN LATERAL ( SELECT (count(*))::integer AS source_count
           FROM public.interview_source x
          WHERE (x.interview_id = i.interview_id)) src ON (true));


--
-- Name: mini_project_round_sequence_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.mini_project_round_sequence_view AS
 SELECT par.assessment_round_id,
    pj.project_id,
    pj.cohort_id,
    (dense_rank() OVER (PARTITION BY pj.cohort_id ORDER BY pj.sequence_no, pj.project_id))::integer AS analysis_sequence_no
   FROM (public.project_assessment_round par
     JOIN public.project pj ON (((pj.project_id = par.project_id) AND (pj.deleted_at IS NULL) AND ((pj.project_category)::text = 'MINI_PROJECT'::text))))
  WHERE (par.deleted_at IS NULL);


--
-- Name: manager_interview_list_context_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.manager_interview_list_context_view AS
 WITH scope AS (
         SELECT ma.org_id,
            ma.manager_user_id,
            c.cohort_id,
            array_agg(DISTINCT ma.class_id) AS class_ids
           FROM (public.manager_assignment ma
             JOIN public.class c ON ((c.class_id = ma.class_id)))
          WHERE (((ma.status)::text = 'ACTIVE'::text) AND (ma.unassigned_at IS NULL))
          GROUP BY ma.org_id, ma.manager_user_id, c.cohort_id
        ), x AS (
         SELECT s.org_id,
            s.manager_user_id,
            s.cohort_id,
            s.class_ids,
            cr.project_id AS current_project_id,
            cr.assessment_round_id AS current_round_id,
            cr.round_no AS current_round_no,
            ( SELECT jsonb_agg(jsonb_build_object('assessmentRoundId', r.assessment_round_id, 'projectId', r.project_id, 'roundNo', ( SELECT s_1.analysis_sequence_no
                           FROM public.mini_project_round_sequence_view s_1
                          WHERE (s_1.assessment_round_id = r.assessment_round_id)), 'roundName', r.round_name, 'status', r.status) ORDER BY p.sequence_no, r.round_no) AS jsonb_agg
                   FROM (public.project_assessment_round r
                     JOIN public.project p ON ((p.project_id = r.project_id)))
                  WHERE ((r.cohort_id = s.cohort_id) AND (r.deleted_at IS NULL))) AS rounds,
            (( SELECT count(*) AS count
                   FROM public.project_membership pm
                  WHERE ((pm.project_id = cr.project_id) AND (pm.class_id = ANY (s.class_ids)) AND ((pm.status)::text = 'ACTIVE'::text))))::integer AS eligible_trainee_count,
            (( SELECT count(DISTINCT ic.user_id) AS count
                   FROM public.interview_candidate ic
                  WHERE ((ic.assessment_round_id = cr.assessment_round_id) AND (ic.class_id = ANY (s.class_ids)))))::integer AS evaluated_trainee_count,
            (( SELECT count(*) AS count
                   FROM public.interview_candidate ic
                  WHERE ((ic.assessment_round_id = cr.assessment_round_id) AND (ic.class_id = ANY (s.class_ids)) AND ((ic.status)::text <> 'EXCLUDED'::text))))::integer AS matched_candidate_count,
            0 AS unavailable_count,
            (( SELECT count(*) AS count
                   FROM public.interview_candidate ic
                  WHERE ((ic.assessment_round_id = cr.assessment_round_id) AND (ic.class_id = ANY (s.class_ids)) AND ((ic.status)::text <> 'EXCLUDED'::text))))::integer AS accessible_candidate_count,
            (( SELECT count(*) AS count
                   FROM (public.interview_candidate ic
                     LEFT JOIN public.interview i ON ((i.candidate_id = ic.candidate_id)))
                  WHERE ((ic.assessment_round_id = cr.assessment_round_id) AND (ic.class_id = ANY (s.class_ids)) AND ((COALESCE(i.status, 'PENDING'::character varying))::text <> 'COMPLETED'::text))))::integer AS active_item_count,
            (( SELECT count(*) AS count
                   FROM public.interview i
                  WHERE ((i.assessment_round_id = cr.assessment_round_id) AND (i.class_id = ANY (s.class_ids)) AND ((i.status)::text = 'COMPLETED'::text))))::integer AS completed_interview_count,
            ( SELECT COALESCE(jsonb_object_agg(q.status, q.cnt), '{}'::jsonb) AS "coalesce"
                   FROM ( SELECT ic.status,
                            count(*) AS cnt
                           FROM public.interview_candidate ic
                          WHERE ((ic.assessment_round_id = cr.assessment_round_id) AND (ic.class_id = ANY (s.class_ids)))
                          GROUP BY ic.status) q) AS candidate_status_counts,
            ( SELECT COALESCE(jsonb_object_agg(q.status, q.cnt), '{}'::jsonb) AS "coalesce"
                   FROM ( SELECT i.status,
                            count(*) AS cnt
                           FROM public.interview i
                          WHERE ((i.assessment_round_id = cr.assessment_round_id) AND (i.class_id = ANY (s.class_ids)))
                          GROUP BY i.status) q) AS interview_status_counts,
            ( SELECT COALESCE(jsonb_agg(jsonb_build_object('reasonCode', q.reason_code, 'count', q.cnt)), '[]'::jsonb) AS "coalesce"
                   FROM ( SELECT icr.reason_code,
                            count(*) AS cnt
                           FROM (public.interview_candidate_reason icr
                             JOIN public.interview_candidate ic ON ((ic.candidate_id = icr.candidate_id)))
                          WHERE ((ic.assessment_round_id = cr.assessment_round_id) AND (ic.class_id = ANY (s.class_ids)) AND ((icr.reason_status)::text = 'ACTIVE'::text))
                          GROUP BY icr.reason_code) q) AS reason_results
           FROM (scope s
             LEFT JOIN LATERAL ( SELECT r.assessment_round_id,
                    r.project_id,
                    r.org_id,
                    r.cohort_id,
                    r.concept_set_id,
                    r.round_no,
                    r.round_name,
                    r.analysis_role_code,
                    r.trigger_type,
                    r.scheduled_at,
                    r.submission_due_at,
                    r.assessment_open_at,
                    r.assessment_due_at,
                    r.report_publish_mode,
                    r.report_publish_not_before_at,
                    r.is_final,
                    r.status,
                    r.created_by,
                    r.updated_by,
                    r.created_at,
                    r.updated_at,
                    r.deleted_at
                   FROM (public.project_assessment_round r
                     JOIN public.project p ON ((p.project_id = r.project_id)))
                  WHERE ((r.cohort_id = s.cohort_id) AND (r.deleted_at IS NULL))
                  ORDER BY
                        CASE
                            WHEN ((r.status)::text = ANY ((ARRAY['OPEN'::character varying, 'PLANNED'::character varying])::text[])) THEN 0
                            ELSE 1
                        END, p.sequence_no DESC, r.round_no DESC
                 LIMIT 1) cr ON (true))
        )
 SELECT org_id,
    manager_user_id,
    cohort_id,
    'ACTIVE'::character varying(100) AS list_mode,
    'SELECTED_OR_CURRENT'::character varying(100) AS round_scope,
    current_project_id AS selected_project_id,
    current_round_id AS selected_assessment_round_id,
    current_round_id AS current_assessment_round_id,
    'CURRENT'::character varying(100) AS round_relation_code,
    (COALESCE(rounds, '[]'::jsonb))::text AS available_assessment_rounds,
    current_round_id AS default_assessment_round_id,
    (
        CASE
            WHEN (current_round_id IS NULL) THEN 'NO_ROUND'::text
            ELSE NULL::text
        END)::character varying(100) AS selection_unavailable_reason_code,
    ( SELECT s.analysis_sequence_no
           FROM public.mini_project_round_sequence_view s
          WHERE (s.assessment_round_id = x.current_round_id)) AS analysis_sequence_no,
    (( SELECT s.analysis_sequence_no
           FROM public.mini_project_round_sequence_view s
          WHERE (s.assessment_round_id = x.current_round_id)) = 1) AS is_first_mini_project,
    (
        CASE
            WHEN (evaluated_trainee_count = eligible_trainee_count) THEN 'COMPLETED'::text
            WHEN (evaluated_trainee_count = 0) THEN 'NOT_STARTED'::text
            ELSE 'PARTIAL'::text
        END)::character varying(100) AS candidate_evaluation_status,
    NULL::character varying(100) AS candidate_evaluation_reason_code,
    COALESCE(reason_results, '[]'::jsonb) AS reason_evaluation_results,
    eligible_trainee_count,
    evaluated_trainee_count,
    matched_candidate_count,
    GREATEST((eligible_trainee_count - evaluated_trainee_count), 0) AS unevaluated_trainee_count,
    unavailable_count AS unavailable_evaluation_count,
    accessible_candidate_count,
    active_item_count,
    completed_interview_count,
    (candidate_status_counts)::text AS candidate_status_counts,
    (interview_status_counts)::text AS interview_status_counts,
    (active_item_count + completed_interview_count) AS mode_total_count,
    active_item_count AS filtered_count,
    ((unavailable_count > 0))::text AS mode_total_count_is_partial,
    (
        CASE
            WHEN (current_round_id IS NULL) THEN 'NO_ROUND'::text
            WHEN (active_item_count = 0) THEN 'NO_CANDIDATE'::text
            ELSE NULL::text
        END)::character varying(100) AS empty_state_code,
    (
        CASE
            WHEN (unavailable_count > 0) THEN 'PARTIAL'::text
            ELSE 'COMPLETE'::text
        END)::character varying(20) AS aggregation_status,
    CURRENT_TIMESTAMP AS as_of_at,
    1 AS calculation_version
   FROM x;


--
-- Name: manager_interview_list_source_status_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.manager_interview_list_source_status_view AS
 WITH scope AS (
         SELECT ma.org_id,
            ma.manager_user_id,
            c.cohort_id,
            ma.class_id
           FROM (public.manager_assignment ma
             JOIN public.class c ON ((c.class_id = ma.class_id)))
          WHERE (((ma.status)::text = 'ACTIVE'::text) AND (ma.unassigned_at IS NULL))
        ), rounds AS (
         SELECT DISTINCT s.org_id,
            s.manager_user_id,
            s.cohort_id,
            r.assessment_round_id,
            s.class_id
           FROM (scope s
             JOIN public.project_assessment_round r ON (((r.cohort_id = s.cohort_id) AND (r.deleted_at IS NULL))))
        ), z AS (
         SELECT r.org_id,
            r.manager_user_id,
            r.cohort_id,
            r.assessment_round_id,
            'ACTIVE'::text AS list_mode,
            'SELECTED_OR_CURRENT'::text AS round_scope,
            md5((((r.manager_user_id)::text || ':'::text) || (r.class_id)::text)) AS assignment_scope_hash,
            'ANALYSIS_JOB'::text AS source_code,
                CASE
                    WHEN (count(aj.job_id) = 0) THEN 'NOT_STARTED'::text
                    WHEN bool_or(((aj.status)::text = 'FAILED'::text)) THEN 'FAILED'::text
                    WHEN bool_and(((aj.status)::text = 'SUCCEEDED'::text)) THEN 'READY'::text
                    ELSE 'RUNNING'::text
                END AS source_readiness_status,
                CASE
                    WHEN bool_or(((aj.status)::text = 'FAILED'::text)) THEN 'PARTIAL'::text
                    ELSE 'COMPLETE'::text
                END AS aggregation_status,
            CURRENT_TIMESTAMP AS as_of_at,
            false AS is_stale,
            max(aj.trace_id) AS source_watermark,
            max(aj.completed_at) FILTER (WHERE ((aj.status)::text = 'SUCCEEDED'::text)) AS last_successful_at,
                CASE
                    WHEN bool_or(((aj.status)::text = 'FAILED'::text)) THEN 'ANALYSIS_FAILED'::text
                    ELSE NULL::text
                END AS failure_code,
            (count(*) FILTER (WHERE ((aj.status)::text = 'FAILED'::text)))::integer AS affected_row_count,
            bool_or(((aj.status)::text = 'FAILED'::text)) AS mode_total_count_is_partial,
            bool_or(((aj.status)::text = 'FAILED'::text)) AS retryable,
                CASE
                    WHEN bool_or(((aj.status)::text = 'FAILED'::text)) THEN 'ASSESSMENT_ROUND'::text
                    ELSE NULL::text
                END AS retry_scope_code
           FROM (rounds r
             LEFT JOIN public.analysis_job aj ON ((aj.assessment_round_id = r.assessment_round_id)))
          GROUP BY r.org_id, r.manager_user_id, r.cohort_id, r.assessment_round_id, r.class_id
        UNION ALL
         SELECT r.org_id,
            r.manager_user_id,
            r.cohort_id,
            r.assessment_round_id,
            'ACTIVE'::text,
            'SELECTED_OR_CURRENT'::text,
            md5((((r.manager_user_id)::text || ':'::text) || (r.class_id)::text)) AS md5,
            'MEASUREMENT_ATTEMPT'::text,
                CASE
                    WHEN (count(ma.attempt_id) = 0) THEN 'NOT_STARTED'::text
                    WHEN bool_or(((ma.status)::text = 'FAILED'::text)) THEN 'FAILED'::text
                    WHEN bool_and(((ma.status)::text = ANY ((ARRAY['COMPLETED'::character varying, 'EXPIRED'::character varying])::text[]))) THEN 'READY'::text
                    ELSE 'RUNNING'::text
                END AS "case",
                CASE
                    WHEN bool_or(((ma.status)::text = 'FAILED'::text)) THEN 'PARTIAL'::text
                    ELSE 'COMPLETE'::text
                END AS "case",
            CURRENT_TIMESTAMP AS "current_timestamp",
            false,
            (max(ma.updated_at))::text AS max,
            max(ma.updated_at) FILTER (WHERE ((ma.status)::text = 'COMPLETED'::text)) AS max,
                CASE
                    WHEN bool_or(((ma.status)::text = 'FAILED'::text)) THEN 'ATTEMPT_FAILED'::text
                    ELSE NULL::text
                END AS "case",
            (count(*) FILTER (WHERE ((ma.status)::text = 'FAILED'::text)))::integer AS count,
            bool_or(((ma.status)::text = 'FAILED'::text)) AS bool_or,
            false,
            NULL::text
           FROM (rounds r
             LEFT JOIN public.measurement_attempt ma ON ((ma.assessment_round_id = r.assessment_round_id)))
          GROUP BY r.org_id, r.manager_user_id, r.cohort_id, r.assessment_round_id, r.class_id
        )
 SELECT org_id,
    manager_user_id,
    cohort_id,
    assessment_round_id,
    (list_mode)::character varying(100) AS list_mode,
    (round_scope)::character varying(100) AS round_scope,
    (assignment_scope_hash)::character varying(128) AS assignment_scope_hash,
    (source_code)::character varying(100) AS source_code,
    (source_readiness_status)::character varying(100) AS source_readiness_status,
    (aggregation_status)::character varying(20) AS aggregation_status,
    as_of_at,
    is_stale,
    source_watermark,
    last_successful_at,
    (failure_code)::character varying(100) AS failure_code,
    affected_row_count,
    (mode_total_count_is_partial)::text AS mode_total_count_is_partial,
    (retryable)::text AS retryable,
    (retry_scope_code)::character varying(100) AS retry_scope_code
   FROM z;


--
-- Name: team; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.team (
    team_id uuid DEFAULT gen_random_uuid() NOT NULL,
    project_id uuid NOT NULL,
    class_id uuid NOT NULL,
    org_id uuid NOT NULL,
    team_number text NOT NULL,
    name character varying(200) NOT NULL,
    status character varying(30) DEFAULT 'DRAFT'::character varying NOT NULL,
    min_member_count integer NOT NULL,
    max_member_count integer NOT NULL,
    row_version integer DEFAULT 0 NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    deleted_at timestamp with time zone,
    CONSTRAINT ck_team_max_member_count CHECK ((max_member_count >= min_member_count)),
    CONSTRAINT ck_team_min_member_count CHECK ((min_member_count > 0)),
    CONSTRAINT ck_team_row_version CHECK ((row_version >= 0)),
    CONSTRAINT ck_team_status CHECK (((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'CONFIRMED'::character varying])::text[])))
);


--
-- Name: TABLE team; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.team IS '프로젝트·반별 제출 단위와 팀 편성 상태, 안정적인 팀 번호, 인원 범위와 동시 수정 버전을 관리합니다. 프로젝트가 달라지면 같은 팀 번호라도 별개의 team_id와 팀원 구성을 가집니다. | 정의서명: Team | 제약·비고: • team_number > 0 • 활성 범위 UNIQUE(project_id, class_id, team_number), UNIQUE(project_id, class_id, name) • 상태: DRAFT / CONFIRMED • min_member_count > 0, max_member_count >= min_member_count • Project.cohort_id와 Class.cohort_id, 모든 org_id 경로가 일치해야 합니다. • 같은 project_id + class_id의 활성 팀 집합은 정상 상태에서 모두 DRAFT 또는 모두 CONFIRMED여야 하며 혼합 상태를 금지합니다. • 팀 번호는 OP-02 행 슬롯과 정렬에 사용하지만 프로젝트 간 동일 팀 계보나 동일 구성원을 뜻하지 않습니다. • 화면 team_display_key=''TEAM_NO_'' || team_number는 조회 파생값입니다. • 편성 확정은 관련 팀·참여·소속 행을 잠그고 전원 배정·팀명·인원 범위를 재검증한 뒤 모든 팀을 원자적으로 CONFIRMED로 변경합니다. • SUBMISSION_STARTED는 Team.status에 저장하지 않고 유효 Submission 존재 여부에서 파생합니다. • row_version은 팀명·팀원·잠금의 낙관적 동시성 검증에 사용합니다.';


