--
-- Name: manager_interview_list_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.manager_interview_list_view AS
 WITH scope AS (
         SELECT ma_1.manager_user_id,
            ma_1.class_id
           FROM public.manager_assignment ma_1
          WHERE (((ma_1.status)::text = 'ACTIVE'::text) AND (ma_1.unassigned_at IS NULL))
        )
 SELECT ic.org_id,
    scope.manager_user_id,
    ic.cohort_id,
    'ACTIVE'::character varying(100) AS list_mode,
    'SELECTED_OR_CURRENT'::character varying(100) AS round_scope,
    NULL::text AS candidate_status_filter,
    ic.class_id,
    c.name AS class_name,
    ic.team_id,
    t.name AS team_name,
    ic.candidate_id,
    ic.status AS candidate_status,
    ic.row_version AS candidate_row_version,
    (
        CASE
            WHEN ((ic.status)::text = 'EXCLUDED'::text) THEN 'EXCLUDED'::text
            WHEN (COALESCE(reason.active_count, 0) > 0) THEN 'QUALIFIED'::text
            ELSE 'PENDING'::text
        END)::character varying(100) AS candidate_qualification_status,
    COALESCE(reason.active_count, 0) AS active_matched_reason_count,
    (COALESCE(reason.codes, (ARRAY[]::text[])::character varying[]))::text[] AS active_matched_reason_codes,
    to_jsonb(COALESCE(reason.summaries, ARRAY[]::text[])) AS active_reason_summaries,
    (COALESCE(reason.codes, (ARRAY[]::text[])::character varying[]))::text AS matched_reason_codes_at_detection,
    to_jsonb(COALESCE(reason.summaries, ARRAY[]::text[])) AS matched_reason_summaries_at_detection,
    (reason.policy_version)::text AS risk_policy_version_at_detection,
    ic.detected_at AS candidate_detected_at,
    i.interview_id,
    i.status AS interview_status,
    ic.user_id AS target_user_id,
    u.name AS target_user_name,
    ic.project_id,
    p.name AS project_name,
    ic.assessment_round_id,
    r.round_name AS assessment_round_name,
    r.round_no AS analysis_sequence_no,
    (((p.project_category)::text = 'MINI_PROJECT'::text) AND (r.round_no = 1)) AS is_first_mini_project,
    ma.validity_review_status,
    ic.exclusion_reason_code,
    ic.exclusion_note,
    ic.excluded_by,
    ic.excluded_at,
    ((ic.status)::text = 'EXCLUDED'::text) AS can_reinclude_candidate,
    i.assignee_id,
    assignee.name AS assignee_name,
    i.planned_at,
    i.started_at,
    i.completed_at,
    i.completed_by AS completed_by_id,
    completer.name AS completed_by_name,
    i.result_summary,
    brief.brief_id AS confirmed_brief_id,
    COALESCE(act.activity_count, 0) AS interview_activity_count,
    COALESCE(act.follow_up_count, 0) AS follow_up_action_count,
    act.last_activity_at,
    (
        CASE
            WHEN ((ic.status)::text = 'EXCLUDED'::text) THEN 'REINCLUDE'::text
            WHEN (i.interview_id IS NULL) THEN 'CREATE_INTERVIEW'::text
            WHEN ((i.status)::text = 'PENDING'::text) THEN 'START_INTERVIEW'::text
            WHEN ((i.status)::text = 'IN_PROGRESS'::text) THEN 'CONTINUE_INTERVIEW'::text
            ELSE 'VIEW_INTERVIEW'::text
        END)::character varying(100) AS primary_action_code,
        CASE
            WHEN ((ic.status)::text = 'EXCLUDED'::text) THEN ARRAY['REINCLUDE'::text]
            WHEN (i.interview_id IS NULL) THEN ARRAY['CREATE_INTERVIEW'::text, 'EXCLUDE'::text]
            WHEN ((i.status)::text = 'PENDING'::text) THEN ARRAY['START_INTERVIEW'::text, 'EXCLUDE'::text]
            WHEN ((i.status)::text = 'IN_PROGRESS'::text) THEN ARRAY['CONTINUE_INTERVIEW'::text, 'COMPLETE_INTERVIEW'::text]
            ELSE ARRAY['VIEW_INTERVIEW'::text]
        END AS available_action_codes,
    NULL::character varying(100) AS action_unavailable_reason_code
   FROM (((((((((((((public.interview_candidate ic
     JOIN scope ON ((scope.class_id = ic.class_id)))
     JOIN public.class c ON ((c.class_id = ic.class_id)))
     LEFT JOIN public.team t ON ((t.team_id = ic.team_id)))
     JOIN public.app_user u ON ((u.user_id = ic.user_id)))
     JOIN public.project p ON ((p.project_id = ic.project_id)))
     JOIN public.project_assessment_round r ON ((r.assessment_round_id = ic.assessment_round_id)))
     LEFT JOIN public.interview i ON ((i.candidate_id = ic.candidate_id)))
     LEFT JOIN public.app_user assignee ON ((assignee.user_id = i.assignee_id)))
     LEFT JOIN public.app_user completer ON ((completer.user_id = i.completed_by)))
     LEFT JOIN LATERAL ( SELECT (count(*) FILTER (WHERE (((x.reason_status)::text = 'ACTIVE'::text) AND ((x.evaluation_status)::text = 'MATCHED'::text))))::integer AS active_count,
            array_agg(x.reason_code ORDER BY x.detected_at) FILTER (WHERE (((x.reason_status)::text = 'ACTIVE'::text) AND ((x.evaluation_status)::text = 'MATCHED'::text))) AS codes,
            array_agg(x.reason_summary ORDER BY x.detected_at) FILTER (WHERE (((x.reason_status)::text = 'ACTIVE'::text) AND ((x.evaluation_status)::text = 'MATCHED'::text))) AS summaries,
            max(x.policy_version) AS policy_version
           FROM public.interview_candidate_reason x
          WHERE (x.candidate_id = ic.candidate_id)) reason ON (true))
     LEFT JOIN LATERAL ( SELECT x.brief_id
           FROM public.interview_brief x
          WHERE ((x.interview_id = i.interview_id) AND ((x.status)::text = 'CONFIRMED'::text))
          ORDER BY x.version_no DESC
         LIMIT 1) brief ON (true))
     LEFT JOIN LATERAL ( SELECT (count(*))::integer AS activity_count,
            (count(*) FILTER (WHERE (x.next_action IS NOT NULL)))::integer AS follow_up_count,
            max(x.occurred_at) AS last_activity_at
           FROM public.interview_activity x
          WHERE (x.interview_id = i.interview_id)) act ON (true))
     LEFT JOIN LATERAL ( SELECT x.attempt_id,
            x.org_id,
            x.cohort_id,
            x.assessment_round_id,
            x.project_id,
            x.user_id,
            x.assessment_contract_version,
            x.source_submission_id,
            x.code_analysis_id,
            x.attempt_type,
            x.source_attempt_id,
            x.attempt_sequence_no,
            x.assigned_at,
            x.assigned_by,
            x.review_source_report_id,
            x.review_source_report_snapshot_id,
            x.review_due_at,
            x.status,
            x.terminal_reason_code,
            x.terminal_at,
            x.analysis_completed_at,
            x.assessment_open_at,
            x.assessment_close_at,
            x.validity_review_status,
            x.validity_trigger_reason_code,
            x.validity_decision_reason_code,
            x.validity_decision_note,
            x.validity_review_started_at,
            x.validity_reviewed_by,
            x.validity_reviewed_at,
            x.row_version,
            x.updated_at,
            x.outcome_type_code,
            x.outcome_verdict,
            x.outcome_policy_version,
            x.outcome_judged_at
           FROM public.measurement_attempt x
          WHERE ((x.assessment_round_id = ic.assessment_round_id) AND (x.user_id = ic.user_id) AND ((x.attempt_type)::text = 'INITIAL'::text))
          ORDER BY x.attempt_sequence_no DESC
         LIMIT 1) ma ON (true));


--
-- Name: manager_invalid_attempt_review_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.manager_invalid_attempt_review_view AS
 WITH scope AS (
         SELECT ma_1.manager_user_id,
            ma_1.class_id
           FROM public.manager_assignment ma_1
          WHERE (((ma_1.status)::text = 'ACTIVE'::text) AND (ma_1.unassigned_at IS NULL))
        )
 SELECT ma.org_id,
    scope.manager_user_id,
    ma.cohort_id,
    pm.class_id,
    c.name AS class_name,
    tm.team_id,
    t.name AS team_name,
    ma.project_id,
    p.name AS project_name,
    ma.assessment_round_id,
    r.round_name AS assessment_round_name,
    ma.user_id AS target_user_id,
    u.name AS target_user_name,
    ma.attempt_id,
    s.session_id,
    ma.status AS attempt_status,
    ma.terminal_reason_code,
    ma.validity_review_status,
    ma.validity_trigger_reason_code,
    ma.validity_decision_reason_code,
    ma.validity_decision_note,
    ma.validity_review_started_at,
    (ma.validity_reviewed_by)::text AS validity_reviewed_by,
    reviewer.name AS validity_reviewed_by_name,
    ma.validity_reviewed_at,
    ma.updated_at AS attempt_updated_at,
    ic.candidate_id,
    icr.candidate_reason_id,
    i.interview_id,
    ((ma.validity_review_status)::text = 'PENDING'::text) AS can_confirm_invalid,
    ((ma.validity_review_status)::text = 'CONFIRMED_INVALID'::text) AS can_restore_valid,
    (
        CASE
            WHEN ((ma.validity_review_status)::text <> ALL ((ARRAY['PENDING'::character varying, 'CONFIRMED_INVALID'::character varying])::text[])) THEN 'REVIEW_NOT_ACTIONABLE'::text
            ELSE NULL::text
        END)::character varying(100) AS action_unavailable_reason_code,
    ma.row_version,
    NULL::character varying(100) AS empty_state_code,
    'COMPLETE'::character varying(20) AS aggregation_status,
    CURRENT_TIMESTAMP AS as_of_at
   FROM (((((((((((((public.measurement_attempt ma
     JOIN public.project_membership pm ON (((pm.project_id = ma.project_id) AND (pm.user_id = ma.user_id))))
     JOIN scope ON ((scope.class_id = pm.class_id)))
     JOIN public.class c ON ((c.class_id = pm.class_id)))
     JOIN public.project p ON ((p.project_id = ma.project_id)))
     JOIN public.project_assessment_round r ON ((r.assessment_round_id = ma.assessment_round_id)))
     JOIN public.app_user u ON ((u.user_id = ma.user_id)))
     LEFT JOIN public.app_user reviewer ON ((reviewer.user_id = ma.validity_reviewed_by)))
     LEFT JOIN public.assessment_session s ON ((s.attempt_id = ma.attempt_id)))
     LEFT JOIN LATERAL ( SELECT x.team_id
           FROM public.team_membership x
          WHERE ((x.project_membership_id = pm.project_membership_id) AND (x.from_at <= COALESCE(ma.assessment_open_at, CURRENT_TIMESTAMP)) AND ((x.to_at IS NULL) OR (x.to_at > COALESCE(ma.assessment_open_at, CURRENT_TIMESTAMP))))
          ORDER BY x.from_at DESC
         LIMIT 1) tm ON (true))
     LEFT JOIN public.team t ON ((t.team_id = tm.team_id)))
     LEFT JOIN public.interview_candidate ic ON (((ic.assessment_round_id = ma.assessment_round_id) AND (ic.user_id = ma.user_id))))
     LEFT JOIN public.interview_candidate_reason icr ON (((icr.candidate_id = ic.candidate_id) AND ((icr.reason_code)::text = 'INVALID_ATTEMPT'::text) AND ((icr.reason_status)::text = 'ACTIVE'::text))))
     LEFT JOIN public.interview i ON ((i.candidate_id = ic.candidate_id)))
  WHERE ((ma.validity_review_status)::text = ANY ((ARRAY['PENDING'::character varying, 'CONFIRMED_INVALID'::character varying, 'RESTORED_VALID'::character varying])::text[]));


--
-- Name: manager_project_list_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.manager_project_list_view AS
 WITH manager_scope AS (
         SELECT ma.org_id,
            ma.manager_user_id,
            c.cohort_id,
            array_agg(DISTINCT ma.class_id ORDER BY ma.class_id) AS assigned_class_ids
           FROM (public.manager_assignment ma
             JOIN public.class c ON ((c.class_id = ma.class_id)))
          WHERE (((ma.status)::text = 'ACTIVE'::text) AND (ma.unassigned_at IS NULL))
          GROUP BY ma.org_id, ma.manager_user_id, c.cohort_id
        ), base AS (
         SELECT ms.org_id,
            ms.manager_user_id,
            ms.cohort_id,
            ms.assigned_class_ids,
            p.project_id,
            p.sequence_no,
            p.name AS project_name,
            p.project_category,
            p.lifecycle_status,
            r.assessment_round_id,
            r.round_name,
            r.round_no,
            r.status AS round_status,
            ( SELECT string_agg((cm.title)::text, ', '::text ORDER BY pc.sequence_no) AS string_agg
                   FROM ((public.project_curriculum pc
                     JOIN public.curriculum_version cv ON ((cv.version_id = pc.curriculum_version_id)))
                     JOIN public.curriculum_material cm ON ((cm.material_id = cv.material_id)))
                  WHERE (pc.project_id = p.project_id)) AS curriculum_summary,
            (( SELECT count(*) AS count
                   FROM (public.project_verification_concept pvc
                     JOIN public.project_verification_concept_set pcs ON ((pcs.concept_set_id = pvc.concept_set_id)))
                  WHERE ((pcs.project_id = p.project_id) AND ((pcs.status)::text = 'ACTIVE'::text))))::integer AS concept_count,
            (( SELECT count(*) AS count
                   FROM public.project_membership pm
                  WHERE ((pm.project_id = p.project_id) AND (pm.class_id = ANY (ms.assigned_class_ids)) AND ((pm.status)::text = 'ACTIVE'::text))))::integer AS assigned_trainee_count,
            (( SELECT count(*) AS count
                   FROM public.team t
                  WHERE ((t.project_id = p.project_id) AND (t.class_id = ANY (ms.assigned_class_ids)) AND (t.deleted_at IS NULL))))::integer AS team_count,
            (( SELECT count(*) AS count
                   FROM (public.repository repo
                     JOIN public.team t ON ((t.team_id = repo.team_id)))
                  WHERE ((t.project_id = p.project_id) AND (t.class_id = ANY (ms.assigned_class_ids)) AND ((repo.status)::text = 'ACTIVE'::text))))::integer AS repository_ready_team_count,
            (( SELECT count(DISTINCT s.team_id) AS count
                   FROM (public.submission s
                     JOIN public.team t ON ((t.team_id = s.team_id)))
                  WHERE ((t.project_id = p.project_id) AND (t.class_id = ANY (ms.assigned_class_ids)) AND (s.assessment_round_id = r.assessment_round_id) AND s.is_current)))::integer AS submitted_team_count,
            (( SELECT count(DISTINCT aj.team_id) AS count
                   FROM (public.analysis_job aj
                     JOIN public.team t ON ((t.team_id = aj.team_id)))
                  WHERE ((t.project_id = p.project_id) AND (t.class_id = ANY (ms.assigned_class_ids)) AND (aj.assessment_round_id = r.assessment_round_id) AND ((aj.status)::text = 'SUCCEEDED'::text))))::integer AS analysis_ready_team_count,
            (( SELECT count(DISTINCT ma2.user_id) AS count
                   FROM (public.measurement_attempt ma2
                     JOIN public.project_membership pm ON (((pm.user_id = ma2.user_id) AND (pm.project_id = p.project_id))))
                  WHERE ((ma2.assessment_round_id = r.assessment_round_id) AND ((ma2.attempt_type)::text = 'INITIAL'::text) AND ((ma2.status)::text = 'COMPLETED'::text) AND (pm.class_id = ANY (ms.assigned_class_ids)))))::integer AS assessment_completed_count
           FROM ((manager_scope ms
             JOIN public.project p ON (((p.cohort_id = ms.cohort_id) AND (p.deleted_at IS NULL))))
             LEFT JOIN public.project_assessment_round r ON (((r.project_id = p.project_id) AND (r.deleted_at IS NULL))))
        )
 SELECT org_id,
    manager_user_id,
    cohort_id,
    NULL::uuid AS selected_class_id,
    assigned_class_ids,
    project_id,
    sequence_no AS project_sequence_no,
    project_name,
    project_category,
    lifecycle_status AS project_status,
    assessment_round_id,
    round_name AS assessment_round_name,
    round_no AS assessment_round_no,
    round_status AS round_display_status,
    curriculum_summary,
    (
        CASE
            WHEN (concept_count = 3) THEN 'READY'::text
            WHEN (concept_count = 0) THEN 'EMPTY'::text
            ELSE 'INCOMPLETE'::text
        END)::character varying(100) AS concept_display_status,
    concept_count AS verification_concept_count,
    (
        CASE
            WHEN ((lifecycle_status)::text = 'CLOSED'::text) THEN 'CLOSED'::text
            WHEN (submitted_team_count = 0) THEN 'SUBMISSION'::text
            WHEN (analysis_ready_team_count < submitted_team_count) THEN 'ANALYSIS'::text
            WHEN (assessment_completed_count < assigned_trainee_count) THEN 'ASSESSMENT'::text
            ELSE 'RESULT'::text
        END)::character varying(30) AS execution_stage,
    'TRAINEE'::character varying(100) AS progress_unit_type,
    assessment_completed_count AS progress_completed_count,
    assigned_trainee_count AS progress_target_count,
    cardinality(assigned_class_ids) AS assigned_class_count,
    assigned_trainee_count,
    '[]'::jsonb AS lagging_class_summaries,
    (
        CASE
            WHEN (submitted_team_count < team_count) THEN 'ACTION_REQUIRED'::text
            ELSE 'OK'::text
        END)::character varying(100) AS action_summary_status,
    jsonb_build_array(jsonb_build_object('code', 'SUBMISSION', 'targetCount', GREATEST((team_count - submitted_team_count), 0)), jsonb_build_object('code', 'ANALYSIS', 'targetCount', GREATEST((submitted_team_count - analysis_ready_team_count), 0)), jsonb_build_object('code', 'ASSESSMENT', 'targetCount', GREATEST((assigned_trainee_count - assessment_completed_count), 0))) AS action_items,
    ARRAY['OPEN_PROJECT'::text, 'OPEN_SUBMISSION'::text, 'OPEN_RESULTS'::text] AS available_action_codes,
    ARRAY[]::text[] AS action_unavailable_reason_codes,
    repository_ready_team_count,
    submitted_team_count,
    analysis_ready_team_count,
    assessment_completed_count,
    'COMPLETE'::character varying(20) AS aggregation_status,
    CURRENT_TIMESTAMP AS as_of_at
   FROM base x;


--
-- Name: report_evidence; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.report_evidence (
    evidence_id uuid DEFAULT gen_random_uuid() NOT NULL,
    snapshot_id uuid NOT NULL,
    metric_id uuid,
    problem_id uuid,
    problem_stage_id uuid,
    source_assessment_round_id uuid,
    source_snapshot_id uuid,
    subject_user_id uuid,
    subject_class_id uuid,
    source_class_id uuid,
    source_type character varying(100),
    source_ref_id text,
    evidence_category character varying(100) NOT NULL,
    participant_section_code character varying(100),
    source_role_code character varying(100),
    result_category_code character varying(100),
    baseline_value numeric(18,6),
    outcome_value numeric(18,6),
    eligibility_status character varying(100),
    exclusion_reason_code character varying(100),
    occurrence_count integer,
    big_project_minimum_reached_level integer,
    is_joint_top boolean,
    top_tie_count integer,
    subject_display_snapshot jsonb,
    axis_code character varying(10),
    decision_code character varying(100),
    evidence_summary text,
    quote_excerpt text,
    display_order integer,
    filter_snapshot jsonb NOT NULL,
    policy_version integer,
    trace_payload jsonb NOT NULL,
    CONSTRAINT ck_report_evidence_big_project_minimum_reached_level CHECK (((big_project_minimum_reached_level IS NULL) OR ((big_project_minimum_reached_level >= 0) AND (big_project_minimum_reached_level <= 4)))),
    CONSTRAINT ck_report_evidence_display_order CHECK (((display_order IS NULL) OR (display_order > 0))),
    CONSTRAINT ck_report_evidence_eligibility_status CHECK (((eligibility_status)::text = ANY ((ARRAY['ELIGIBLE'::character varying, 'EXCLUDED'::character varying])::text[]))),
    CONSTRAINT ck_report_evidence_evidence_category CHECK (((evidence_category)::text = ANY ((ARRAY['CURRICULUM_LOCATION'::character varying, 'RESULT_EXPLANATION'::character varying, 'ANSWER_EXCERPT'::character varying, 'METRIC_TRACE'::character varying, 'REPORT_SOURCE_ROUND'::character varying, 'REPORT_SOURCE_SNAPSHOT'::character varying, 'PARTICIPANT_RESULT'::character varying, 'PARTICIPANT_RESULT_OCCURRENCE'::character varying])::text[]))),
    CONSTRAINT ck_report_evidence_evidence_category_2 CHECK (((((evidence_category)::text = 'METRIC_TRACE'::text) AND (metric_id IS NOT NULL)) OR (((evidence_category)::text = 'REPORT_SOURCE_ROUND'::text) AND (source_assessment_round_id IS NOT NULL)) OR (((evidence_category)::text = 'REPORT_SOURCE_SNAPSHOT'::text) AND (source_snapshot_id IS NOT NULL)) OR (((evidence_category)::text = 'PARTICIPANT_RESULT'::text) AND (subject_user_id IS NOT NULL)) OR (((evidence_category)::text = 'PARTICIPANT_RESULT_OCCURRENCE'::text) AND (subject_user_id IS NOT NULL) AND (source_assessment_round_id IS NOT NULL) AND (source_class_id IS NOT NULL)) OR (((evidence_category)::text = 'ANSWER_EXCERPT'::text) AND (num_nonnulls(problem_id, problem_stage_id) > 0)) OR ((evidence_category)::text = ANY ((ARRAY['CURRICULUM_LOCATION'::character varying, 'RESULT_EXPLANATION'::character varying])::text[])))),
    CONSTRAINT ck_report_evidence_exclusion_reason_code CHECK (((exclusion_reason_code)::text = ANY ((ARRAY['NOT_ATTENDED_INCLUDED'::character varying, 'INVALID_INCLUDED'::character varying, 'INTERRUPTED_INCLUDED'::character varying])::text[]))),
    CONSTRAINT ck_report_evidence_occurrence_count CHECK (((occurrence_count IS NULL) OR (occurrence_count >= 0))),
    CONSTRAINT ck_report_evidence_participant_section_code CHECK (((participant_section_code)::text = ANY ((ARRAY['GROWTH_TRANSITION'::character varying, 'EXCELLENT_TRAINEE'::character varying])::text[]))),
    CONSTRAINT ck_report_evidence_policy_version CHECK (((policy_version IS NULL) OR (policy_version > 0))),
    CONSTRAINT ck_report_evidence_result_category_code CHECK (((result_category_code)::text = ANY ((ARRAY['LOW_TO_HIGH'::character varying, 'LOW_TO_LOW'::character varying, 'HIGH_TO_HIGH'::character varying, 'HIGH_TO_LOW'::character varying, 'MINI_CLASS_TOP'::character varying])::text[]))),
    CONSTRAINT ck_report_evidence_source_ref_id CHECK ((((source_type IS NULL) AND (source_ref_id IS NULL)) OR ((source_type IS NOT NULL) AND (source_ref_id IS NOT NULL)))),
    CONSTRAINT ck_report_evidence_source_ref_id_2 CHECK ((NOT ((source_type IS NOT NULL) AND (source_ref_id IS NOT NULL) AND (num_nonnulls(problem_id, problem_stage_id, source_assessment_round_id, source_snapshot_id, subject_user_id, subject_class_id, source_class_id) > 0)))),
    CONSTRAINT ck_report_evidence_source_role_code CHECK (((source_role_code)::text = ANY ((ARRAY['GROWTH_LAST_MINI'::character varying, 'GROWTH_BIG_ROUND'::character varying, 'OUTCOME_FINAL_MINI'::character varying, 'EXCELLENT_MINI_OCCURRENCE'::character varying])::text[]))),
    CONSTRAINT ck_report_evidence_top_tie_count CHECK (((top_tie_count IS NULL) OR (top_tie_count > 0))),
    CONSTRAINT ck_report_evidence_top_tie_count_2 CHECK (((is_joint_top IS DISTINCT FROM true) OR (top_tie_count >= 2)))
);


--
-- Name: TABLE report_evidence; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.report_evidence IS '리포트 수치·개인 축 판정·출처 회차·참여자 결과·우수 발생의 원천 FK와 공개용 발췌를 보존합니다. | 정의서명: ReportEvidence | 제약·비고: • evidence_category: CURRICULUM_LOCATION / RESULT_EXPLANATION / ANSWER_EXCERPT / METRIC_TRACE / REPORT_SOURCE_ROUND / REPORT_SOURCE_SNAPSHOT / PARTICIPANT_RESULT / PARTICIPANT_RESULT_OCCURRENCE • metric_id는 지표 trace에서는 필수지만 참여자 결과·출처 회차 근거에서는 NULL을 허용합니다. • 문제·세션별 문제 단계·회차·스냅샷·사용자·반 FK는 원천 종류에 따라 조건부로 사용합니다. • CURRICULUM_LOCATION은 별도 교안-개념 FK를 추가하지 않고 teachId·unitId·sourcePages·studyPointer를 trace_payload JSONB에 발행 당시 값으로 보존합니다. • 개념별 취약도 집계는 ReportMetric의 teaches_id와 metric_grain_code=''CONCEPT'' 또는 ''ROUND_CONCEPT'' 경로를 사용합니다. • 성장 요약은 마지막 미니 결과·빅프로젝트 평균 원값·기술 제외 사유를 고정합니다. • 우수 발생은 판정 당시 반·회차·공동 1위 여부·동점 인원 수를 고정합니다. • 형식화 FK와 source_type/source_ref_id로 같은 원천을 중복 표현하지 않습니다. • 원천 전문을 복제하지 않고 식별자·요약·길이 제한된 마스킹 발췌만 저장합니다. • 근거 열람은 최신 ManagerAssignment를 검증하고 허용·거부를 AuditLog에 기록합니다. • 감사 기록 실패 시 민감 근거 응답을 ';


