--
-- Name: report_generation_run; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.report_generation_run (
    generation_run_id uuid DEFAULT gen_random_uuid() NOT NULL,
    report_id uuid NOT NULL,
    trigger_type character varying(100) NOT NULL,
    idempotency_key text NOT NULL,
    calculation_version integer NOT NULL,
    status character varying(100) NOT NULL,
    failure_reason text,
    execution_no integer NOT NULL,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    request_fingerprint character(64) NOT NULL,
    CONSTRAINT ck_report_generation_run_calculation_version CHECK ((calculation_version > 0)),
    CONSTRAINT ck_report_generation_run_execution_no CHECK ((execution_no > 0)),
    CONSTRAINT ck_report_generation_run_request_fingerprint CHECK ((request_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT ck_report_generation_run_status CHECK (((status)::text = ANY ((ARRAY['QUEUED'::character varying, 'RUNNING'::character varying, 'COMPLETED'::character varying, 'PARTIAL'::character varying, 'FAILED'::character varying, 'RETRYING'::character varying])::text[]))),
    CONSTRAINT ck_report_generation_run_status_2 CHECK (((((status)::text = 'QUEUED'::text) AND (started_at IS NULL) AND (completed_at IS NULL) AND (failure_reason IS NULL)) OR (((status)::text = ANY ((ARRAY['RUNNING'::character varying, 'RETRYING'::character varying])::text[])) AND (started_at IS NOT NULL) AND (completed_at IS NULL)) OR (((status)::text = ANY ((ARRAY['COMPLETED'::character varying, 'PARTIAL'::character varying])::text[])) AND (started_at IS NOT NULL) AND (completed_at IS NOT NULL) AND (failure_reason IS NULL)) OR (((status)::text = 'FAILED'::text) AND (completed_at IS NOT NULL) AND (failure_reason IS NOT NULL))))
);


--
-- Name: TABLE report_generation_run; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.report_generation_run IS '리포트 생성·재생성·재시도를 APPEND-ONLY 실행 이력으로 보존합니다. 생성 완료와 실제 발행·교육생 공개는 서로 다른 상태입니다. | 정의서명: ReportGenerationRun | 제약·비고: • 상태: QUEUED / RUNNING / COMPLETED / PARTIAL / FAILED / RETRYING • execution_no > 0이며 같은 report_id·trigger_type·업무 키 안에서 불변 증가합니다. • 재시도는 기존 행의 retry_count를 갱신하지 않고 execution_no+1 새 행으로 생성합니다. • 같은 report_id의 같은 생성 업무에서 QUEUED/RUNNING/RETRYING 활성 실행은 최대 1건입니다. • COMPLETED·PARTIAL이면 completed_at이 필수이고 FAILED이면 failure_reason이 필수입니다. • idempotency_key는 같은 요청 지문 하나에만 대응하며 동일 키·다른 지문은 거부합니다. • 원천 진행 중에는 공식 생성 실행을 만들지 않습니다. • 문제별 /reports 응답은 같은 생성 실행 안에서 버퍼링하고 모든 문제 종료 후 ReportSnapshot 1건으로 확정합니다. • reportMarkdown·narrative·versions(modelCode·promptVersion·rubricVersion)는 생성 실행 컬럼에 중복 저장하지 않고 ReportSnapshot.summary_payload에 보존합니다. • scheduled_publish_at·published_at·교육생 공개 상태를 저장하지 않습니다.';


