--
-- Name: report_metric; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.report_metric (
    metric_id uuid DEFAULT gen_random_uuid() NOT NULL,
    snapshot_id uuid NOT NULL,
    section_code character varying(100) NOT NULL,
    metric_grain_code character varying(100) NOT NULL,
    metric_code character varying(100) NOT NULL,
    dimension_key text,
    dimension_value numeric(18,6),
    project_id uuid,
    source_assessment_round_id uuid,
    project_verification_concept_id uuid,
    class_id uuid,
    curriculum_material_id uuid,
    curriculum_version_id uuid,
    curriculum_section_id uuid,
    teaches_id uuid,
    reached_level integer,
    metric_value numeric(18,6),
    numerator numeric(18,6),
    denominator numeric(18,6),
    missing_count integer DEFAULT 0,
    policy_version integer,
    aggregation_status character varying(20),
    aggregation_policy_version integer,
    policy_parameter_snapshot jsonb,
    dimension_snapshot jsonb,
    display_order integer,
    source_snapshot_version integer NOT NULL,
    display_scope character varying(100) NOT NULL,
    CONSTRAINT ck_report_metric_aggregation_policy_version CHECK (((aggregation_policy_version IS NULL) OR (aggregation_policy_version > 0))),
    CONSTRAINT ck_report_metric_aggregation_status CHECK (((aggregation_status)::text = ANY ((ARRAY['SINGLE_SOURCE'::character varying, 'MULTIPLE_SOURCE_ROUNDS'::character varying, 'CALCULATED'::character varying, 'POLICY_REQUIRED'::character varying, 'FAILED'::character varying])::text[]))),
    CONSTRAINT ck_report_metric_denominator CHECK (((denominator IS NULL) OR (denominator >= (0)::numeric))),
    CONSTRAINT ck_report_metric_display_order CHECK (((display_order IS NULL) OR (display_order > 0))),
    CONSTRAINT ck_report_metric_display_scope CHECK (((display_scope)::text = ANY ((ARRAY['TRAINEE'::character varying, 'MANAGER'::character varying, 'OPERATOR'::character varying, 'INTERNAL'::character varying])::text[]))),
    CONSTRAINT ck_report_metric_metric_grain_code CHECK (((metric_grain_code)::text = ANY ((ARRAY['REPORT'::character varying, 'CURRICULUM'::character varying, 'CONCEPT'::character varying, 'CONCEPT_REACHED_LEVEL'::character varying, 'ROUND'::character varying, 'ROUND_CONCEPT'::character varying, 'ROUND_CONCEPT_REACHED_LEVEL'::character varying, 'TRANSITION_CATEGORY'::character varying, 'CLASS'::character varying, 'CLASS_CONCEPT'::character varying])::text[]))),
    CONSTRAINT ck_report_metric_metric_grain_code_2 CHECK (((((metric_grain_code)::text = 'REPORT'::text) AND (num_nonnulls(project_id, source_assessment_round_id, project_verification_concept_id, class_id, curriculum_material_id, curriculum_version_id, curriculum_section_id, teaches_id, reached_level) = 0)) OR (((metric_grain_code)::text = 'CURRICULUM'::text) AND (curriculum_version_id IS NOT NULL)) OR (((metric_grain_code)::text = ANY ((ARRAY['CONCEPT'::character varying, 'CONCEPT_REACHED_LEVEL'::character varying])::text[])) AND (num_nonnulls(project_verification_concept_id, teaches_id) = 1)) OR (((metric_grain_code)::text = 'ROUND'::text) AND (source_assessment_round_id IS NOT NULL)) OR (((metric_grain_code)::text = ANY ((ARRAY['ROUND_CONCEPT'::character varying, 'ROUND_CONCEPT_REACHED_LEVEL'::character varying])::text[])) AND (source_assessment_round_id IS NOT NULL) AND (num_nonnulls(project_verification_concept_id, teaches_id) = 1)) OR (((metric_grain_code)::text = 'TRANSITION_CATEGORY'::text) AND (dimension_key IS NOT NULL)) OR (((metric_grain_code)::text = 'CLASS'::text) AND (class_id IS NOT NULL)) OR (((metric_grain_code)::text = 'CLASS_CONCEPT'::text) AND (class_id IS NOT NULL) AND (num_nonnulls(project_verification_concept_id, teaches_id) = 1)))),
    CONSTRAINT ck_report_metric_missing_count CHECK ((missing_count >= 0)),
    CONSTRAINT ck_report_metric_numerator CHECK (((numerator IS NULL) OR (numerator >= (0)::numeric))),
    CONSTRAINT ck_report_metric_policy_version CHECK (((policy_version IS NULL) OR (policy_version > 0))),
    CONSTRAINT ck_report_metric_reached_level CHECK (((reached_level IS NULL) OR ((reached_level >= 0) AND (reached_level <= 4)))),
    CONSTRAINT ck_report_metric_section_code CHECK (((section_code)::text = ANY ((ARRAY['CURRICULUM_DIAGNOSIS_SUMMARY'::character varying, 'CONCEPT_REACH_DISTRIBUTION'::character varying, 'ROUND_CONCEPT_RESULT'::character varying, 'COHORT_OUTCOME_SUMMARY'::character varying, 'COHORT_GROWTH_TRANSITION'::character varying, 'EXCELLENT_TRAINEE'::character varying, 'CLASS_RISK'::character varying, 'GROUP_UNDERPERFORMANCE'::character varying])::text[]))),
    CONSTRAINT ck_report_metric_source_snapshot_version CHECK ((source_snapshot_version > 0))
);


--
-- Name: TABLE report_metric; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.report_metric IS '리포트 스냅샷의 수업 진단·단계 분포·성장·반 위험·집단 미달·결측 지표를 명시적 섹션·grain·차원 FK와 정책 스냅샷으로 보존합니다. | 정의서명: ReportMetric | 제약·비고: • display_scope: TRAINEE / MANAGER / OPERATOR / INTERNAL • 수업 진단 section_code: CURRICULUM_DIAGNOSIS_SUMMARY / CONCEPT_REACH_DISTRIBUTION / ROUND_CONCEPT_RESULT • 기수 결산 section_code: COHORT_OUTCOME_SUMMARY / COHORT_GROWTH_TRANSITION / EXCELLENT_TRAINEE / CLASS_RISK / GROUP_UNDERPERFORMANCE • metric_grain_code: REPORT / CURRICULUM / CONCEPT / CONCEPT_REACHED_LEVEL / ROUND / ROUND_CONCEPT / ROUND_CONCEPT_REACHED_LEVEL / TRANSITION_CATEGORY / CLASS / CLASS_CONCEPT • 문자열 이름만으로 차원을 식별하지 않고 가능한 경우 정식 FK를 사용합니다. • 발행 당시 표시 이름·순서는 dimension_snapshot에 고정합니다. • 단계 분포 denominator는 L0~L4 합계와 일치해야 하며 저단계 수는 L0+L1+L2로 계산합니다. • 정책 경계·임계치는 policy_parameter_snapshot에 고정합니다. • 공식 결과 지표는 INITIAL 수행만 사용하고 미응시·무효·중단·기술 결측을 별도 결측으로 보존합니다. • metric_value·denominator·missing_count는 아직 미계산 또는 집계 실패 시 NULL을 ';


