--
-- Name: manager_project_result_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.manager_project_result_view AS
 SELECT rpt.org_id,
    rpt.cohort_id,
    ar.project_id,
    rpt.assessment_round_id,
    pm.class_id,
    tm.team_id,
    rpt.user_id,
    rpt.report_id,
    rpt.report_type,
    rpt.lifecycle_status,
    gr.status AS latest_generation_status,
    rs.snapshot_id AS report_snapshot_id,
    rs.completion_status,
    rpt.published_at,
    rpt.trainee_release_status,
    rpt.trainee_disclosure_scope,
    (COALESCE(rs.sample_count, 0) + COALESCE(rs.missing_count, 0)) AS eligible_trainee_count,
    COALESCE(rs.sample_count, 0) AS assessed_trainee_count,
    rs.sample_count,
    rs.missing_count,
    (((rs.completion_status)::text = 'PARTIAL'::text) OR (rpt.published_at IS NULL)) AS is_provisional,
    ma.attempt_id,
    ma.validity_review_status,
    ma.terminal_reason_code,
    ap.problem_id,
    ap.problem_scope,
    ap.project_verification_concept_id,
    (COALESCE((re.subject_display_snapshot ->> 'conceptName'::text), (tch.canonical_name)::text))::character varying(200) AS concept_display_name_snapshot,
    COALESCE(rm.display_order, pvc.sequence_no) AS concept_display_order,
        CASE ap.best_success_stage
            WHEN 'L4'::text THEN 4
            WHEN 'L3'::text THEN 3
            WHEN 'L2'::text THEN 2
            WHEN 'L1'::text THEN 1
            ELSE 0
        END AS highest_reached_level,
    (
        CASE
            WHEN ((ap.generation_status)::text = 'NOT_GENERATED'::text) THEN 'NO_PROBLEM'::text
            WHEN ((ma.validity_review_status)::text = 'CONFIRMED_INVALID'::text) THEN 'INVALID'::text
            WHEN ((ma.status)::text = 'COMPLETED'::text) THEN 'AVAILABLE'::text
            ELSE 'PENDING'::text
        END)::character varying(100) AS result_display_status,
    ps.axis_code,
    (ps.status)::character varying(100) AS stage_status,
    ((((ps.question_answer_text IS NOT NULL))::integer + ((ps.first_hint_answer_text IS NOT NULL))::integer) + ((ps.second_hint_answer_text IS NOT NULL))::integer) AS answer_attempt_count,
    (COALESCE(ps.second_hint_score, ps.first_hint_score, ps.question_score))::numeric(18,6) AS score,
    (
        CASE
            WHEN (ps.second_hint_answer_text IS NOT NULL) THEN 'SECOND_HINT'::text
            WHEN (ps.first_hint_answer_text IS NOT NULL) THEN 'FIRST_HINT'::text
            ELSE 'NONE'::text
        END)::character varying(100) AS assistance_display_code,
    (
        CASE
            WHEN ((re.evidence_id IS NOT NULL) AND ((re.evidence_category)::text = 'ANSWER_EXCERPT'::text)) THEN 'TARGET'::text
            ELSE 'NOT_TARGET'::text
        END)::character varying(100) AS review_target_status,
    (re.evidence_id IS NOT NULL) AS internal_evidence_available,
    ((re.evidence_id IS NOT NULL) AND ((rpt.trainee_release_status)::text = 'RELEASED'::text)) AS trainee_evidence_available,
    (COALESCE(rm.aggregation_status, 'SINGLE_SOURCE'::character varying))::character varying(20) AS aggregation_status,
    rs.as_of_at,
    rs.calculation_version
   FROM ((((((((((((public.report rpt
     JOIN public.report_snapshot rs ON (((rs.report_id = rpt.report_id) AND rs.is_active)))
     LEFT JOIN LATERAL ( SELECT x.generation_run_id,
            x.report_id,
            x.trigger_type,
            x.idempotency_key,
            x.calculation_version,
            x.status,
            x.failure_reason,
            x.execution_no,
            x.started_at,
            x.completed_at,
            x.request_fingerprint
           FROM public.report_generation_run x
          WHERE (x.report_id = rpt.report_id)
          ORDER BY x.execution_no DESC
         LIMIT 1) gr ON (true))
     LEFT JOIN public.project_assessment_round ar ON ((ar.assessment_round_id = rpt.assessment_round_id)))
     LEFT JOIN public.measurement_attempt ma ON (((ma.assessment_round_id = rpt.assessment_round_id) AND (ma.user_id = rpt.user_id) AND ((ma.attempt_type)::text = 'INITIAL'::text))))
     LEFT JOIN public.project_membership pm ON (((pm.project_id = ar.project_id) AND (pm.user_id = rpt.user_id))))
     LEFT JOIN LATERAL ( SELECT x.team_id
           FROM public.team_membership x
          WHERE ((x.project_membership_id = pm.project_membership_id) AND (x.from_at <= COALESCE(ma.assessment_open_at, rs.as_of_at)) AND ((x.to_at IS NULL) OR (x.to_at > COALESCE(ma.assessment_open_at, rs.as_of_at))))
          ORDER BY x.from_at DESC
         LIMIT 1) tm ON (true))
     LEFT JOIN public.assessment_problem ap ON (((ap.measurement_attempt_id = ma.attempt_id) OR (ap.code_analysis_id = ma.code_analysis_id))))
     LEFT JOIN public.problem_stage ps ON ((ps.problem_id = ap.problem_id)))
     LEFT JOIN public.project_verification_concept pvc ON ((pvc.project_concept_id = ap.project_verification_concept_id)))
     LEFT JOIN public.teaches tch ON ((tch.teaches_id = pvc.teaches_id)))
     LEFT JOIN public.report_metric rm ON (((rm.snapshot_id = rs.snapshot_id) AND ((rm.project_verification_concept_id = ap.project_verification_concept_id) OR ((rm.metric_grain_code)::text = 'REPORT'::text)))))
     LEFT JOIN public.report_evidence re ON (((re.snapshot_id = rs.snapshot_id) AND ((re.problem_id = ap.problem_id) OR (re.problem_stage_id = ps.problem_stage_id)))))
  WHERE (rpt.user_id IS NOT NULL);


--
-- Name: project_requirement; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.project_requirement (
    requirement_id uuid DEFAULT gen_random_uuid() NOT NULL,
    project_id uuid NOT NULL,
    org_id uuid NOT NULL,
    requirement_key character varying(100) NOT NULL,
    version_no integer NOT NULL,
    sequence_no integer NOT NULL,
    title character varying(200) NOT NULL,
    description text NOT NULL,
    active boolean DEFAULT true NOT NULL,
    effective_from timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    effective_to timestamp with time zone,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT ck_project_requirement_effective_to CHECK (((effective_to IS NULL) OR (effective_to > effective_from))),
    CONSTRAINT ck_project_requirement_sequence_no CHECK ((sequence_no > 0)),
    CONSTRAINT ck_project_requirement_version_no CHECK ((version_no > 0))
);


--
-- Name: TABLE project_requirement; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.project_requirement IS '프로젝트 생성·구성에서 입력하는 구현 요구사항을 버전별로 보존합니다. 교안 개념과 PLAN 질문 초점과는 별개의 P/F 판정 대상이며 과거 판정이 참조한 버전은 수정·삭제하지 않습니다. | 정의서명: ProjectRequirement | 제약·비고: • version_no > 0, sequence_no > 0 • UNIQUE(project_id, requirement_key, version_no) • 같은 project_id + requirement_key의 현재 활성 버전은 최대 1건입니다. • active=TRUE이면 일반적으로 effective_to IS NULL이고 종료 버전은 effective_to가 effective_from보다 이후여야 합니다. • 요구사항 변경은 기존 행 수정 대신 기존 활성 버전 종료와 신규 version_no 생성을 한 트랜잭션으로 처리합니다. • ProjectRequirementAssessment가 존재하는 버전은 내용 수정·물리 삭제를 금지합니다. • 요구사항은 교안·검증 개념·ProjectAssessmentRound 질문 초점과 분리합니다.';


--
-- Name: COLUMN project_requirement.requirement_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.project_requirement.requirement_id IS '요구사항 버전 행을 식별하는 기본키이다.';


--
-- Name: COLUMN project_requirement.project_id; Type: COMMENT; Schema: public; Owner: -
