--
-- Name: manager_project_submission_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.manager_project_submission_view AS
 WITH class_base AS (
         SELECT p.org_id,
            p.cohort_id,
            p.project_id,
            p.lifecycle_status AS project_status,
            r.assessment_round_id,
            r.submission_due_at,
            c.class_id,
            (( SELECT count(*) AS count
                   FROM public.project_membership pm_1
                  WHERE ((pm_1.project_id = p.project_id) AND (pm_1.class_id = c.class_id) AND ((pm_1.status)::text = 'ACTIVE'::text))))::integer AS eligible_member_count,
            (( SELECT count(*) AS count
                   FROM public.team t_1
                  WHERE ((t_1.project_id = p.project_id) AND (t_1.class_id = c.class_id) AND (t_1.deleted_at IS NULL))))::integer AS team_count,
            (( SELECT count(*) AS count
                   FROM public.team t_1
                  WHERE ((t_1.project_id = p.project_id) AND (t_1.class_id = c.class_id) AND (t_1.deleted_at IS NULL) AND ((t_1.status)::text <> 'CONFIRMED'::text))))::integer AS unconfirmed_team_count,
            (( SELECT count(DISTINCT tm_1.project_membership_id) AS count
                   FROM (public.team_membership tm_1
                     JOIN public.team t_1 ON ((t_1.team_id = tm_1.team_id)))
                  WHERE ((t_1.project_id = p.project_id) AND (t_1.class_id = c.class_id) AND (tm_1.to_at IS NULL))))::integer AS assigned_member_count,
            ((( SELECT count(*) AS count
                   FROM public.project_membership pm_1
                  WHERE ((pm_1.project_id = p.project_id) AND (pm_1.class_id = c.class_id) AND ((pm_1.status)::text = 'ACTIVE'::text))))::integer - (( SELECT count(DISTINCT tm_1.project_membership_id) AS count
                   FROM (public.team_membership tm_1
                     JOIN public.team t_1 ON ((t_1.team_id = tm_1.team_id)))
                  WHERE ((t_1.project_id = p.project_id) AND (t_1.class_id = c.class_id) AND (tm_1.to_at IS NULL))))::integer) AS unassigned_member_count,
            (( SELECT count(DISTINCT s.team_id) AS count
                   FROM (public.submission s
                     JOIN public.team t_1 ON ((t_1.team_id = s.team_id)))
                  WHERE ((t_1.project_id = p.project_id) AND (t_1.class_id = c.class_id) AND (s.assessment_round_id = r.assessment_round_id) AND s.is_current)))::integer AS submitted_team_count,
            (( SELECT count(DISTINCT aj_1.team_id) AS count
                   FROM (public.analysis_job aj_1
                     JOIN public.team t_1 ON ((t_1.team_id = aj_1.team_id)))
                  WHERE ((t_1.project_id = p.project_id) AND (t_1.class_id = c.class_id) AND (aj_1.assessment_round_id = r.assessment_round_id) AND ((aj_1.status)::text = 'FAILED'::text))))::integer AS analysis_failed_team_count
           FROM ((public.project p
             JOIN public.project_assessment_round r ON (((r.project_id = p.project_id) AND (r.deleted_at IS NULL))))
             JOIN public.class c ON (((c.cohort_id = p.cohort_id) AND (c.deleted_at IS NULL))))
          WHERE (p.deleted_at IS NULL)
        )
 SELECT b.org_id,
    b.cohort_id,
    b.project_id,
    b.assessment_round_id,
    b.class_id,
        CASE
            WHEN ((b.project_status)::text = 'CLOSED'::text) THEN 'CLOSED'::text
            WHEN (b.team_count = 0) THEN 'NOT_STARTED'::text
            WHEN (b.unassigned_member_count > 0) THEN 'FORMING'::text
            WHEN (b.unconfirmed_team_count > 0) THEN 'READY_TO_CONFIRM'::text
            ELSE 'CONFIRMED'::text
        END AS team_formation_stage,
    b.team_count,
    b.eligible_member_count,
    b.assigned_member_count,
    b.unassigned_member_count,
    b.team_count AS submission_target_team_count,
    b.submitted_team_count,
    GREATEST((b.team_count - b.submitted_team_count), 0) AS unsubmitted_team_count,
    b.analysis_failed_team_count,
    b.submission_due_at,
    (GREATEST((EXTRACT(epoch FROM (b.submission_due_at - CURRENT_TIMESTAMP)))::bigint, (0)::bigint))::integer AS remaining_submission_seconds,
    (((b.project_status)::text <> ALL ((ARRAY['RUNNING'::character varying, 'CLOSED'::character varying])::text[])) AND (b.submitted_team_count = 0)) AS can_auto_assign,
    (((b.project_status)::text <> ALL ((ARRAY['RUNNING'::character varying, 'CLOSED'::character varying])::text[])) AND (b.submitted_team_count = 0)) AS can_add_team,
    ((b.project_status)::text <> ALL ((ARRAY['RUNNING'::character varying, 'CLOSED'::character varying])::text[])) AS can_assign_unassigned_member,
    ((b.unassigned_member_count = 0) AND (b.team_count > 0) AND (b.unconfirmed_team_count > 0)) AS can_confirm,
    ((b.submitted_team_count = 0) AND ((b.project_status)::text <> 'CLOSED'::text)) AS can_reopen,
    t.team_id,
    t.team_number,
    t.name AS team_name,
    (t.status)::character varying(100) AS team_status,
    (
        CASE
            WHEN (sub.submission_id IS NOT NULL) THEN 'SUBMITTED'::character varying
            WHEN ((t.status)::text = 'CONFIRMED'::text) THEN 'CONFIRMED'::character varying
            WHEN (t.team_id IS NULL) THEN 'UNASSIGNED'::character varying
            ELSE t.status
        END)::character varying(100) AS team_display_status,
    ts.member_count,
    t.min_member_count,
    t.max_member_count,
    (
        CASE
            WHEN (t.max_member_count IS NULL) THEN NULL::integer
            ELSE GREATEST((t.max_member_count - COALESCE(ts.member_count, 0)), 0)
        END)::text AS remaining_capacity,
    repo.repo_url AS repository_url,
    sub.submission_id,
    sub.method AS submission_method,
    sub.status AS submission_status,
    sub.submitted_by AS submitted_by_user_id,
    submitter.name AS submitted_by_name,
    sub.submitted_at,
    aj.job_id AS analysis_job_id,
    aj.status AS analysis_status,
    ca.analysis_id AS code_analysis_id,
    array_remove(ARRAY[
        CASE
            WHEN ((sub.submission_id IS NULL) AND (CURRENT_TIMESTAMP <= b.submission_due_at)) THEN 'SUBMISSION_MISSING'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((sub.submission_id IS NULL) AND (CURRENT_TIMESTAMP > b.submission_due_at)) THEN 'SUBMISSION_MISSED'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((aj.status)::text = 'FAILED'::text) THEN 'ANALYSIS_FAILED'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((t.status)::text <> 'CONFIRMED'::text) THEN 'TEAM_NOT_CONFIRMED'::text
            ELSE NULL::text
        END], NULL::text) AS team_lag_reason_codes,
    pm.project_membership_id,
    pm.user_id,
    u.name AS user_name,
    att.primary_attempt_id,
    att.primary_attempt_status,
    att.primary_assessment_open_at AS assessment_open_at,
    att.primary_assessment_close_at AS assessment_close_at,
    ma.terminal_at AS assessment_completed_at,
    (COALESCE(pr.levels, '[]'::jsonb))::text AS problem_highest_levels,
    array_remove(ARRAY[
        CASE
            WHEN (att.primary_attempt_id IS NULL) THEN 'ATTEMPT_NOT_CREATED'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (((att.primary_attempt_status)::text = ANY ((ARRAY['NOT_STARTED'::character varying, 'SESSION_READY'::character varying])::text[])) AND (att.primary_assessment_close_at > CURRENT_TIMESTAMP)) THEN 'ASSESSMENT_NOT_STARTED'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((att.primary_attempt_status)::text = 'EXPIRED'::text) THEN 'ASSESSMENT_EXPIRED'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((ma.validity_review_status)::text = 'CONFIRMED_INVALID'::text) THEN 'INVALID_ATTEMPT'::text
            ELSE NULL::text
        END], NULL::text) AS individual_lag_reason_codes,
    req.requirement_id,
    (req.result)::character varying(100) AS requirement_result,
    req.evidence_summary,
    req.evidence_locations,
    req.assessment_version AS requirement_assessment_version,
    att.as_of_at AS latest_reminder_at,
    att.nudge_reason_code AS reminder_reason_code,
    att.latest_reminder_status AS reminder_status,
    jsonb_build_object('team', t.row_version, 'attempt', ma.row_version) AS row_versions,
    CURRENT_TIMESTAMP AS as_of_at,
    'COMPLETE'::character varying(20) AS aggregation_status
   FROM ((((((((((((((class_base b
     LEFT JOIN public.team t ON (((t.project_id = b.project_id) AND (t.class_id = b.class_id) AND (t.deleted_at IS NULL))))
     LEFT JOIN LATERAL ( SELECT (count(*))::integer AS member_count
           FROM public.team_membership x
          WHERE ((x.team_id = t.team_id) AND (x.to_at IS NULL))) ts ON (true))
     LEFT JOIN public.team_membership tm ON (((tm.team_id = t.team_id) AND (tm.to_at IS NULL))))
     LEFT JOIN public.project_membership pm ON ((pm.project_membership_id = tm.project_membership_id)))
     LEFT JOIN public.app_user u ON ((u.user_id = pm.user_id)))
     LEFT JOIN LATERAL ( SELECT x.submission_id,
            x.org_id,
            x.team_id,
            x.assessment_round_id,
            x.method,
            x.repository_id,
            x.requested_branch,
            x.resolved_branch,
            x.source_commit_sha,
            x.source_commit_message,
            x.source_commit_committed_at,
            x.supersedes_submission_id,
            x.submitted_by,
            x.status,
            x.submitted_at,
            x.is_current,
            x.failure_reason,
            x.analysis_input_hash,
            x.git_history,
            x.analysis_input_file_count,
            x.analysis_input_captured_at,
            x.code_snippets,
            x.analysis_input_byte_count,
            x.repository_verification_id,
            x.request_idempotency_key
           FROM public.submission x
          WHERE ((x.team_id = t.team_id) AND (x.assessment_round_id = b.assessment_round_id))
          ORDER BY x.is_current DESC, x.submitted_at DESC
         LIMIT 1) sub ON (true))
     LEFT JOIN public.repository repo ON ((repo.repository_id = sub.repository_id)))
     LEFT JOIN public.app_user submitter ON ((submitter.user_id = sub.submitted_by)))
     LEFT JOIN LATERAL ( SELECT x.job_id,
            x.org_id,
            x.assessment_round_id,
            x.team_id,
            x.submission_id,
            x.analysis_id,
            x.question_focus_version_no,
            x.batch_key,
            x.job_type,
            x.execution_no,
            x.status,
            x.started_at,
            x.completed_at,
            x.failure_reason,
            x.trace_id,
            x.external_job_id,
            x.extraction_scope_id,
            x.requested_model_id,
            x.question_budget,
            x.request_payload,
            x.request_payload_hash,
            x.payload_schema_version,
            x.failure_code,
            x.created_at
           FROM public.analysis_job x
          WHERE ((x.team_id = t.team_id) AND (x.assessment_round_id = b.assessment_round_id))
          ORDER BY x.execution_no DESC, x.started_at DESC NULLS LAST
         LIMIT 1) aj ON (true))
     LEFT JOIN public.code_analysis ca ON ((ca.analysis_id = aj.analysis_id)))
     LEFT JOIN public.assessment_round_attendance att ON (((att.assessment_round_id = b.assessment_round_id) AND (att.class_id = b.class_id) AND (att.team_id = t.team_id) AND (att.user_id = pm.user_id))))
     LEFT JOIN public.measurement_attempt ma ON ((ma.attempt_id = att.primary_attempt_id)))
     LEFT JOIN LATERAL ( SELECT jsonb_agg(jsonb_build_object('problemId', ap.problem_id, 'problemNo', ap.problem_no, 'bestSuccessStage', ap.best_success_stage, 'generationStatus', ap.generation_status) ORDER BY ap.problem_no) AS levels
           FROM public.assessment_problem ap
          WHERE ((ap.measurement_attempt_id = att.primary_attempt_id) OR ((ap.code_analysis_id = ma.code_analysis_id) AND ((ap.problem_scope)::text = 'TEAM_SHARED_PROBLEM'::text)))) pr ON (true))
     LEFT JOIN LATERAL ( SELECT pra.assessment_id,
            pra.requirement_id,
            pra.assessment_round_id,
            pra.team_id,
            pra.org_id,
            pra.result,
            pra.evidence_summary,
            pra.evidence_locations,
            pra.source_submission_id,
            pra.analysis_id,
            pra.assessment_version,
            pra.supersedes_assessment_id,
            pra.assessed_at,
            pra.assessed_by,
            pra.created_at,
            pra.assessment_note
           FROM (public.project_requirement_assessment pra
             JOIN public.project_requirement rq ON ((rq.requirement_id = pra.requirement_id)))
          WHERE ((pra.assessment_round_id = b.assessment_round_id) AND (pra.team_id = t.team_id))
          ORDER BY rq.sequence_no, pra.assessed_at DESC
         LIMIT 1) req ON (true));


--
-- Name: manager_retried_trainee_heatmap_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.manager_retried_trainee_heatmap_view AS
 WITH problem_result AS (
         SELECT ma.org_id,
            ma.cohort_id,
            ma.project_id,
            ma.assessment_round_id,
            ma.user_id,
            ma.attempt_id,
            ma.attempt_type,
            ma.source_attempt_id,
            ma.attempt_sequence_no,
            ma.status AS attempt_status,
            ma.validity_review_status,
            ma.terminal_reason_code,
            pm.class_id,
            tm.team_id,
            ap.problem_id,
            ap.problem_no,
            max(
                CASE
                    WHEN ((ps.status)::text = 'PASSED'::text) THEN
                    CASE ps.axis_code
                        WHEN 'L4'::text THEN 4
                        WHEN 'L3'::text THEN 3
                        WHEN 'L2'::text THEN 2
                        WHEN 'L1'::text THEN 1
                        ELSE 0
                    END
                    ELSE 0
                END) AS highest_reached_level,
                CASE
                    WHEN ((ma.validity_review_status)::text = 'CONFIRMED_INVALID'::text) THEN 'INVALID'::text
                    WHEN ((ma.status)::text = 'COMPLETED'::text) THEN 'VALID'::text
                    WHEN ((ma.terminal_reason_code)::text = ANY ((ARRAY['NOT_ATTENDED'::character varying, 'NOT_SUBMITTED'::character varying])::text[])) THEN 'NOT_ATTENDED'::text
                    WHEN (((ma.status)::text = 'FAILED'::text) OR ((ma.terminal_reason_code)::text = 'SESSION_INCOMPLETE'::text)) THEN 'INTERRUPTED'::text
                    WHEN ((ma.status)::text = 'EXPIRED'::text) THEN 'NOT_ATTENDED'::text
                    ELSE 'PENDING'::text
                END AS result_status,
            (sum(((((ps.question_answer_text IS NOT NULL))::integer + ((ps.first_hint_answer_text IS NOT NULL))::integer) + ((ps.second_hint_answer_text IS NOT NULL))::integer)))::integer AS answer_attempt_count,
            jsonb_agg(jsonb_build_object('axisCode', ps.axis_code, 'status', ps.status, 'questionScore', ps.question_score, 'firstHintScore', ps.first_hint_score, 'secondHintScore', ps.second_hint_score) ORDER BY ps.question_sequence_no) AS score_summary
           FROM (((((public.measurement_attempt ma
             LEFT JOIN public.project_membership pm ON (((pm.project_id = ma.project_id) AND (pm.user_id = ma.user_id) AND (pm.joined_at <= COALESCE(ma.assessment_open_at, ma.assigned_at, CURRENT_TIMESTAMP)) AND ((pm.left_at IS NULL) OR (pm.left_at > COALESCE(ma.assessment_open_at, ma.assigned_at, CURRENT_TIMESTAMP))))))
             LEFT JOIN LATERAL ( SELECT x.team_id
                   FROM public.team_membership x
                  WHERE ((x.project_membership_id = pm.project_membership_id) AND (x.from_at <= COALESCE(ma.assessment_open_at, ma.assigned_at, CURRENT_TIMESTAMP)) AND ((x.to_at IS NULL) OR (x.to_at > COALESCE(ma.assessment_open_at, ma.assigned_at, CURRENT_TIMESTAMP))))
                  ORDER BY x.from_at DESC
                 LIMIT 1) tm ON (true))
             LEFT JOIN public.assessment_session s ON ((s.attempt_id = ma.attempt_id)))
             LEFT JOIN public.problem_stage ps ON ((ps.session_id = s.session_id)))
             LEFT JOIN public.assessment_problem ap ON ((ap.problem_id = ps.problem_id)))
          GROUP BY ma.org_id, ma.cohort_id, ma.project_id, ma.assessment_round_id, ma.user_id, ma.attempt_id, ma.attempt_type, ma.source_attempt_id, ma.attempt_sequence_no, ma.status, ma.validity_review_status, ma.terminal_reason_code, pm.class_id, tm.team_id, ap.problem_id, ap.problem_no
        )
 SELECT c.org_id,
    c.cohort_id,
    c.class_id,
    c.project_id,
    c.assessment_round_id,
    c.team_id,
    c.user_id,
    c.source_attempt_id AS initial_attempt_id,
    c.attempt_id AS comparison_attempt_id,
    c.attempt_type AS comparison_attempt_type,
    c.attempt_sequence_no,
    c.problem_id,
    c.problem_no,
    COALESCE(i.highest_reached_level, 0) AS initial_highest_reached_level,
    c.highest_reached_level AS comparison_highest_reached_level,
    (COALESCE(i.result_status, 'SOURCE_MISSING'::text))::character varying(100) AS initial_result_status,
    (c.result_status)::character varying(100) AS comparison_result_status,
    (c.highest_reached_level - COALESCE(i.highest_reached_level, 0)) AS comparison_delta,
    (
        CASE
            WHEN (i.attempt_id IS NULL) THEN 'PARTIAL_SOURCE_MISSING'::text
            ELSE 'COMPLETE'::text
        END)::character varying(20) AS aggregation_status,
    CURRENT_TIMESTAMP AS as_of_at,
    1 AS calculation_version
   FROM (problem_result c
     LEFT JOIN problem_result i ON (((i.attempt_id = c.source_attempt_id) AND (i.problem_no = c.problem_no))))
  WHERE ((c.attempt_type)::text = ANY ((ARRAY['RETRY'::character varying, 'REVIEW'::character varying])::text[]));


--
-- Name: manager_team_heatmap_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.manager_team_heatmap_view AS
 WITH problem_result AS (
         SELECT ma.org_id,
            ma.cohort_id,
            ma.project_id,
            ma.assessment_round_id,
            ma.user_id,
            ma.attempt_id,
            ma.attempt_type,
            ma.source_attempt_id,
            ma.attempt_sequence_no,
            ma.status AS attempt_status,
            ma.validity_review_status,
            ma.terminal_reason_code,
            pm.class_id,
            tm.team_id,
            ap.problem_id,
            ap.problem_no,
            max(
                CASE
                    WHEN ((ps.status)::text = 'PASSED'::text) THEN
                    CASE ps.axis_code
                        WHEN 'L4'::text THEN 4
                        WHEN 'L3'::text THEN 3
                        WHEN 'L2'::text THEN 2
                        WHEN 'L1'::text THEN 1
                        ELSE 0
                    END
                    ELSE 0
                END) AS highest_reached_level,
                CASE
                    WHEN ((ma.validity_review_status)::text = 'CONFIRMED_INVALID'::text) THEN 'INVALID'::text
                    WHEN ((ma.status)::text = 'COMPLETED'::text) THEN 'VALID'::text
                    WHEN ((ma.terminal_reason_code)::text = ANY ((ARRAY['NOT_ATTENDED'::character varying, 'NOT_SUBMITTED'::character varying])::text[])) THEN 'NOT_ATTENDED'::text
                    WHEN (((ma.status)::text = 'FAILED'::text) OR ((ma.terminal_reason_code)::text = 'SESSION_INCOMPLETE'::text)) THEN 'INTERRUPTED'::text
                    WHEN ((ma.status)::text = 'EXPIRED'::text) THEN 'NOT_ATTENDED'::text
                    ELSE 'PENDING'::text
                END AS result_status,
            (sum(((((ps.question_answer_text IS NOT NULL))::integer + ((ps.first_hint_answer_text IS NOT NULL))::integer) + ((ps.second_hint_answer_text IS NOT NULL))::integer)))::integer AS answer_attempt_count,
            jsonb_agg(jsonb_build_object('axisCode', ps.axis_code, 'status', ps.status, 'questionScore', ps.question_score, 'firstHintScore', ps.first_hint_score, 'secondHintScore', ps.second_hint_score) ORDER BY ps.question_sequence_no) AS score_summary
           FROM (((((public.measurement_attempt ma
             LEFT JOIN public.project_membership pm ON (((pm.project_id = ma.project_id) AND (pm.user_id = ma.user_id) AND (pm.joined_at <= COALESCE(ma.assessment_open_at, ma.assigned_at, CURRENT_TIMESTAMP)) AND ((pm.left_at IS NULL) OR (pm.left_at > COALESCE(ma.assessment_open_at, ma.assigned_at, CURRENT_TIMESTAMP))))))
             LEFT JOIN LATERAL ( SELECT x.team_id
                   FROM public.team_membership x
                  WHERE ((x.project_membership_id = pm.project_membership_id) AND (x.from_at <= COALESCE(ma.assessment_open_at, ma.assigned_at, CURRENT_TIMESTAMP)) AND ((x.to_at IS NULL) OR (x.to_at > COALESCE(ma.assessment_open_at, ma.assigned_at, CURRENT_TIMESTAMP))))
                  ORDER BY x.from_at DESC
                 LIMIT 1) tm ON (true))
             LEFT JOIN public.assessment_session s ON ((s.attempt_id = ma.attempt_id)))
             LEFT JOIN public.problem_stage ps ON ((ps.session_id = s.session_id)))
             LEFT JOIN public.assessment_problem ap ON ((ap.problem_id = ps.problem_id)))
          GROUP BY ma.org_id, ma.cohort_id, ma.project_id, ma.assessment_round_id, ma.user_id, ma.attempt_id, ma.attempt_type, ma.source_attempt_id, ma.attempt_sequence_no, ma.status, ma.validity_review_status, ma.terminal_reason_code, pm.class_id, tm.team_id, ap.problem_id, ap.problem_no
        )
 SELECT org_id,
    cohort_id,
    class_id,
    project_id,
    assessment_round_id,
    team_id,
    problem_no,
    (avg(highest_reached_level) FILTER (WHERE (result_status = 'VALID'::text)))::numeric(10,4) AS average_highest_reached_level,
    (count(*) FILTER (WHERE (result_status = 'VALID'::text)))::integer AS valid_result_count,
    (count(*) FILTER (WHERE (result_status = 'NOT_ATTENDED'::text)))::integer AS not_attended_count,
    (count(*) FILTER (WHERE (result_status = 'INVALID'::text)))::integer AS invalid_attempt_count,
    (count(*) FILTER (WHERE (result_status = 'INTERRUPTED'::text)))::integer AS interrupted_count,
    (
        CASE
            WHEN (count(*) = 0) THEN 'EMPTY'::text
            WHEN (count(*) FILTER (WHERE (result_status = 'VALID'::text)) = 0) THEN 'NO_VALID_RESULT'::text
            ELSE 'COMPLETE'::text
        END)::character varying(20) AS aggregation_status,
    CURRENT_TIMESTAMP AS as_of_at,
    1 AS calculation_version
   FROM problem_result pr
  WHERE ((attempt_type)::text = 'INITIAL'::text)
  GROUP BY org_id, cohort_id, class_id, project_id, assessment_round_id, team_id, problem_no;


--
-- Name: manager_trainee_detail_timeline_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.manager_trainee_detail_timeline_view AS
 WITH manager_scope AS (
         SELECT ma.org_id,
            ma.manager_user_id,
            c.cohort_id,
            ma.class_id
           FROM (public.manager_assignment ma
             JOIN public.class c ON ((c.class_id = ma.class_id)))
          WHERE (((ma.status)::text = 'ACTIVE'::text) AND (ma.unassigned_at IS NULL))
        ), attempt_scope AS (
         SELECT ms.org_id,
            ms.manager_user_id,
            ms.cohort_id,
            ma.user_id AS target_user_id,
            ma.attempt_id,
            ma.attempt_type,
            ma.source_attempt_id,
            ma.code_analysis_id,
            ma.status,
            ma.terminal_reason_code,
            ma.terminal_at,
            ma.updated_at,
            ma.assessment_open_at,
            ma.assessment_close_at,
            ma.review_due_at,
            ma.attempt_sequence_no,
            ma.project_id,
            ma.assessment_round_id,
            r.round_name,
            p.name AS project_name,
            p.sequence_no AS analysis_sequence_no,
            tm.team_id,
            t.name AS team_name,
            s.session_id
           FROM (((((((manager_scope ms
             JOIN public.project_membership pm ON (((pm.class_id = ms.class_id) AND ((pm.status)::text = 'ACTIVE'::text))))
             JOIN public.measurement_attempt ma ON (((ma.user_id = pm.user_id) AND (ma.project_id = pm.project_id))))
             JOIN public.project_assessment_round r ON ((r.assessment_round_id = ma.assessment_round_id)))
             JOIN public.project p ON ((p.project_id = r.project_id)))
             LEFT JOIN LATERAL ( SELECT x.team_id
                   FROM public.team_membership x
                  WHERE ((x.project_membership_id = pm.project_membership_id) AND (x.from_at <= COALESCE(ma.assessment_open_at, CURRENT_TIMESTAMP)) AND ((x.to_at IS NULL) OR (x.to_at > COALESCE(ma.assessment_open_at, CURRENT_TIMESTAMP))))
                  ORDER BY x.from_at DESC
                 LIMIT 1) tm ON (true))
             LEFT JOIN public.team t ON ((t.team_id = tm.team_id)))
             LEFT JOIN public.assessment_session s ON ((s.attempt_id = ma.attempt_id)))
        ), round_context AS (
         SELECT attempt_scope.manager_user_id,
            attempt_scope.cohort_id,
            attempt_scope.target_user_id,
            attempt_scope.assessment_round_id,
            (max((attempt_scope.project_id)::text))::uuid AS project_id,
            max(attempt_scope.analysis_sequence_no) AS analysis_sequence_no,
            max((attempt_scope.round_name)::text) AS round_name,
            max((attempt_scope.project_name)::text) AS project_name,
            (max((attempt_scope.team_id)::text) FILTER (WHERE ((attempt_scope.attempt_type)::text = 'INITIAL'::text)))::uuid AS team_id,
            max((attempt_scope.team_name)::text) FILTER (WHERE ((attempt_scope.attempt_type)::text = 'INITIAL'::text)) AS team_name,
            min(attempt_scope.assessment_open_at) FILTER (WHERE ((attempt_scope.attempt_type)::text = 'INITIAL'::text)) AS activity_start_at,
            max(COALESCE(attempt_scope.terminal_at, attempt_scope.assessment_close_at)) FILTER (WHERE ((attempt_scope.attempt_type)::text = 'INITIAL'::text)) AS activity_end_at
           FROM attempt_scope
          GROUP BY attempt_scope.manager_user_id, attempt_scope.cohort_id, attempt_scope.target_user_id, attempt_scope.assessment_round_id
        ), problem_result AS (
         SELECT a.attempt_id,
            ap.problem_id,
            ap.problem_no,
            ap.project_verification_concept_id AS concept_id,
            COALESCE(tc.canonical_name, (ap.title)::character varying) AS concept_name,
            ap.generation_status,
            COALESCE(st.answered_axis_count, 0) AS answered_axis_count,
            st.reach_level,
            st.hint_used_count
           FROM ((((attempt_scope a
             JOIN public.assessment_problem ap ON (((ap.measurement_attempt_id = a.attempt_id) OR ((ap.code_analysis_id = a.code_analysis_id) AND ((ap.problem_scope)::text = 'TEAM_SHARED_PROBLEM'::text)))))
             LEFT JOIN public.project_verification_concept pvc ON ((pvc.project_concept_id = ap.project_verification_concept_id)))
             LEFT JOIN public.teaches tc ON ((tc.teaches_id = pvc.teaches_id)))
             LEFT JOIN LATERAL ( SELECT (count(*) FILTER (WHERE ((ps.status)::text = ANY ((ARRAY['PASSED'::character varying, 'NOT_PASSED'::character varying])::text[]))))::integer AS answered_axis_count,
                    COALESCE(max((SUBSTRING(ps.axis_code FROM 2))::integer) FILTER (WHERE ((ps.status)::text = 'PASSED'::text)), 0) AS reach_level,
                    (array_agg((((ps.first_hint_answered_at IS NOT NULL))::integer + ((ps.second_hint_answered_at IS NOT NULL))::integer) ORDER BY ((ps.status)::text = 'PASSED'::text) DESC, (SUBSTRING(ps.axis_code FROM 2))::integer DESC) FILTER (WHERE ((ps.status)::text = ANY ((ARRAY['PASSED'::character varying, 'NOT_PASSED'::character varying])::text[]))))[1] AS hint_used_count
                   FROM public.problem_stage ps
                  WHERE ((ps.session_id = a.session_id) AND (ps.problem_id = ap.problem_id))) st ON (true))
        ), review_target AS (
         SELECT a.manager_user_id,
            a.cohort_id,
            a.target_user_id,
            a.assessment_round_id,
            (count(*) FILTER (WHERE (((pr.generation_status)::text = 'GENERATED'::text) AND (pr.answered_axis_count > 0) AND (pr.reach_level <= 1))))::integer AS target_count
           FROM (attempt_scope a
             JOIN problem_result pr ON ((pr.attempt_id = a.attempt_id)))
          WHERE ((a.attempt_type)::text = 'INITIAL'::text)
          GROUP BY a.manager_user_id, a.cohort_id, a.target_user_id, a.assessment_round_id
        ), review_problem AS (
         SELECT a.org_id,
            a.manager_user_id,
            a.cohort_id,
            a.target_user_id,
            a.attempt_id,
            a.attempt_type,
            a.source_attempt_id,
            a.code_analysis_id,
            a.status,
            a.terminal_reason_code,
            a.terminal_at,
            a.updated_at,
            a.assessment_open_at,
            a.assessment_close_at,
            a.review_due_at,
            a.attempt_sequence_no,
            a.project_id,
            a.assessment_round_id,
            a.round_name,
            a.project_name,
            a.analysis_sequence_no,
            a.team_id,
            a.team_name,
            a.session_id,
            pr.problem_id,
            pr.problem_no,
            pr.concept_id,
            pr.concept_name,
            pr.generation_status,
            pr.answered_axis_count,
            pr.reach_level AS to_level,
            src.reach_level AS from_level
           FROM ((attempt_scope a
             JOIN problem_result pr ON ((pr.attempt_id = a.attempt_id)))
             LEFT JOIN problem_result src ON (((src.attempt_id = a.source_attempt_id) AND (src.problem_id = pr.problem_id))))
          WHERE ((a.attempt_type)::text = 'REVIEW'::text)
        ), assessment_events AS (
         SELECT a.org_id,
            a.manager_user_id,
            a.cohort_id,
            a.target_user_id,
            a.assessment_round_id,
            a.attempt_id AS event_id,
            'ASSESSMENT'::text AS event_type,
            10 AS event_type_order,
            COALESCE(a.terminal_at, a.updated_at) AS occurred_at,
            'MEASUREMENT_ATTEMPT'::text AS source_entity_type,
            a.attempt_id AS source_entity_id,
            (a.status)::text AS source_status,
            a.session_id,
            (a.session_id IS NOT NULL) AS is_expandable,
            'OPEN_ASSESSMENT'::text AS detail_action_code,
            jsonb_build_object('attemptSequenceNo', a.attempt_sequence_no, 'problems', COALESCE(pp.problems, '[]'::jsonb)) AS payload,
            'COMPLETE'::text AS row_aggregation_status
           FROM (attempt_scope a
             LEFT JOIN LATERAL ( SELECT jsonb_agg(jsonb_build_object('problemNo', pr.problem_no, 'problemId', pr.problem_id, 'conceptId', pr.concept_id, 'conceptName', pr.concept_name, 'generationStatus', pr.generation_status, 'reachLevel',
                        CASE
                            WHEN (((pr.generation_status)::text = 'GENERATED'::text) AND (pr.answered_axis_count > 0)) THEN pr.reach_level
                            ELSE NULL::integer
                        END, 'hintUsedCount',
                        CASE
                            WHEN (((pr.generation_status)::text = 'GENERATED'::text) AND (pr.answered_axis_count > 0)) THEN COALESCE(pr.hint_used_count, 0)
                            ELSE NULL::integer
                        END) ORDER BY pr.problem_no) AS problems
                   FROM problem_result pr
                  WHERE (pr.attempt_id = a.attempt_id)) pp ON (true))
          WHERE ((a.attempt_type)::text = ANY ((ARRAY['INITIAL'::character varying, 'RETRY'::character varying])::text[]))
        ), report_events AS (
         SELECT ms.org_id,
            ms.manager_user_id,
            ms.cohort_id,
            rpt.user_id AS target_user_id,
            rpt.assessment_round_id,
            rpt.report_id AS event_id,
            'REPORT'::text AS event_type,
            20 AS event_type_order,
            COALESCE(rpt.published_at, rs.as_of_at) AS occurred_at,
            'REPORT'::text AS source_entity_type,
            rpt.report_id AS source_entity_id,
            (rpt.lifecycle_status)::text AS source_status,
            NULL::uuid AS session_id,
            true AS is_expandable,
            'OPEN_REPORT'::text AS detail_action_code,
            jsonb_build_object('reviewTargetCount', COALESCE(rt.target_count, 0), 'summary', (rs.summary_payload ->> 'summary'::text)) AS payload,
            (rs.completion_status)::text AS row_aggregation_status
           FROM ((((((manager_scope ms
             JOIN public.project_membership pm ON (((pm.class_id = ms.class_id) AND ((pm.status)::text = 'ACTIVE'::text))))
             JOIN public.report rpt ON ((rpt.user_id = pm.user_id)))
             JOIN public.report_snapshot rs ON (((rs.report_id = rpt.report_id) AND rs.is_active)))
             JOIN public.project_assessment_round ar ON ((ar.assessment_round_id = rpt.assessment_round_id)))
             JOIN public.project p ON (((p.project_id = ar.project_id) AND (p.project_id = pm.project_id))))
             LEFT JOIN review_target rt ON (((rt.manager_user_id = ms.manager_user_id) AND (rt.cohort_id = ms.cohort_id) AND (rt.target_user_id = rpt.user_id) AND (rt.assessment_round_id = rpt.assessment_round_id))))
        ), review_events AS (
         SELECT rp.org_id,
            rp.manager_user_id,
            rp.cohort_id,
            rp.target_user_id,
            rp.assessment_round_id,
            rp.attempt_id AS event_id,
            'REVIEW'::text AS event_type,
            30 AS event_type_order,
            COALESCE(rp.terminal_at, rp.updated_at) AS occurred_at,
            'MEASUREMENT_ATTEMPT'::text AS source_entity_type,
            rp.attempt_id AS source_entity_id,
            (rp.status)::text AS source_status,
            (max((rp.session_id)::text))::uuid AS session_id,
            (max((rp.session_id)::text) IS NOT NULL) AS is_expandable,
            'OPEN_ASSESSMENT'::text AS detail_action_code,
            jsonb_build_object('dueAt', max(rp.review_due_at), 'changes', jsonb_agg(jsonb_build_object('problemNo', rp.problem_no, 'problemId', rp.problem_id, 'conceptId', rp.concept_id, 'conceptName', rp.concept_name, 'fromReachLevel', rp.from_level, 'toReachLevel', rp.to_level, 'improved', (COALESCE(rp.to_level, '-1'::integer) > COALESCE(rp.from_level, '-1'::integer))) ORDER BY rp.problem_no)) AS payload,
            'COMPLETE'::text AS row_aggregation_status
           FROM review_problem rp
          WHERE (rp.answered_axis_count > 0)
          GROUP BY rp.org_id, rp.manager_user_id, rp.cohort_id, rp.target_user_id, rp.assessment_round_id, rp.attempt_id, rp.terminal_at, rp.updated_at, rp.status
        ), review_closed_events AS (
         SELECT rp.org_id,
            rp.manager_user_id,
            rp.cohort_id,
            rp.target_user_id,
            rp.assessment_round_id,
            rp.attempt_id AS event_id,
            'REVIEW_CLOSED'::text AS event_type,
            40 AS event_type_order,
            max(COALESCE(rp.review_due_at, rp.terminal_at, rp.updated_at)) AS occurred_at,
            'MEASUREMENT_ATTEMPT'::text AS source_entity_type,
            rp.attempt_id AS source_entity_id,
            (rp.status)::text AS source_status,
            NULL::uuid AS session_id,
            false AS is_expandable,
            NULL::text AS detail_action_code,
            jsonb_build_object('dueAt', max(rp.review_due_at), 'missedCount', count(*), 'missed', jsonb_agg(jsonb_build_object('problemNo', rp.problem_no, 'problemId', rp.problem_id, 'conceptId', rp.concept_id, 'conceptName', rp.concept_name) ORDER BY rp.problem_no)) AS payload,
            'COMPLETE'::text AS row_aggregation_status
           FROM review_problem rp
          WHERE ((rp.answered_axis_count = 0) AND ((rp.generation_status)::text = 'GENERATED'::text) AND ((rp.review_due_at <= CURRENT_TIMESTAMP) OR ((rp.status)::text = ANY ((ARRAY['EXPIRED'::character varying, 'FAILED'::character varying])::text[])) OR ((rp.terminal_reason_code)::text = ANY ((ARRAY['NOT_ATTENDED'::character varying, 'REVIEW_NOT_COMPLETED'::character varying])::text[]))))
          GROUP BY rp.org_id, rp.manager_user_id, rp.cohort_id, rp.target_user_id, rp.assessment_round_id, rp.attempt_id, rp.terminal_at, rp.updated_at, rp.status
        ), interview_events AS (
         SELECT ms.org_id,
            ms.manager_user_id,
            ms.cohort_id,
            i.target_user_id,
            i.assessment_round_id,
            i.interview_id AS event_id,
            'INTERVIEW'::text AS event_type,
            50 AS event_type_order,
            COALESCE(i.completed_at, i.started_at, i.created_at) AS occurred_at,
            'INTERVIEW'::text AS source_entity_type,
            i.interview_id AS source_entity_id,
            (i.status)::text AS source_status,
            NULL::uuid AS session_id,
            true AS is_expandable,
            'OPEN_INTERVIEW'::text AS detail_action_code,
            jsonb_build_object('recordStatus', i.status, 'identifiedCause', i.result_summary, 'managerNote', ib.manager_note, 'nextAction', act.next_action, 'nextActionConfirmedAt', ( SELECT min(COALESCE(nx.started_at, nx.created_at)) AS min
                   FROM public.interview nx
                  WHERE ((nx.target_user_id = i.target_user_id) AND (nx.class_id = i.class_id) AND (COALESCE(nx.started_at, nx.created_at) > COALESCE(i.completed_at, i.started_at, i.created_at)))), 'managerActions', COALESCE(bi.items, '[]'::jsonb)) AS payload,
                CASE
                    WHEN (ib.brief_id IS NULL) THEN 'PARTIAL'::text
                    ELSE 'COMPLETE'::text
                END AS row_aggregation_status
           FROM ((((manager_scope ms
             JOIN public.interview i ON ((i.class_id = ms.class_id)))
             LEFT JOIN LATERAL ( SELECT x.brief_id,
                    x.interview_id,
                    x.org_id,
                    x.cohort_id,
                    x.user_id,
                    x.assessment_round_id,
                    x.brief_type,
                    x.version_no,
                    x.is_first_interview,
                    x.brief_generation_policy_version,
                    x.status,
                    x.manager_note,
                    x.opening_remark_text,
                    x.opening_remark_generated_at,
                    x.created_by,
                    x.created_at,
                    x.updated_by,
                    x.updated_at,
                    x.confirmed_by,
                    x.confirmed_at,
                    x.row_version,
                    x.last_request_id,
                    x.last_request_fingerprint
                   FROM public.interview_brief x
                  WHERE (x.interview_id = i.interview_id)
                  ORDER BY x.version_no DESC
                 LIMIT 1) ib ON (true))
             LEFT JOIN LATERAL ( SELECT jsonb_agg(jsonb_build_object('displayOrder', bii.display_order, 'question', bii.question_text, 'rationale', bii.question_rationale) ORDER BY bii.display_order) AS items
                   FROM public.interview_brief_item bii
                  WHERE ((bii.brief_id = ib.brief_id) AND bii.is_selected)) bi ON (true))
             LEFT JOIN LATERAL ( SELECT ia.next_action
                   FROM public.interview_activity ia
                  WHERE (ia.interview_id = i.interview_id)
                  ORDER BY ia.occurred_at DESC
                 LIMIT 1) act ON (true))
        ), z AS (
         SELECT assessment_events.org_id,
            assessment_events.manager_user_id,
            assessment_events.cohort_id,
            assessment_events.target_user_id,
            assessment_events.assessment_round_id,
            assessment_events.event_id,
            assessment_events.event_type,
            assessment_events.event_type_order,
            assessment_events.occurred_at,
            assessment_events.source_entity_type,
            assessment_events.source_entity_id,
            assessment_events.source_status,
            assessment_events.session_id,
            assessment_events.is_expandable,
            assessment_events.detail_action_code,
            assessment_events.payload,
            assessment_events.row_aggregation_status
           FROM assessment_events
        UNION ALL
         SELECT report_events.org_id,
            report_events.manager_user_id,
            report_events.cohort_id,
            report_events.target_user_id,
            report_events.assessment_round_id,
            report_events.event_id,
            report_events.event_type,
            report_events.event_type_order,
            report_events.occurred_at,
            report_events.source_entity_type,
            report_events.source_entity_id,
            report_events.source_status,
            report_events.session_id,
            report_events.is_expandable,
            report_events.detail_action_code,
            report_events.payload,
            report_events.row_aggregation_status
           FROM report_events
        UNION ALL
         SELECT review_events.org_id,
            review_events.manager_user_id,
            review_events.cohort_id,
            review_events.target_user_id,
            review_events.assessment_round_id,
            review_events.event_id,
            review_events.event_type,
            review_events.event_type_order,
            review_events.occurred_at,
            review_events.source_entity_type,
            review_events.source_entity_id,
            review_events.source_status,
            review_events.session_id,
            review_events.is_expandable,
            review_events.detail_action_code,
            review_events.payload,
            review_events.row_aggregation_status
           FROM review_events
        UNION ALL
         SELECT review_closed_events.org_id,
            review_closed_events.manager_user_id,
            review_closed_events.cohort_id,
            review_closed_events.target_user_id,
            review_closed_events.assessment_round_id,
            review_closed_events.event_id,
            review_closed_events.event_type,
            review_closed_events.event_type_order,
            review_closed_events.occurred_at,
            review_closed_events.source_entity_type,
            review_closed_events.source_entity_id,
            review_closed_events.source_status,
            review_closed_events.session_id,
            review_closed_events.is_expandable,
            review_closed_events.detail_action_code,
            review_closed_events.payload,
            review_closed_events.row_aggregation_status
           FROM review_closed_events
        UNION ALL
         SELECT interview_events.org_id,
            interview_events.manager_user_id,
            interview_events.cohort_id,
            interview_events.target_user_id,
            interview_events.assessment_round_id,
            interview_events.event_id,
            interview_events.event_type,
            interview_events.event_type_order,
            interview_events.occurred_at,
            interview_events.source_entity_type,
            interview_events.source_entity_id,
            interview_events.source_status,
            interview_events.session_id,
            interview_events.is_expandable,
            interview_events.detail_action_code,
            interview_events.payload,
            interview_events.row_aggregation_status
           FROM interview_events
        )
 SELECT z.org_id,
    z.manager_user_id,
    z.cohort_id,
    z.target_user_id,
    rc.project_id,
    z.assessment_round_id,
    rc.analysis_sequence_no,
    rc.round_name,
    rc.project_name,
    rc.team_id AS team_id_at_round,
    rc.team_name AS team_name_at_round,
    rc.activity_start_at AS round_activity_start_at,
    rc.activity_end_at AS round_activity_end_at,
    rc.analysis_sequence_no AS round_sort_at,
    z.event_id,
    (z.event_type)::character varying(100) AS event_type,
    z.event_type_order,
    z.occurred_at,
    (z.source_entity_type)::character varying(100) AS source_entity_type,
    z.source_entity_id,
    (z.source_status)::character varying(100) AS source_status,
    z.session_id,
    z.is_expandable,
    (z.detail_action_code)::character varying(100) AS detail_action_code,
    z.payload,
    (z.row_aggregation_status)::character varying(100) AS row_aggregation_status,
    false AS is_stale,
    CURRENT_TIMESTAMP AS as_of_at,
    2 AS calculation_version
   FROM (z
     JOIN round_context rc ON (((rc.manager_user_id = z.manager_user_id) AND (rc.cohort_id = z.cohort_id) AND (rc.target_user_id = z.target_user_id) AND (rc.assessment_round_id = z.assessment_round_id))));


--
-- Name: manager_trainee_heatmap_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.manager_trainee_heatmap_view AS
 WITH problem_result AS (
         SELECT ma.org_id,
            ma.cohort_id,
            ma.project_id,
            ma.assessment_round_id,
            ma.user_id,
            ma.attempt_id,
            ma.attempt_type,
            ma.source_attempt_id,
            ma.attempt_sequence_no,
            ma.status AS attempt_status,
            ma.validity_review_status,
            ma.terminal_reason_code,
            pm.class_id,
            tm.team_id,
            ap.problem_id,
            ap.problem_no,
            max(
                CASE
                    WHEN ((ps.status)::text = 'PASSED'::text) THEN
                    CASE ps.axis_code
                        WHEN 'L4'::text THEN 4
                        WHEN 'L3'::text THEN 3
                        WHEN 'L2'::text THEN 2
                        WHEN 'L1'::text THEN 1
                        ELSE 0
                    END
                    ELSE 0
                END) AS highest_reached_level,
                CASE
                    WHEN ((ma.validity_review_status)::text = 'CONFIRMED_INVALID'::text) THEN 'INVALID'::text
                    WHEN ((ma.status)::text = 'COMPLETED'::text) THEN 'VALID'::text
                    WHEN ((ma.terminal_reason_code)::text = ANY ((ARRAY['NOT_ATTENDED'::character varying, 'NOT_SUBMITTED'::character varying])::text[])) THEN 'NOT_ATTENDED'::text
                    WHEN (((ma.status)::text = 'FAILED'::text) OR ((ma.terminal_reason_code)::text = 'SESSION_INCOMPLETE'::text)) THEN 'INTERRUPTED'::text
                    WHEN ((ma.status)::text = 'EXPIRED'::text) THEN 'NOT_ATTENDED'::text
                    ELSE 'PENDING'::text
                END AS result_status,
            (sum(((((ps.question_answer_text IS NOT NULL))::integer + ((ps.first_hint_answer_text IS NOT NULL))::integer) + ((ps.second_hint_answer_text IS NOT NULL))::integer)))::integer AS answer_attempt_count,
            jsonb_agg(jsonb_build_object('axisCode', ps.axis_code, 'status', ps.status, 'questionScore', ps.question_score, 'firstHintScore', ps.first_hint_score, 'secondHintScore', ps.second_hint_score) ORDER BY ps.question_sequence_no) AS score_summary
           FROM (((((public.measurement_attempt ma
             LEFT JOIN public.project_membership pm ON (((pm.project_id = ma.project_id) AND (pm.user_id = ma.user_id) AND (pm.joined_at <= COALESCE(ma.assessment_open_at, ma.assigned_at, CURRENT_TIMESTAMP)) AND ((pm.left_at IS NULL) OR (pm.left_at > COALESCE(ma.assessment_open_at, ma.assigned_at, CURRENT_TIMESTAMP))))))
             LEFT JOIN LATERAL ( SELECT x.team_id
                   FROM public.team_membership x
                  WHERE ((x.project_membership_id = pm.project_membership_id) AND (x.from_at <= COALESCE(ma.assessment_open_at, ma.assigned_at, CURRENT_TIMESTAMP)) AND ((x.to_at IS NULL) OR (x.to_at > COALESCE(ma.assessment_open_at, ma.assigned_at, CURRENT_TIMESTAMP))))
                  ORDER BY x.from_at DESC
                 LIMIT 1) tm ON (true))
             LEFT JOIN public.assessment_session s ON ((s.attempt_id = ma.attempt_id)))
             LEFT JOIN public.problem_stage ps ON ((ps.session_id = s.session_id)))
             LEFT JOIN public.assessment_problem ap ON ((ap.problem_id = ps.problem_id)))
          GROUP BY ma.org_id, ma.cohort_id, ma.project_id, ma.assessment_round_id, ma.user_id, ma.attempt_id, ma.attempt_type, ma.source_attempt_id, ma.attempt_sequence_no, ma.status, ma.validity_review_status, ma.terminal_reason_code, pm.class_id, tm.team_id, ap.problem_id, ap.problem_no
        )
 SELECT org_id,
    cohort_id,
    class_id,
    project_id,
    assessment_round_id,
    team_id,
    user_id,
    problem_id,
    problem_no,
    highest_reached_level,
    (result_status)::character varying(100) AS problem_result_status,
    answer_attempt_count,
    (score_summary)::text AS score_summary,
    (
        CASE
            WHEN (problem_id IS NULL) THEN 'PARTIAL'::text
            ELSE 'COMPLETE'::text
        END)::character varying(20) AS aggregation_status,
    CURRENT_TIMESTAMP AS as_of_at,
    1 AS calculation_version
   FROM problem_result pr
  WHERE ((attempt_type)::text = 'INITIAL'::text);


--
-- Name: participant_contribution_snapshot; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.participant_contribution_snapshot (
    contribution_snapshot_id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    project_id uuid NOT NULL,
    assessment_round_id uuid NOT NULL,
    repository_id uuid NOT NULL,
    team_id uuid NOT NULL,
    user_id uuid NOT NULL,
    analysis_job_id uuid NOT NULL,
    code_analysis_id uuid NOT NULL,
    commit_range_strategy text NOT NULL,
    base_commit_sha character varying(64) NOT NULL,
    head_commit_sha character varying(64) NOT NULL,
    contribution_period_started_at timestamp with time zone NOT NULL,
    contribution_period_ended_at timestamp with time zone NOT NULL,
    commit_count integer NOT NULL,
    changed_file_count integer NOT NULL,
    addition_count integer NOT NULL,
    deletion_count integer NOT NULL,
    changed_line_count integer NOT NULL,
    contribution_value numeric(18,6),
    contribution_ratio numeric(10,4),
    attribution_coverage_rate numeric(18,6),
    calculation_policy_version integer NOT NULL,
    status character varying(30) NOT NULL,
    failure_code character varying(100),
    calculated_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT ck_participant_contribution_snapshot_addition_count CHECK ((addition_count >= 0)),
    CONSTRAINT ck_participant_contribution_snapshot_attribution_coverage_rate CHECK (((attribution_coverage_rate IS NULL) OR ((attribution_coverage_rate >= (0)::numeric) AND (attribution_coverage_rate <= (1)::numeric)))),
    CONSTRAINT ck_participant_contribution_snapshot_changed_file_count CHECK ((changed_file_count >= 0)),
    CONSTRAINT ck_participant_contribution_snapshot_changed_line_count CHECK ((changed_line_count >= 0)),
    CONSTRAINT ck_participant_contribution_snapshot_commit_count CHECK ((commit_count >= 0)),
    CONSTRAINT ck_participant_contribution_snapshot_commit_range_strategy CHECK ((commit_range_strategy = ANY (ARRAY['CUMULATIVE_FROM_PROJECT_START'::text, 'INCREMENTAL_FROM_PREVIOUS_ROUND'::text]))),
    CONSTRAINT ck_participant_contribution_snapshot_contribution_period_ended_ CHECK ((contribution_period_ended_at > contribution_period_started_at)),
    CONSTRAINT ck_participant_contribution_snapshot_contribution_ratio CHECK (((contribution_ratio IS NULL) OR ((contribution_ratio >= (0)::numeric) AND (contribution_ratio <= (1)::numeric)))),
    CONSTRAINT ck_participant_contribution_snapshot_contribution_value CHECK (((contribution_value IS NULL) OR (contribution_value >= (0)::numeric))),
    CONSTRAINT ck_participant_contribution_snapshot_deletion_count CHECK ((deletion_count >= 0)),
    CONSTRAINT ck_participant_contribution_snapshot_status CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'AVAILABLE'::character varying, 'INSUFFICIENT_ATTRIBUTION'::character varying, 'FAILED'::character varying])::text[]))),
    CONSTRAINT ck_participant_contribution_snapshot_status_2 CHECK (((((status)::text = 'PENDING'::text) AND (contribution_value IS NULL) AND (contribution_ratio IS NULL) AND (attribution_coverage_rate IS NULL) AND (calculated_at IS NULL) AND (failure_code IS NULL)) OR (((status)::text = 'AVAILABLE'::text) AND (contribution_value IS NOT NULL) AND (contribution_ratio IS NOT NULL) AND (attribution_coverage_rate IS NOT NULL) AND (calculated_at IS NOT NULL) AND (failure_code IS NULL)) OR (((status)::text = ANY ((ARRAY['INSUFFICIENT_ATTRIBUTION'::character varying, 'FAILED'::character varying])::text[])) AND (failure_code IS NOT NULL))))
);


--
-- Name: TABLE participant_contribution_snapshot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.participant_contribution_snapshot IS '빅프로젝트 회차에서 교육생별 GitHub 귀속 커밋 범위와 기여도 계산 결과를 실행별로 불변 보존하는 APPEND-ONLY 스냅샷입니다. | 정의서명: ParticipantContributionSnapshot | 제약·비고: • 상태: PENDING / AVAILABLE / INSUFFICIENT_ATTRIBUTION / FAILED • UNIQUE(analysis_job_id, assessment_round_id, user_id) • commit_range_strategy: CUMULATIVE_FROM_PROJECT_START / INCREMENTAL_FROM_PREVIOUS_ROUND • contribution_period_ended_at > contribution_period_started_at • 집계 수치는 0 이상이고 contribution_value는 NULL 또는 0 이상입니다. • contribution_ratio·attribution_coverage_rate는 NULL 또는 0~1입니다. • AVAILABLE이면 contribution_value·contribution_ratio·attribution_coverage_rate·calculated_at이 필수이고 failure_code는 NULL입니다. • INSUFFICIENT_ATTRIBUTION·FAILED이면 failure_code가 필수입니다. • 기관·프로젝트·회차·저장소·팀·사용자·작업·코드 분석 경로가 일치해야 합니다. • 재분석은 기존 행을 갱신하지 않고 새 analysis_job_id와 새 스냅샷을 생성합니다. • 기여도와 이해도를 하나의 합산 점수로 저장하지 않습니다.';


