--
-- Name: manager_trainee_risk_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.manager_trainee_risk_view AS
 SELECT ma.user_id,
    ma.assessment_round_id,
    (COALESCE(pcs.status, 'UNAVAILABLE'::character varying))::character varying(100) AS contribution_status,
    (
        CASE
            WHEN ((ma.validity_review_status)::text = 'CONFIRMED_INVALID'::text) THEN 'INVALID'::text
            WHEN ((ma.status)::text = 'COMPLETED'::text) THEN 'AVAILABLE'::text
            WHEN ((ma.status)::text = ANY ((ARRAY['FAILED'::character varying, 'EXPIRED'::character varying])::text[])) THEN 'UNAVAILABLE'::text
            ELSE 'PENDING'::text
        END)::character varying(100) AS comprehension_status,
    (
        CASE
            WHEN ((ma.validity_review_status)::text = 'CONFIRMED_INVALID'::text) THEN 'INVALID_ATTEMPT'::text
            ELSE NULL::text
        END)::character varying(100) AS risk_type_code,
    ((ma.validity_review_status)::text = 'CONFIRMED_INVALID'::text) AS is_applicable,
    COALESCE(pcs.calculation_policy_version, 1) AS policy_version,
    COALESCE(pcs.calculated_at, ma.updated_at) AS calculated_at,
    (jsonb_build_object('attemptId', ma.attempt_id, 'attemptStatus', ma.status, 'validityReviewStatus', ma.validity_review_status, 'contributionSnapshotId', pcs.contribution_snapshot_id, 'contributionStatus', pcs.status))::text AS source_trace
   FROM (public.measurement_attempt ma
     LEFT JOIN public.participant_contribution_snapshot pcs ON (((pcs.assessment_round_id = ma.assessment_round_id) AND (pcs.user_id = ma.user_id))))
  WHERE ((ma.attempt_type)::text = 'INITIAL'::text);


--
-- Name: user_invitation; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_invitation (
    invitation_id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid,
    target_email public.citext NOT NULL,
    target_email_normalized character varying(320) NOT NULL,
    target_role_code character varying(30) NOT NULL,
    target_cohort_id uuid,
    target_class_id uuid,
    status character varying(30) DEFAULT 'PENDING'::character varying NOT NULL,
    invited_by uuid NOT NULL,
    invited_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    sent_at timestamp with time zone,
    accepted_at timestamp with time zone,
    expired_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    cancelled_by uuid,
    failure_stage character varying(30),
    failure_code character varying(100),
    failure_reason text,
    failed_at timestamp with time zone,
    current_token_id uuid,
    accepted_user_id uuid,
    resend_count integer DEFAULT 0 NOT NULL,
    last_resend_at timestamp with time zone,
    create_idempotency_key uuid,
    create_request_fingerprint character(64),
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    batch_request_id text,
    mail_claimed_at timestamp with time zone,
    CONSTRAINT ck_user_invitation_create_idempotency_key CHECK ((((create_idempotency_key IS NULL) AND (create_request_fingerprint IS NULL)) OR ((create_idempotency_key IS NOT NULL) AND (create_request_fingerprint IS NOT NULL)))),
    CONSTRAINT ck_user_invitation_create_request_fingerprint CHECK (((create_request_fingerprint IS NULL) OR (create_request_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT ck_user_invitation_failure_code CHECK (((failure_code)::text = ANY ((ARRAY['INVITE_TOKEN_FAILED'::character varying, 'INVITE_MAIL_FAILED'::character varying])::text[]))),
    CONSTRAINT ck_user_invitation_failure_stage CHECK (((failure_stage)::text = ANY ((ARRAY['TOKEN_GENERATION'::character varying, 'MAIL_DELIVERY'::character varying])::text[]))),
    CONSTRAINT ck_user_invitation_org_id CHECK (((((target_role_code)::text = 'SUPER_ADMIN'::text) AND (org_id IS NULL)) OR (((target_role_code)::text <> 'SUPER_ADMIN'::text) AND (org_id IS NOT NULL)))),
    CONSTRAINT ck_user_invitation_resend_count CHECK ((resend_count >= 0)),
    CONSTRAINT ck_user_invitation_status CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'SENT'::character varying, 'DELIVERY_FAILED'::character varying, 'ACCEPTED'::character varying, 'EXPIRED'::character varying, 'CANCELLED'::character varying])::text[]))),
    CONSTRAINT ck_user_invitation_target_class_id CHECK (((((target_role_code)::text = 'MANAGER'::text) AND ((target_class_id IS NULL) OR (target_cohort_id IS NOT NULL))) OR (((target_role_code)::text = ANY ((ARRAY['SUPER_ADMIN'::character varying, 'OPERATOR'::character varying, 'TRAINEE'::character varying])::text[])) AND (target_class_id IS NULL)))),
    CONSTRAINT ck_user_invitation_target_cohort_id CHECK (((((target_role_code)::text = ANY ((ARRAY['SUPER_ADMIN'::character varying, 'OPERATOR'::character varying])::text[])) AND (target_cohort_id IS NULL)) OR (((target_role_code)::text = ANY ((ARRAY['MANAGER'::character varying, 'TRAINEE'::character varying])::text[])) AND (target_cohort_id IS NOT NULL)))),
    CONSTRAINT ck_user_invitation_target_role_code CHECK (((target_role_code)::text = ANY ((ARRAY['SUPER_ADMIN'::character varying, 'OPERATOR'::character varying, 'MANAGER'::character varying, 'TRAINEE'::character varying])::text[]))),
    CONSTRAINT ck_user_invitation_updated_at CHECK (((((status)::text = 'SENT'::text) AND (sent_at IS NOT NULL)) OR ((status)::text <> 'SENT'::text))),
    CONSTRAINT ck_user_invitation_updated_at_2 CHECK (((((status)::text = 'ACCEPTED'::text) AND (accepted_at IS NOT NULL) AND (accepted_user_id IS NOT NULL)) OR ((status)::text <> 'ACCEPTED'::text))),
    CONSTRAINT ck_user_invitation_updated_at_3 CHECK (((((status)::text = 'EXPIRED'::text) AND (expired_at IS NOT NULL)) OR ((status)::text <> 'EXPIRED'::text))),
    CONSTRAINT ck_user_invitation_updated_at_4 CHECK (((((status)::text = 'CANCELLED'::text) AND (cancelled_at IS NOT NULL) AND (cancelled_by IS NOT NULL)) OR ((status)::text <> 'CANCELLED'::text))),
    CONSTRAINT ck_user_invitation_updated_at_5 CHECK (((((status)::text = 'DELIVERY_FAILED'::text) AND ((failure_stage)::text = 'MAIL_DELIVERY'::text) AND ((failure_code)::text = 'INVITE_MAIL_FAILED'::text) AND (failed_at IS NOT NULL)) OR ((status)::text <> 'DELIVERY_FAILED'::text))),
    CONSTRAINT ck_user_invitation_updated_at_6 CHECK (((((failure_stage)::text = 'TOKEN_GENERATION'::text) AND ((status)::text = 'PENDING'::text) AND ((failure_code)::text = 'INVITE_TOKEN_FAILED'::text) AND (failed_at IS NOT NULL)) OR ((failure_stage)::text IS DISTINCT FROM 'TOKEN_GENERATION'::text)))
);


--
-- Name: TABLE user_invitation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.user_invitation IS '슈퍼어드민·오퍼레이터·매니저·교육생 초대 한 건의 대상 기관·이메일·역할·기수/반 범위와 발송·실패·수락·취소 상태를 보존하는 업무 원장입니다. 토큰 재발급이 반복되어도 초대 행은 유지하고 현재 사용 가능한 토큰만 교체합니다. | 정의서명: UserInvitation | 제약·비고: • 대상 역할: SUPER_ADMIN / OPERATOR / MANAGER / TRAINEE • SUPER_ADMIN은 기관에 소속되지 않으므로 org_id·target_cohort_id·target_class_id가 모두 NULL이며, org_id는 SUPER_ADMIN일 때만 NULL이고 그 외 역할은 필수입니다. • 상태: PENDING / SENT / DELIVERY_FAILED / ACCEPTED / EXPIRED / CANCELLED • 동일 org_id·target_email_normalized·target_role_code의 미완료 초대는 최대 1건이며 org_id가 NULL인 SUPER_ADMIN 초대도 NULLS NOT DISTINCT로 동일하게 제한합니다. • 초대 상태는 UserInvitation이, 토큰 사용 가능 여부는 OneTimeToken이 각각 소유합니다. • SUPER_ADMIN·OPERATOR는 target_cohort_id·target_class_id가 모두 NULL입니다. • MANAGER는 target_cohort_id가 필수이고 target_class_id는 선택값입니다. 반이 없으면 ACTIVE·미배정 계정으로 가입합니다. • TRAINEE는 target_cohort_id가 필수이고 target_class_id는 NULL이며 명단의 PENDING 계정과 기관·기수·정규화 이메일 경로가 일치해야 합니다. • PENDING에서 토큰 생성 실패가 발생하면 failure_stage=TOKEN_GENERATION, failure_code=INVITE_TOKEN_FAILED, current_token_id=NULL을 보존합니다. • DELIVERY_FAILED이면 failure_stage=MAIL_DELIVERY, failure_code=INVITE_MAIL_FAILED, failure_reason·failed_a';


