--
-- Name: one_time_token; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.one_time_token (
    token_id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid,
    user_id uuid,
    invitation_id uuid,
    target_email public.citext NOT NULL,
    target_email_normalized character varying(320) NOT NULL,
    purpose character varying(50) NOT NULL,
    token_hash character varying(128) NOT NULL,
    payload jsonb NOT NULL,
    issued_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    used_at timestamp with time zone,
    invalidated_at timestamp with time zone,
    invalidated_reason text,
    replaced_by_token_id uuid,
    issued_by uuid,
    issued_request_id text NOT NULL,
    used_request_id text,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT ck_one_time_token_created_at CHECK ((NOT ((used_at IS NOT NULL) AND (invalidated_at IS NOT NULL)))),
    CONSTRAINT ck_one_time_token_expires_at CHECK ((expires_at > issued_at)),
    CONSTRAINT ck_one_time_token_invalidated_reason CHECK ((invalidated_reason = ANY (ARRAY['REPLACED'::text, 'INVITATION_CANCELLED'::text, 'ORGANIZATION_SUSPENDED'::text, 'ORGANIZATION_DELETION_PENDING'::text, 'ACCOUNT_INACTIVATED'::text, 'PASSWORD_CHANGED'::text, 'SECURITY_ACTION'::text, 'ADMIN_REVOKED'::text]))),
    CONSTRAINT ck_one_time_token_invalidated_reason_2 CHECK ((((invalidated_at IS NULL) AND (invalidated_reason IS NULL)) OR ((invalidated_at IS NOT NULL) AND (invalidated_reason IS NOT NULL)))),
    CONSTRAINT ck_one_time_token_purpose CHECK (((purpose)::text = ANY ((ARRAY['INVITE_SUPER_ADMIN'::character varying, 'INVITE_OPERATOR_MANAGER'::character varying, 'INVITE_TRAINEE'::character varying, 'EMAIL_VERIFY'::character varying, 'PASSWORD_RESET'::character varying])::text[]))),
    CONSTRAINT ck_one_time_token_replaced_by_token_id CHECK (((replaced_by_token_id IS NULL) OR (invalidated_at IS NOT NULL))),
    CONSTRAINT ck_one_time_token_used_request_id CHECK ((((used_at IS NULL) AND (used_request_id IS NULL)) OR ((used_at IS NOT NULL) AND (used_request_id IS NOT NULL))))
);


--
-- Name: TABLE one_time_token; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.one_time_token IS '초대 수락, 이메일 소유 확인, 비밀번호 재설정에 사용하는 1회성 자격 증명 원장입니다. 원문 대신 해시를 저장하고 발급·사용·무효화·대체 관계를 분리하여 만료·재사용·재발송을 추적합니다. | 정의서명: OneTimeToken | 제약·비고: • token_hash는 전체 UNIQUE이며 일회성 토큰 원문은 DB·로그·감사 payload에 저장하지 않습니다. • 목적: INVITE_SUPER_ADMIN / INVITE_OPERATOR_MANAGER / INVITE_TRAINEE / EMAIL_VERIFY / PASSWORD_RESET • expires_at은 issued_at보다 이후여야 합니다. • INVITE_SUPER_ADMIN·INVITE_OPERATOR_MANAGER·INVITE_TRAINEE는 invitation_id가 필수이고 EMAIL_VERIFY·PASSWORD_RESET은 invitation_id가 NULL입니다. • 초대 목적 토큰은 연결된 UserInvitation의 org_id·target_email_normalized·대상 역할·기수/반 범위와 일치해야 합니다. • 가입 전 SUPER_ADMIN·OPERATOR·MANAGER 초대는 user_id가 NULL일 수 있고 TRAINEE 초대는 기존 PENDING 교육생 계정·명단 경로를 함께 검증합니다. • 기관 사용자 초대·재설정은 org_id가 필수이며 기관 미소속 SUPER_ADMIN의 INVITE_SUPER_ADMIN·PASSWORD_RESET만 org_id NULL을 허용합니다. • PASSWORD_RESET은 ACTIVE 대상 user_id가 필수입니다. • used_at과 used_request_id는 동시 NULL 또는 동시 NOT NULL이며 사용 완료와 무효화는 동시에 기록하지 않습니다. • invalidated_at이 있으면 invalidated_reason이 필수입니다. • 무효화 사유: REPLACED / INVIT';


