--
-- Name: operational_alert; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operational_alert AS
 WITH manager_unassigned AS (
         SELECT c.org_id,
            c.cohort_id,
            'MANAGER_UNASSIGNED'::text AS alert_type,
            'CLASS'::text AS scope_type,
            c.class_id AS scope_id,
            'HIGH'::text AS severity,
            'NO_ACTIVE_MANAGER'::text AS reason_code,
            CURRENT_TIMESTAMP AS occurred_as_of_at
           FROM public.class c
          WHERE ((c.deleted_at IS NULL) AND ((c.lifecycle_status)::text <> 'CLOSED'::text) AND (NOT (EXISTS ( SELECT 1
                   FROM public.manager_assignment ma
                  WHERE ((ma.class_id = c.class_id) AND ((ma.status)::text = 'ACTIVE'::text) AND (ma.unassigned_at IS NULL))))))
        ), project_not_ready AS (
         SELECT p.org_id,
            p.cohort_id,
            'PROJECT_NOT_READY'::text AS "?column?",
            'PROJECT'::text AS "?column?",
            p.project_id,
            'MEDIUM'::text AS "?column?",
                CASE
                    WHEN ((NOT p.curriculum_not_applicable) AND (NOT (EXISTS ( SELECT 1
                       FROM public.project_curriculum pc
                      WHERE (pc.project_id = p.project_id))))) THEN 'CURRICULUM_REQUIRED'::text
                    WHEN (( SELECT count(*) AS count
                       FROM (public.project_verification_concept pvc
                         JOIN public.project_verification_concept_set pcs ON ((pcs.concept_set_id = pvc.concept_set_id)))
                      WHERE ((pcs.project_id = p.project_id) AND ((pcs.status)::text = 'ACTIVE'::text))) <> 3) THEN 'THREE_CONCEPTS_REQUIRED'::text
                    ELSE 'ROUND_REQUIRED'::text
                END AS "case",
            CURRENT_TIMESTAMP AS "current_timestamp"
           FROM public.project p
          WHERE ((p.deleted_at IS NULL) AND ((p.lifecycle_status)::text <> ALL ((ARRAY['RUNNING'::character varying, 'CLOSED'::character varying])::text[])) AND (((NOT p.curriculum_not_applicable) AND (NOT (EXISTS ( SELECT 1
                   FROM public.project_curriculum pc
                  WHERE (pc.project_id = p.project_id))))) OR (( SELECT count(*) AS count
                   FROM (public.project_verification_concept pvc
                     JOIN public.project_verification_concept_set pcs ON ((pcs.concept_set_id = pvc.concept_set_id)))
                  WHERE ((pcs.project_id = p.project_id) AND ((pcs.status)::text = 'ACTIVE'::text))) <> 3) OR (NOT (EXISTS ( SELECT 1
                   FROM public.project_assessment_round r
                  WHERE ((r.project_id = p.project_id) AND (r.deleted_at IS NULL)))))))
        ), analysis_failed AS (
         SELECT aj.org_id,
            r.cohort_id,
            'ANALYSIS_FAILED'::text AS "?column?",
            'TEAM'::text AS "?column?",
            aj.team_id,
            'HIGH'::text AS "?column?",
            'ANALYSIS_JOB_FAILED'::text AS "?column?",
            COALESCE(aj.completed_at, aj.started_at, CURRENT_TIMESTAMP) AS "coalesce"
           FROM (public.analysis_job aj
             JOIN public.project_assessment_round r ON ((r.assessment_round_id = aj.assessment_round_id)))
          WHERE ((aj.status)::text = 'FAILED'::text)
        ), submission_overdue AS (
         SELECT r.org_id,
            r.cohort_id,
            'SUBMISSION_OVERDUE'::text AS "?column?",
            'TEAM'::text AS "?column?",
            t.team_id,
            'HIGH'::text AS "?column?",
            'SUBMISSION_NOT_FOUND'::text AS "?column?",
            r.submission_due_at
           FROM (public.project_assessment_round r
             JOIN public.team t ON (((t.project_id = r.project_id) AND (t.deleted_at IS NULL))))
          WHERE ((r.submission_due_at < CURRENT_TIMESTAMP) AND (NOT (EXISTS ( SELECT 1
                   FROM public.submission s
                  WHERE ((s.assessment_round_id = r.assessment_round_id) AND (s.team_id = t.team_id) AND s.is_current)))))
        ), z AS (
         SELECT manager_unassigned.org_id,
            manager_unassigned.cohort_id,
            manager_unassigned.alert_type,
            manager_unassigned.scope_type,
            manager_unassigned.scope_id,
            manager_unassigned.severity,
            manager_unassigned.reason_code,
            manager_unassigned.occurred_as_of_at
           FROM manager_unassigned
        UNION ALL
         SELECT project_not_ready.org_id,
            project_not_ready.cohort_id,
            project_not_ready."?column?",
            project_not_ready."?column?_1" AS "?column?",
            project_not_ready.project_id,
            project_not_ready."?column?_2" AS "?column?",
            project_not_ready."case",
            project_not_ready."current_timestamp"
           FROM project_not_ready project_not_ready(org_id, cohort_id, "?column?", "?column?_1", project_id, "?column?_2", "case", "current_timestamp")
        UNION ALL
         SELECT analysis_failed.org_id,
            analysis_failed.cohort_id,
            analysis_failed."?column?",
            analysis_failed."?column?_1" AS "?column?",
            analysis_failed.team_id,
            analysis_failed."?column?_2" AS "?column?",
            analysis_failed."?column?_3" AS "?column?",
            analysis_failed."coalesce"
           FROM analysis_failed analysis_failed(org_id, cohort_id, "?column?", "?column?_1", team_id, "?column?_2", "?column?_3", "coalesce")
        UNION ALL
         SELECT submission_overdue.org_id,
            submission_overdue.cohort_id,
            submission_overdue."?column?",
            submission_overdue."?column?_1" AS "?column?",
            submission_overdue.team_id,
            submission_overdue."?column?_2" AS "?column?",
            submission_overdue."?column?_3" AS "?column?",
            submission_overdue.submission_due_at
           FROM submission_overdue submission_overdue(org_id, cohort_id, "?column?", "?column?_1", team_id, "?column?_2", "?column?_3", submission_due_at)
        )
 SELECT org_id,
    cohort_id,
    (alert_type)::character varying(100) AS alert_type,
    (scope_type)::character varying(100) AS scope_type,
    scope_id,
    (severity)::character varying(100) AS severity,
    (reason_code)::character varying(100) AS reason_code,
    occurred_as_of_at
   FROM z;


--
-- Name: operator_cohort_class_risk_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operator_cohort_class_risk_view AS
 SELECT rm.snapshot_id,
    rm.class_id,
    (COALESCE((rm.dimension_snapshot ->> 'className'::text), (c.name)::text))::character varying(200) AS class_name_snapshot,
    (COALESCE(rm.denominator, (0)::numeric))::integer AS eligible_trainee_count,
    (COALESCE(rm.numerator, rm.metric_value, (0)::numeric))::integer AS risk_trainee_count,
    (
        CASE
            WHEN ((rm.denominator IS NULL) OR (rm.denominator = (0)::numeric)) THEN NULL::numeric
            ELSE (COALESCE(rm.numerator, rm.metric_value, (0)::numeric) / rm.denominator)
        END)::numeric(18,6) AS risk_rate,
    COALESCE(rm.missing_count, 0) AS missing_count,
    rm.aggregation_status,
    rm.display_order
   FROM (public.report_metric rm
     LEFT JOIN public.class c ON ((c.class_id = rm.class_id)))
  WHERE (((rm.section_code)::text = 'CLASS_RISK'::text) AND ((rm.metric_grain_code)::text = 'CLASS'::text));


--
-- Name: operator_cohort_group_underperformance_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operator_cohort_group_underperformance_view AS
 SELECT rm.snapshot_id,
    rm.class_id,
    (COALESCE((rm.dimension_snapshot ->> 'className'::text), (c.name)::text))::character varying(200) AS class_name_snapshot,
    rm.teaches_id,
    (COALESCE((rm.dimension_snapshot ->> 'conceptName'::text), (t.canonical_name)::text))::character varying(200) AS concept_name_snapshot,
    (COALESCE(rm.numerator, rm.metric_value, (0)::numeric))::integer AS low_level_count,
    rm.denominator,
        CASE
            WHEN (rm.metric_value IS NULL) THEN NULL::boolean
            ELSE (rm.metric_value > (0)::numeric)
        END AS underperformance_flag,
    (count(*) OVER (PARTITION BY rm.snapshot_id))::integer AS evaluated_class_concept_count,
    (
        CASE
            WHEN ((rm.denominator IS NULL) OR (rm.denominator = (0)::numeric)) THEN 'NO_ELIGIBLE_PARTICIPANT'::text
            ELSE NULL::text
        END)::character varying(100) AS empty_reason_code,
    rm.aggregation_status
   FROM ((public.report_metric rm
     LEFT JOIN public.class c ON ((c.class_id = rm.class_id)))
     LEFT JOIN public.teaches t ON ((t.teaches_id = rm.teaches_id)))
  WHERE (((rm.section_code)::text = 'GROUP_UNDERPERFORMANCE'::text) AND ((rm.metric_grain_code)::text = 'CLASS_CONCEPT'::text));


--
-- Name: operator_cohort_growth_transition_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operator_cohort_growth_transition_view AS
 SELECT rm.snapshot_id,
    (COALESCE(rm.dimension_key, (re.result_category_code)::text))::character varying(100) AS transition_category,
    (COALESCE(rm.numerator, rm.metric_value, (0)::numeric))::integer AS participant_count,
    rm.denominator,
    (COALESCE(((rm.policy_parameter_snapshot ->> 'baselineBoundary'::text))::numeric, re.baseline_value))::numeric(18,6) AS baseline_boundary,
    (COALESCE(((rm.policy_parameter_snapshot ->> 'outcomeBoundary'::text))::numeric, re.outcome_value))::numeric(18,6) AS outcome_boundary,
    ((COALESCE(rm.denominator, (0)::numeric) - (COALESCE(rm.missing_count, 0))::numeric))::integer AS eligible_count,
    COALESCE(rm.missing_count, 0) AS excluded_count,
    rm.policy_parameter_snapshot
   FROM (public.report_metric rm
     LEFT JOIN public.report_evidence re ON (((re.metric_id = rm.metric_id) AND ((re.participant_section_code)::text = 'GROWTH_TRANSITION'::text))))
  WHERE (((rm.section_code)::text = 'COHORT_GROWTH_TRANSITION'::text) AND ((rm.metric_grain_code)::text = 'TRANSITION_CATEGORY'::text));


--
-- Name: operator_cohort_outcome_occurrence_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operator_cohort_outcome_occurrence_view AS
 SELECT snapshot_id,
    subject_user_id,
    source_assessment_round_id,
    subject_user_id AS user_id,
    source_class_id AS class_id,
    source_assessment_round_id AS round_id,
    result_category_code AS occurrence_result_code,
    is_joint_top,
    top_tie_count,
    source_role_code,
    subject_display_snapshot
   FROM public.report_evidence re
  WHERE ((evidence_category)::text = 'PARTICIPANT_RESULT_OCCURRENCE'::text);


--
-- Name: operator_cohort_outcome_participant_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operator_cohort_outcome_participant_view AS
 SELECT re.snapshot_id,
    re.participant_section_code,
    re.subject_user_id,
    re.subject_user_id AS user_id,
    (COALESCE((re.subject_display_snapshot ->> 'displayName'::text), (u.name)::text))::character varying(200) AS display_name_snapshot,
    re.subject_class_id AS class_id,
    (COALESCE((re.subject_display_snapshot ->> 'className'::text), (c.name)::text))::character varying(200) AS class_name_snapshot,
    re.eligibility_status,
    re.exclusion_reason_code,
    re.result_category_code,
    re.baseline_value,
    re.outcome_value,
    re.occurrence_count,
    re.is_joint_top,
    re.top_tie_count
   FROM ((public.report_evidence re
     LEFT JOIN public.app_user u ON ((u.user_id = re.subject_user_id)))
     LEFT JOIN public.class c ON ((c.class_id = re.subject_class_id)))
  WHERE ((re.evidence_category)::text = 'PARTICIPANT_RESULT'::text);


--
-- Name: operator_cohort_outcome_summary_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operator_cohort_outcome_summary_view AS
 SELECT rs.snapshot_id,
    rpt.cohort_id,
    rpt.report_id,
    COALESCE(((rs.summary_payload ->> 'eligibleCount'::text))::integer, rs.sample_count) AS eligible_count,
    COALESCE(((rs.summary_payload ->> 'excludedCount'::text))::integer, rs.missing_count) AS excluded_count,
    COALESCE((rs.summary_payload -> 'transitionCounts'::text), '{}'::jsonb) AS transition_counts,
    COALESCE(((rs.summary_payload ->> 'excellentTraineeCount'::text))::integer, met.excellent_count, 0) AS excellent_trainee_count,
    COALESCE(((rs.summary_payload ->> 'riskyClassCount'::text))::integer, met.risky_class_count, 0) AS risky_class_count,
    COALESCE(((rs.summary_payload ->> 'groupUnderperformanceCount'::text))::integer, met.group_count, 0) AS group_underperformance_count,
    (
        CASE
            WHEN ((rs.completion_status)::text = 'FULL'::text) THEN 'COMPLETE'::text
            ELSE 'PARTIAL'::text
        END)::character varying(20) AS aggregation_status,
    met.policy_version
   FROM ((public.report rpt
     JOIN public.report_snapshot rs ON (((rs.report_id = rpt.report_id) AND rs.is_active)))
     LEFT JOIN LATERAL ( SELECT (count(*) FILTER (WHERE ((x.section_code)::text = 'EXCELLENT_TRAINEE'::text)))::integer AS excellent_count,
            (count(*) FILTER (WHERE ((x.section_code)::text = 'CLASS_RISK'::text)))::integer AS risky_class_count,
            (count(*) FILTER (WHERE ((x.section_code)::text = 'GROUP_UNDERPERFORMANCE'::text)))::integer AS group_count,
            max(x.policy_version) AS policy_version
           FROM public.report_metric x
          WHERE (x.snapshot_id = rs.snapshot_id)) met ON (true))
  WHERE ((rpt.report_type)::text = 'COHORT_OUTCOME'::text);


--
-- Name: operator_cohort_report_status_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operator_cohort_report_status_view AS
 WITH report_types(report_type) AS (
         VALUES ('COHORT_CURRICULUM_DIAGNOSIS'::text), ('COHORT_OUTCOME'::text)
        )
 SELECT c.org_id,
    c.cohort_id,
    (rt.report_type)::character varying(100) AS report_type,
    stats.required_project_count AS required_source_project_count,
    stats.completed_project_count AS completed_source_project_count,
    stats.required_round_count AS required_source_round_count,
    stats.completed_round_count AS completed_source_round_count,
    stats.published_round_count AS published_source_round_count,
    GREATEST((stats.required_round_count - stats.completed_round_count), 0) AS remaining_source_round_count,
    (
        CASE
            WHEN (stats.required_round_count = 0) THEN 'NO_SOURCE'::text
            WHEN (stats.completed_round_count = stats.required_round_count) THEN 'COMPLETE'::text
            ELSE 'IN_PROGRESS'::text
        END)::character varying(100) AS source_status,
    (COALESCE(rpt.lifecycle_status, 'NOT_CREATED'::character varying))::character varying(100) AS report_status,
    rpt.report_id,
    rs.snapshot_id AS active_snapshot_id,
    rpt.scheduled_publish_at,
    rpt.published_at,
    gr.generation_run_id AS latest_generation_run_id,
    gr.status AS latest_generation_status,
    ((rpt.published_at IS NOT NULL) AND (rs.snapshot_id IS NOT NULL)) AS can_export_pdf,
    (
        CASE
            WHEN (rpt.report_id IS NULL) THEN 'REPORT_NOT_CREATED'::text
            WHEN (rpt.published_at IS NULL) THEN 'REPORT_NOT_PUBLISHED'::text
            WHEN (rs.snapshot_id IS NULL) THEN 'SNAPSHOT_NOT_READY'::text
            ELSE NULL::text
        END)::character varying(100) AS pdf_unavailable_reason_code,
    'COMPLETE'::character varying(20) AS aggregation_status,
    CURRENT_TIMESTAMP AS as_of_at
   FROM (((((public.cohort c
     CROSS JOIN report_types rt)
     LEFT JOIN LATERAL ( SELECT (count(DISTINCT p.project_id))::integer AS required_project_count,
            (count(DISTINCT p.project_id) FILTER (WHERE ((p.lifecycle_status)::text = 'CLOSED'::text)))::integer AS completed_project_count,
            (count(DISTINCT r.assessment_round_id))::integer AS required_round_count,
            (count(DISTINCT r.assessment_round_id) FILTER (WHERE ((r.status)::text = 'COMPLETED'::text)))::integer AS completed_round_count,
            (count(DISTINCT r.assessment_round_id) FILTER (WHERE (EXISTS ( SELECT 1
                   FROM public.report rr
                  WHERE ((rr.assessment_round_id = r.assessment_round_id) AND (rr.published_at IS NOT NULL))))))::integer AS published_round_count
           FROM (public.project p
             LEFT JOIN public.project_assessment_round r ON (((r.project_id = p.project_id) AND (r.deleted_at IS NULL))))
          WHERE ((p.cohort_id = c.cohort_id) AND (p.deleted_at IS NULL))) stats ON (true))
     LEFT JOIN LATERAL ( SELECT x.report_id,
            x.org_id,
            x.cohort_id,
            x.class_id,
            x.user_id,
            x.assessment_round_id,
            x.report_type,
            x.lifecycle_status,
            x.scheduled_publish_at,
            x.published_at,
            x.trainee_release_status,
            x.trainee_disclosure_scope,
            x.trainee_released_at,
            x.trainee_released_by
           FROM public.report x
          WHERE ((x.cohort_id = c.cohort_id) AND ((x.report_type)::text = rt.report_type) AND (x.class_id IS NULL) AND (x.user_id IS NULL))
          ORDER BY
                CASE
                    WHEN ((x.lifecycle_status)::text = 'ACTIVE'::text) THEN 0
                    ELSE 1
                END, x.published_at DESC NULLS LAST
         LIMIT 1) rpt ON (true))
     LEFT JOIN public.report_snapshot rs ON (((rs.report_id = rpt.report_id) AND rs.is_active)))
     LEFT JOIN LATERAL ( SELECT x.generation_run_id,
            x.report_id,
            x.trigger_type,
            x.idempotency_key,
            x.calculation_version,
            x.status,
            x.failure_reason,
            x.execution_no,
            x.started_at,
            x.completed_at,
            x.request_fingerprint
           FROM public.report_generation_run x
          WHERE (x.report_id = rpt.report_id)
          ORDER BY x.execution_no DESC
         LIMIT 1) gr ON (true))
  WHERE (c.deleted_at IS NULL);


--
-- Name: organization; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.organization (
    org_id uuid DEFAULT gen_random_uuid() NOT NULL,
    name character varying(200) NOT NULL,
    normalized_name character varying(200) NOT NULL,
    slug character varying(64),
    display_code character varying(32),
    email_domain character varying(255),
    create_idempotency_key uuid,
    create_request_fingerprint character(64),
    status character varying(100) DEFAULT 'ACTIVE'::character varying NOT NULL,
    retention_until timestamp with time zone,
    suspended_at timestamp with time zone,
    suspended_reason text,
    deletion_idempotency_key uuid,
    deletion_request_fingerprint character(64),
    deletion_requested_at timestamp with time zone,
    deletion_requested_by uuid,
    purge_status character varying(30) DEFAULT 'NONE'::character varying NOT NULL,
    purge_started_at timestamp with time zone,
    purge_failed_at timestamp with time zone,
    purge_failure_code character varying(100),
    restored_at timestamp with time zone,
    restored_by uuid,
    deleted_at timestamp with time zone,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by uuid,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    row_version integer DEFAULT 0 NOT NULL,
    CONSTRAINT ck_organization_create_key_pair CHECK (((create_idempotency_key IS NULL) = (create_request_fingerprint IS NULL))),
    CONSTRAINT ck_organization_create_request_fingerprint_format CHECK (((create_request_fingerprint IS NULL) OR (create_request_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT ck_organization_deleted_at_required CHECK ((((status)::text <> 'DELETED'::text) OR (deleted_at IS NOT NULL))),
    CONSTRAINT ck_organization_deletion_key_pair CHECK (((deletion_idempotency_key IS NULL) = (deletion_request_fingerprint IS NULL))),
    CONSTRAINT ck_organization_deletion_pending_fields CHECK ((((status)::text <> ALL ((ARRAY['DELETION_PENDING'::character varying, 'DELETED'::character varying])::text[])) OR ((retention_until IS NOT NULL) AND (deletion_requested_at IS NOT NULL) AND (deletion_requested_by IS NOT NULL)))),
    CONSTRAINT ck_organization_deletion_request_fingerprint_format CHECK (((deletion_request_fingerprint IS NULL) OR (deletion_request_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT ck_organization_email_domain_format CHECK (((email_domain IS NULL) OR ((email_domain)::text ~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$'::text))),
    CONSTRAINT ck_organization_purge_failed_fields CHECK ((((purge_status)::text <> 'FAILED'::text) OR ((purge_failed_at IS NOT NULL) AND (purge_failure_code IS NOT NULL)))),
    CONSTRAINT ck_organization_purge_failure_code_format CHECK (((purge_failure_code IS NULL) OR ((purge_failure_code)::text ~ '^[A-Z][A-Z0-9_]{0,99}$'::text))),
    CONSTRAINT ck_organization_purge_status CHECK (((purge_status)::text = ANY ((ARRAY['NONE'::character varying, 'SCHEDULED'::character varying, 'IN_PROGRESS'::character varying, 'FAILED'::character varying, 'COMPLETED'::character varying])::text[]))),
    CONSTRAINT ck_organization_restored_pair CHECK (((restored_at IS NULL) = (restored_by IS NULL))),
    CONSTRAINT ck_organization_row_version CHECK ((row_version >= 0)),
    CONSTRAINT ck_organization_slug CHECK (((slug IS NULL) OR ((slug)::text ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'::text))),
    CONSTRAINT ck_organization_status CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'SUSPENDED'::character varying, 'DELETION_PENDING'::character varying, 'DELETED'::character varying])::text[]))),
    CONSTRAINT ck_organization_suspended_at_required CHECK ((((status)::text <> 'SUSPENDED'::text) OR (suspended_at IS NOT NULL)))
);


--
-- Name: TABLE organization; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.organization IS '서비스를 이용하는 학교·회사 같은 한 고객 기관을 나타냅니다. 건물의 ‘기관 기본 카드’처럼 기관 이름과 운영 상태, 삭제·복구 기록을 한곳에서 관리하며 다른 기관의 데이터가 섞이지 않게 하는 가장 위쪽 기준점입니다. | 정의서명: Organization | 제약·비고: • 상태: ACTIVE / SUSPENDED / DELETION_PENDING / DELETED • normalized_name은 물리 파기 전 전체 기관 범위 UNIQUE • slug는 값이 있으면 전체 기관 UNIQUE • 생성·삭제 멱등성 키와 요청 지문은 각각 동시 NULL 또는 동시 NOT NULL • DELETION_PENDING·DELETED이면 deletion_requested_at·deletion_requested_by·retention_until 필수 • DELETED이면 deleted_at 필수 • 복구 일시와 복구자는 쌍으로 관리 • 파기 상태: NONE / SCHEDULED / IN_PROGRESS / FAILED / COMPLETED • purge_status는 NOT NULL·기본값 NONE이며 삭제 요청 성공 시 SCHEDULED로 전이 • BUDGET_EXCEEDED·ORGANIZATION_OPERATOR_EMPTY·display_status·is_new는 조회 파생값 • row_version >= 0 • purge_failure_code는 영문 대문자·숫자·밑줄 1~100자의 확장형 서비스 코드 카탈로그를 사용하며 DB CHECK는 형식만 검증 • status=''SUSPENDED''이면 suspended_at이 필수이며, 정지는 기관 사용자의 로그인·업무 요청을 막지만 사용자 행을 일괄 삭제하거나 INACTIVE로 바꾸지 않습니다. • purge_status=''FAILED''이면 purge';


--
-- Name: COLUMN organization.org_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.organization.org_id IS '기관·테넌트를 식별한다.';


--
-- Name: COLUMN organization.name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.organization.name IS '화면 표시 기관명이다.';


--
-- Name: COLUMN organization.normalized_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.organization.normalized_name IS 'Unicode NFKC, trim, 연속 공백 축소, 영문 case folding을 적용한 기관명이다. 물리 파기 전에는 상태와 관계없이 재사용하지 않는다.';


--
-- Name: COLUMN organization.slug; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.organization.slug IS 'URL·외부 연동용 짧은 기관 식별값이다.';


--
-- Name: COLUMN organization.display_code; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.organization.display_code IS '화면 표시용 기관 코드다.';


--
-- Name: COLUMN organization.email_domain; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.organization.email_domain IS '기관 사용자 초대 입력 검증용 도메인이다. NULL이면 도메인 제한을 적용하지 않으며 권한·테넌트의 단독 근거로 사용하지 않는다.';


--
-- Name: COLUMN organization.create_idempotency_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.organization.create_idempotency_key IS 'SA-01 기관 생성 성공 결과를 클라이언트 생성 의도와 연결한다. 이관·시드 행은 NULL을 허용한다.';


--
-- Name: COLUMN organization.create_request_fingerprint; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.organization.create_request_fingerprint IS '정규화한 기관 생성 요청의 지문이다. 동일 멱등성 키 재사용 시 요청 동일성을 검증한다.';


--
-- Name: COLUMN organization.status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.organization.status IS '기관 생명주기 상태다. 비용·미배정 경고는 저장하지 않는다.';


--
-- Name: COLUMN organization.retention_until; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.organization.retention_until IS '삭제 요청 시점의 유효 `retention_days`로 고정한 보존 만료 시각이다. 이후 정책 변경으로 자동 갱신하지 않는다.';


--
-- Name: COLUMN organization.suspended_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.organization.suspended_at IS '기관 정지 시각이다.';


--
-- Name: COLUMN organization.suspended_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.organization.suspended_reason IS '기관 정지 사유다.';


--
-- Name: COLUMN organization.deletion_idempotency_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.organization.deletion_idempotency_key IS '기관 삭제 요청의 사용자 의도를 식별한다. 같은 키·같은 지문은 최초 결과를 반환한다.';


--
-- Name: COLUMN organization.deletion_request_fingerprint; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.organization.deletion_request_fingerprint IS '기관명 확인값과 삭제 요청을 정규화한 지문이다.';


--
-- Name: COLUMN organization.deletion_requested_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.organization.deletion_requested_at IS '삭제 요청 시각이다.';


--
-- Name: COLUMN organization.deletion_requested_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.organization.deletion_requested_by IS '삭제 요청 슈퍼어드민이다.';


--
-- Name: COLUMN organization.purge_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.organization.purge_status IS '기관 물리 파기 진행 상태다. 삭제 요청 성공 시 `SCHEDULED`로 전이한다.';


--
-- Name: COLUMN organization.purge_started_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.organization.purge_started_at IS '최근 물리 파기 실행 시작 시각이다.';


--
-- Name: COLUMN organization.purge_failed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.organization.purge_failed_at IS '최근 물리 파기 실패 시각이다.';


--
-- Name: COLUMN organization.purge_failure_code; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.organization.purge_failure_code IS '`SYS.ORGANIZATION_PURGE_FAILURE_CODE` 확장형 서비스 코드 카탈로그다.';


--
-- Name: COLUMN organization.restored_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.organization.restored_at IS '보존기간 내 삭제 요청을 복구한 최근 시각이다.';


--
-- Name: COLUMN organization.restored_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.organization.restored_by IS '최근 복구 슈퍼어드민이다.';


--
-- Name: COLUMN organization.deleted_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.organization.deleted_at IS '삭제 확정 시각이며 그 전에는 NULL이다.';


--
-- Name: COLUMN organization.created_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.organization.created_by IS '기관 생성자다.';


--
-- Name: COLUMN organization.created_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.organization.created_at IS '최초 생성 시각이다.';


