--
-- Name: organization_usage_snapshot; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.organization_usage_snapshot (
    usage_snapshot_id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    period_type character varying(20) NOT NULL,
    period_start_at timestamp with time zone NOT NULL,
    period_end_at timestamp with time zone NOT NULL,
    as_of_at timestamp with time zone NOT NULL,
    active_trainee_count integer,
    completed_session_count integer,
    grading_execution_count integer,
    published_report_count integer,
    ai_call_count bigint,
    input_token_count bigint,
    output_token_count bigint,
    cached_token_count bigint,
    unpriced_call_count bigint,
    unpriced_input_token_count bigint,
    unpriced_output_token_count bigint,
    cost_completeness_status character varying(30),
    estimated_cost numeric(18,6),
    actual_cost numeric(18,6),
    effective_cost numeric(18,6),
    currency_code character varying(3) DEFAULT 'USD'::character varying,
    aggregation_status character varying(20) NOT NULL,
    failure_stage character varying(100),
    failure_code character varying(100),
    failure_reason text,
    failed_at timestamp with time zone,
    is_retryable boolean,
    source_watermark text,
    calculation_version integer NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT ck_org_usage_snapshot_failed_fields CHECK (((((aggregation_status)::text = 'FAILED'::text) AND (failure_stage IS NOT NULL) AND (failure_code IS NOT NULL) AND (failed_at IS NOT NULL) AND (is_retryable IS NOT NULL)) OR (((aggregation_status)::text <> 'FAILED'::text) AND (failure_code IS NULL) AND (failed_at IS NULL) AND (is_retryable IS NULL)))),
    CONSTRAINT ck_org_usage_snapshot_failure_code_format CHECK (((failure_code IS NULL) OR ((failure_code)::text ~ '^[A-Z][A-Z0-9_]{0,99}$'::text))),
    CONSTRAINT ck_org_usage_snapshot_period_order CHECK ((period_end_at > period_start_at)),
    CONSTRAINT ck_org_usage_snapshot_succeeded_fields CHECK (((((aggregation_status)::text = 'SUCCEEDED'::text) AND (effective_cost IS NOT NULL) AND ((currency_code)::text = 'USD'::text) AND (cost_completeness_status IS NOT NULL)) OR ((aggregation_status)::text <> 'SUCCEEDED'::text))),
    CONSTRAINT ck_organization_usage_snapshot_active_trainee_count_min CHECK ((active_trainee_count >= 0)),
    CONSTRAINT ck_organization_usage_snapshot_actual_cost_min CHECK ((actual_cost >= (0)::numeric)),
    CONSTRAINT ck_organization_usage_snapshot_aggregation_status CHECK (((aggregation_status)::text = ANY ((ARRAY['SUCCEEDED'::character varying, 'FAILED'::character varying])::text[]))),
    CONSTRAINT ck_organization_usage_snapshot_ai_call_count_min CHECK ((ai_call_count >= 0)),
    CONSTRAINT ck_organization_usage_snapshot_cached_token_count_min CHECK ((cached_token_count >= 0)),
    CONSTRAINT ck_organization_usage_snapshot_calculation_version_min CHECK ((calculation_version >= 1)),
    CONSTRAINT ck_organization_usage_snapshot_completed_session_count_min CHECK ((completed_session_count >= 0)),
    CONSTRAINT ck_organization_usage_snapshot_cost_completeness_status CHECK (((cost_completeness_status)::text = ANY ((ARRAY['COMPLETE'::character varying, 'PARTIAL_UNPRICED'::character varying])::text[]))),
    CONSTRAINT ck_organization_usage_snapshot_currency_code CHECK (((currency_code)::text = 'USD'::text)),
    CONSTRAINT ck_organization_usage_snapshot_estimated_cost_min CHECK ((estimated_cost >= (0)::numeric)),
    CONSTRAINT ck_organization_usage_snapshot_failure_stage CHECK (((failure_stage)::text = ANY ((ARRAY['STORAGE_MEASUREMENT'::character varying, 'ACTIVITY_AGGREGATION'::character varying, 'AI_COST_AGGREGATION'::character varying, 'SNAPSHOT_COMPOSITION'::character varying, 'CURRENCY_VALIDATION'::character varying])::text[]))),
    CONSTRAINT ck_organization_usage_snapshot_grading_execution_count_min CHECK ((grading_execution_count >= 0)),
    CONSTRAINT ck_organization_usage_snapshot_input_token_count_min CHECK ((input_token_count >= 0)),
    CONSTRAINT ck_organization_usage_snapshot_output_token_count_min CHECK ((output_token_count >= 0)),
    CONSTRAINT ck_organization_usage_snapshot_period_type CHECK (((period_type)::text = ANY ((ARRAY['DAILY'::character varying, 'MONTHLY'::character varying, 'CUSTOM'::character varying])::text[]))),
    CONSTRAINT ck_organization_usage_snapshot_published_report_count_min CHECK ((published_report_count >= 0)),
    CONSTRAINT ck_organization_usage_snapshot_unpriced_call_count_min CHECK ((unpriced_call_count >= 0)),
    CONSTRAINT ck_organization_usage_snapshot_unpriced_input_token_count_min CHECK ((unpriced_input_token_count >= 0)),
    CONSTRAINT ck_organization_usage_snapshot_unpriced_output_token_count_min CHECK ((unpriced_output_token_count >= 0))
);


--
-- Name: TABLE organization_usage_snapshot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.organization_usage_snapshot IS '특정 기간과 시점의 기관 사용량을 사진처럼 저장한 집계 기록입니다. 활성 교육생 수, 세션 수, AI 호출·토큰·비용을 모아 두며, 집계에 성공했는지 실패했는지도 함께 남깁니다. | 정의서명: OrganizationUsageSnapshot | 제약·비고: • 기간 유형: DAILY / MONTHLY / CUSTOM • 집계 상태: SUCCEEDED / FAILED • 비용 완전성: COMPLETE / PARTIAL_UNPRICED • 성공 스냅샷은 기관·기간·기준 시각별 중복 금지 • SUCCEEDED이면 필수 집계 수치·effective_cost·currency_code=''USD''·비용 완전성 상태 보유 • FAILED이면 집계 수치·비용·통화는 NULL이고 failure_stage·failure_code·failed_at·is_retryable 필수 • 실패 단계: STORAGE_MEASUREMENT / ACTIVITY_AGGREGATION / AI_COST_AGGREGATION / SNAPSHOT_COMPOSITION / CURRENCY_VALIDATION • 모든 수치·비용은 0 이상 • failure_code는 SYS.ORGANIZATION_USAGE_FAILURE_CODE 영문 대문자·숫자·밑줄 1~100자의 확장형 서비스 코드 카탈로그를 사용 • SUCCEEDED에서 실제 사용이 없으면 숫자 0을 저장할 수 있지만, FAILED의 NULL은 ‘0’이 아니라 ‘계산하지 못함’을 뜻합니다. • UNPRICED 호출은 0원으로 합산하지 않고 호출·토큰 수와 PARTIAL_UNPRICED 상태를 남깁니다. • effective_cost는 각 호출에서 실제 비용이 있으면 actual_cost, 없으면 estimated_cost를 선택하여 계산하며 둘을 중복 합산하지 않습니다. • ';


