--
-- Name: operator_cost_overview_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operator_cost_overview_view AS
 WITH current_policy AS (
         SELECT DISTINCT ON (op.org_id) op.policy_id,
            op.org_id,
            op.policy_version,
            op.monthly_ai_budget,
            op.currency_code,
            op.monthly_token_limit,
            op.storage_limit_bytes,
            op.retention_days,
            op.default_disclosure_scope,
            op.code_session_tier_code,
            op.allow_manager_invite,
            op.allow_data_export,
            op.allow_zip_submission,
            op.allow_github_integration,
            op.enable_big_project_contribution_analysis,
            op.effective_from,
            op.effective_to,
            op.status,
            op.created_by,
            op.created_at,
            op.updated_by,
            op.updated_at
           FROM public.organization_policy op
          WHERE (((op.status)::text = 'ACTIVE'::text) AND (op.effective_from <= CURRENT_TIMESTAMP) AND ((op.effective_to IS NULL) OR (op.effective_to > CURRENT_TIMESTAMP)))
          ORDER BY op.org_id, op.policy_version DESC, op.effective_from DESC
        ), latest_usage AS (
         SELECT DISTINCT ON (ous.org_id) ous.usage_snapshot_id,
            ous.org_id,
            ous.period_type,
            ous.period_start_at,
            ous.period_end_at,
            ous.as_of_at,
            ous.active_trainee_count,
            ous.completed_session_count,
            ous.grading_execution_count,
            ous.published_report_count,
            ous.ai_call_count,
            ous.input_token_count,
            ous.output_token_count,
            ous.cached_token_count,
            ous.unpriced_call_count,
            ous.unpriced_input_token_count,
            ous.unpriced_output_token_count,
            ous.cost_completeness_status,
            ous.estimated_cost,
            ous.actual_cost,
            ous.effective_cost,
            ous.currency_code,
            ous.aggregation_status,
            ous.failure_stage,
            ous.failure_code,
            ous.failure_reason,
            ous.failed_at,
            ous.is_retryable,
            ous.source_watermark,
            ous.calculation_version,
            ous.created_at
           FROM public.organization_usage_snapshot ous
          ORDER BY ous.org_id, ous.period_end_at DESC, ous.as_of_at DESC, ous.created_at DESC
        ), previous_usage AS (
         SELECT DISTINCT ON (cur.org_id) cur.org_id,
            prev.effective_cost
           FROM (latest_usage cur
             JOIN public.organization_usage_snapshot prev ON (((prev.org_id = cur.org_id) AND (prev.period_end_at <= cur.period_start_at))))
          ORDER BY cur.org_id, prev.period_end_at DESC, prev.as_of_at DESC
        ), org_base AS (
         SELECT o.org_id,
            COALESCE(lu.period_start_at, date_trunc('month'::text, CURRENT_TIMESTAMP)) AS period_start_at,
            COALESCE(lu.period_end_at, (date_trunc('month'::text, CURRENT_TIMESTAMP) + '1 mon'::interval)) AS period_end_at,
            COALESCE(lu.as_of_at, CURRENT_TIMESTAMP) AS as_of_at,
            COALESCE(lu.currency_code, cp.currency_code, 'USD'::character varying) AS currency_code,
            (COALESCE(lu.effective_cost, (0)::numeric))::numeric(18,6) AS organization_effective_cost,
            cp.monthly_ai_budget,
            pu.effective_cost AS previous_period_effective_cost,
            COALESCE(lu.aggregation_status, 'LIVE'::character varying) AS aggregation_status,
            ((lu.as_of_at IS NOT NULL) AND (lu.as_of_at < (CURRENT_TIMESTAMP - '24:00:00'::interval))) AS stale
           FROM (((public.organization o
             LEFT JOIN current_policy cp ON ((cp.org_id = o.org_id)))
             LEFT JOIN latest_usage lu ON ((lu.org_id = o.org_id)))
             LEFT JOIN previous_usage pu ON ((pu.org_id = o.org_id)))
          WHERE (o.deleted_at IS NULL)
        ), ai_current AS (
         SELECT au.org_id,
            au.cohort_id,
            au.class_id,
            (sum(COALESCE(au.actual_cost, au.estimated_cost, (0)::numeric)))::numeric(18,6) AS effective_cost,
            (sum(
                CASE
                    WHEN ((au.class_attribution_status)::text = 'ALLOCATED'::text) THEN COALESCE(au.actual_cost, au.estimated_cost, (0)::numeric)
                    ELSE (0)::numeric
                END))::numeric(18,6) AS allocated_class_cost,
            (sum(
                CASE
                    WHEN ((au.cohort_id IS NOT NULL) AND (au.class_id IS NULL)) THEN COALESCE(au.actual_cost, au.estimated_cost, (0)::numeric)
                    ELSE (0)::numeric
                END))::numeric(18,6) AS cohort_common_cost,
            (sum(
                CASE
                    WHEN ((au.class_attribution_status)::text = 'UNALLOCATED'::text) THEN COALESCE(au.actual_cost, au.estimated_cost, (0)::numeric)
                    ELSE (0)::numeric
                END))::numeric(18,6) AS class_unallocated_cost,
            max((au.class_attribution_status)::text) AS class_attribution_status,
            max((au.class_unallocated_reason_code)::text) AS class_unallocated_reason_code
           FROM public.ai_usage au
          WHERE ((au.occurred_at >= date_trunc('month'::text, CURRENT_TIMESTAMP)) AND (au.occurred_at < (date_trunc('month'::text, CURRENT_TIMESTAMP) + '1 mon'::interval)))
          GROUP BY au.org_id, au.cohort_id, au.class_id
        ), cohort_cost AS (
         SELECT ai_current.org_id,
            ai_current.cohort_id,
            sum(ai_current.effective_cost) AS effective_cost,
            sum(ai_current.cohort_common_cost) AS cohort_common_cost,
            sum(ai_current.class_unallocated_cost) AS class_unallocated_cost
           FROM ai_current
          WHERE (ai_current.cohort_id IS NOT NULL)
          GROUP BY ai_current.org_id, ai_current.cohort_id
        ), class_cost AS (
         SELECT ai_current.org_id,
            ai_current.cohort_id,
            ai_current.class_id,
            sum(ai_current.effective_cost) AS effective_cost,
            sum(ai_current.allocated_class_cost) AS allocated_class_cost,
            max(ai_current.class_attribution_status) AS class_attribution_status,
            max(ai_current.class_unallocated_reason_code) AS class_unallocated_reason_code
           FROM ai_current
          WHERE (ai_current.class_id IS NOT NULL)
          GROUP BY ai_current.org_id, ai_current.cohort_id, ai_current.class_id
        ), cohort_trainees AS (
         SELECT cohort_member.org_id,
            cohort_member.cohort_id,
            (count(DISTINCT cohort_member.user_id))::integer AS trainee_count
           FROM public.cohort_member
          WHERE (((cohort_member.status)::text = 'ACTIVE'::text) AND (cohort_member.left_at IS NULL))
          GROUP BY cohort_member.org_id, cohort_member.cohort_id
        ), class_trainees AS (
         SELECT cl.org_id,
            cl.cohort_id,
            cl.class_id,
            (count(DISTINCT cm.user_id))::integer AS trainee_count
           FROM ((public.class cl
             LEFT JOIN public.class_membership csm ON (((csm.class_id = cl.class_id) AND (csm.unassigned_at IS NULL))))
             LEFT JOIN public.cohort_member cm ON (((cm.cohort_member_id = csm.cohort_member_id) AND ((cm.status)::text = 'ACTIVE'::text) AND (cm.left_at IS NULL))))
          WHERE (cl.deleted_at IS NULL)
          GROUP BY cl.org_id, cl.cohort_id, cl.class_id
        ), class_managers AS (
         SELECT ma.org_id,
            ma.class_id,
            array_agg(DISTINCT u.name ORDER BY u.name) FILTER (WHERE (u.name IS NOT NULL)) AS manager_names
           FROM (public.manager_assignment ma
             JOIN public.app_user u ON ((u.user_id = ma.manager_user_id)))
          WHERE (((ma.status)::text = 'ACTIVE'::text) AND (ma.unassigned_at IS NULL) AND (u.deleted_at IS NULL))
          GROUP BY ma.org_id, ma.class_id
        ), class_sessions AS (
         SELECT pm.class_id,
            (count(DISTINCT s.session_id))::integer AS started_session_count
           FROM ((public.project_membership pm
             JOIN public.measurement_attempt ma ON (((ma.project_id = pm.project_id) AND (ma.user_id = pm.user_id))))
             JOIN public.assessment_session s ON (((s.attempt_id = ma.attempt_id) AND (s.started_at IS NOT NULL))))
          WHERE ((pm.status)::text = 'ACTIVE'::text)
          GROUP BY pm.class_id
        ), org_rows AS (
         SELECT ob.org_id,
            ob.period_start_at,
            ob.period_end_at,
            ob.as_of_at,
            ob.currency_code,
            ob.organization_effective_cost,
            ob.monthly_ai_budget,
            ob.previous_period_effective_cost,
            ob.aggregation_status,
            ob.stale,
            NULL::uuid AS cohort_id,
            NULL::character varying(200) AS cohort_name,
            NULL::numeric AS cohort_effective_cost,
            NULL::integer AS trainee_count,
            NULL::numeric AS cost_per_trainee,
            NULL::uuid AS class_id,
            NULL::character varying(200) AS class_name,
            ARRAY[]::text[] AS manager_names,
            NULL::integer AS class_trainee_count,
            NULL::integer AS started_session_count,
            NULL::numeric AS class_effective_cost,
            NULL::numeric AS allocated_class_cost,
            NULL::numeric AS cohort_common_cost,
            NULL::numeric AS class_unallocated_cost,
            NULL::character varying AS class_attribution_status,
            NULL::character varying AS class_unallocated_reason_code
           FROM org_base ob
        ), cohort_rows AS (
         SELECT ob.org_id,
            ob.period_start_at,
            ob.period_end_at,
            ob.as_of_at,
            ob.currency_code,
            ob.organization_effective_cost,
            ob.monthly_ai_budget,
            ob.previous_period_effective_cost,
            ob.aggregation_status,
            ob.stale,
            c.cohort_id,
            c.name AS cohort_name,
            COALESCE(cc.effective_cost, (0)::numeric) AS cohort_effective_cost,
            COALESCE(ct.trainee_count, 0) AS trainee_count,
                CASE
                    WHEN (COALESCE(ct.trainee_count, 0) = 0) THEN NULL::numeric
                    ELSE (COALESCE(cc.effective_cost, (0)::numeric) / (ct.trainee_count)::numeric)
                END AS cost_per_trainee,
            NULL::uuid AS class_id,
            NULL::character varying(200) AS class_name,
            ARRAY[]::text[] AS manager_names,
            NULL::integer AS class_trainee_count,
            NULL::integer AS started_session_count,
            NULL::numeric AS class_effective_cost,
            NULL::numeric AS allocated_class_cost,
            COALESCE(cc.cohort_common_cost, (0)::numeric) AS cohort_common_cost,
            COALESCE(cc.class_unallocated_cost, (0)::numeric) AS class_unallocated_cost,
            NULL::character varying AS class_attribution_status,
            NULL::character varying AS class_unallocated_reason_code
           FROM (((org_base ob
             JOIN public.cohort c ON (((c.org_id = ob.org_id) AND (c.deleted_at IS NULL))))
             LEFT JOIN cohort_cost cc ON (((cc.org_id = c.org_id) AND (cc.cohort_id = c.cohort_id))))
             LEFT JOIN cohort_trainees ct ON (((ct.org_id = c.org_id) AND (ct.cohort_id = c.cohort_id))))
        ), class_rows AS (
         SELECT ob.org_id,
            ob.period_start_at,
            ob.period_end_at,
            ob.as_of_at,
            ob.currency_code,
            ob.organization_effective_cost,
            ob.monthly_ai_budget,
            ob.previous_period_effective_cost,
            ob.aggregation_status,
            ob.stale,
            c.cohort_id,
            c.name AS cohort_name,
            COALESCE(cc.effective_cost, (0)::numeric) AS cohort_effective_cost,
            COALESCE(ct.trainee_count, 0) AS trainee_count,
                CASE
                    WHEN (COALESCE(ct.trainee_count, 0) = 0) THEN NULL::numeric
                    ELSE (COALESCE(cc.effective_cost, (0)::numeric) / (ct.trainee_count)::numeric)
                END AS cost_per_trainee,
            cl.class_id,
            cl.name AS class_name,
            COALESCE(cm.manager_names, (ARRAY[]::text[])::character varying[]) AS manager_names,
            COALESCE(clt.trainee_count, 0) AS class_trainee_count,
            COALESCE(cs.started_session_count, 0) AS started_session_count,
            COALESCE(clc.effective_cost, (0)::numeric) AS class_effective_cost,
            COALESCE(clc.allocated_class_cost, (0)::numeric) AS allocated_class_cost,
            COALESCE(cc.cohort_common_cost, (0)::numeric) AS cohort_common_cost,
            COALESCE(cc.class_unallocated_cost, (0)::numeric) AS class_unallocated_cost,
            COALESCE(clc.class_attribution_status, 'ALLOCATED'::text) AS class_attribution_status,
            clc.class_unallocated_reason_code
           FROM ((((((((org_base ob
             JOIN public.cohort c ON (((c.org_id = ob.org_id) AND (c.deleted_at IS NULL))))
             JOIN public.class cl ON (((cl.cohort_id = c.cohort_id) AND (cl.deleted_at IS NULL))))
             LEFT JOIN cohort_cost cc ON (((cc.org_id = c.org_id) AND (cc.cohort_id = c.cohort_id))))
             LEFT JOIN class_cost clc ON (((clc.org_id = cl.org_id) AND (clc.class_id = cl.class_id))))
             LEFT JOIN cohort_trainees ct ON (((ct.org_id = c.org_id) AND (ct.cohort_id = c.cohort_id))))
             LEFT JOIN class_trainees clt ON (((clt.org_id = cl.org_id) AND (clt.class_id = cl.class_id))))
             LEFT JOIN class_managers cm ON (((cm.org_id = cl.org_id) AND (cm.class_id = cl.class_id))))
             LEFT JOIN class_sessions cs ON ((cs.class_id = cl.class_id)))
        ), all_rows AS (
         SELECT org_rows.org_id,
            org_rows.period_start_at,
            org_rows.period_end_at,
            org_rows.as_of_at,
            org_rows.currency_code,
            org_rows.organization_effective_cost,
            org_rows.monthly_ai_budget,
            org_rows.previous_period_effective_cost,
            org_rows.aggregation_status,
            org_rows.stale,
            org_rows.cohort_id,
            org_rows.cohort_name,
            org_rows.cohort_effective_cost,
            org_rows.trainee_count,
            org_rows.cost_per_trainee,
            org_rows.class_id,
            org_rows.class_name,
            org_rows.manager_names,
            org_rows.class_trainee_count,
            org_rows.started_session_count,
            org_rows.class_effective_cost,
            org_rows.allocated_class_cost,
            org_rows.cohort_common_cost,
            org_rows.class_unallocated_cost,
            org_rows.class_attribution_status,
            org_rows.class_unallocated_reason_code
           FROM org_rows
        UNION ALL
         SELECT cohort_rows.org_id,
            cohort_rows.period_start_at,
            cohort_rows.period_end_at,
            cohort_rows.as_of_at,
            cohort_rows.currency_code,
            cohort_rows.organization_effective_cost,
            cohort_rows.monthly_ai_budget,
            cohort_rows.previous_period_effective_cost,
            cohort_rows.aggregation_status,
            cohort_rows.stale,
            cohort_rows.cohort_id,
            cohort_rows.cohort_name,
            cohort_rows.cohort_effective_cost,
            cohort_rows.trainee_count,
            cohort_rows.cost_per_trainee,
            cohort_rows.class_id,
            cohort_rows.class_name,
            cohort_rows.manager_names,
            cohort_rows.class_trainee_count,
            cohort_rows.started_session_count,
            cohort_rows.class_effective_cost,
            cohort_rows.allocated_class_cost,
            cohort_rows.cohort_common_cost,
            cohort_rows.class_unallocated_cost,
            cohort_rows.class_attribution_status,
            cohort_rows.class_unallocated_reason_code
           FROM cohort_rows
        UNION ALL
         SELECT class_rows.org_id,
            class_rows.period_start_at,
            class_rows.period_end_at,
            class_rows.as_of_at,
            class_rows.currency_code,
            class_rows.organization_effective_cost,
            class_rows.monthly_ai_budget,
            class_rows.previous_period_effective_cost,
            class_rows.aggregation_status,
            class_rows.stale,
            class_rows.cohort_id,
            class_rows.cohort_name,
            class_rows.cohort_effective_cost,
            class_rows.trainee_count,
            class_rows.cost_per_trainee,
            class_rows.class_id,
            class_rows.class_name,
            class_rows.manager_names,
            class_rows.class_trainee_count,
            class_rows.started_session_count,
            class_rows.class_effective_cost,
            class_rows.allocated_class_cost,
            class_rows.cohort_common_cost,
            class_rows.class_unallocated_cost,
            class_rows.class_attribution_status,
            class_rows.class_unallocated_reason_code
           FROM class_rows
        )
 SELECT org_id,
    period_start_at,
    period_end_at,
    as_of_at,
    (currency_code)::character varying(3) AS currency_code,
    organization_effective_cost,
    monthly_ai_budget,
    (
        CASE
            WHEN ((monthly_ai_budget IS NULL) OR (monthly_ai_budget = (0)::numeric)) THEN NULL::numeric
            ELSE (organization_effective_cost / monthly_ai_budget)
        END)::numeric(9,4) AS budget_utilization_rate,
    (
        CASE
            WHEN (monthly_ai_budget IS NULL) THEN NULL::numeric
            ELSE (monthly_ai_budget - organization_effective_cost)
        END)::numeric(18,6) AS budget_remaining,
    (
        CASE
            WHEN (monthly_ai_budget IS NULL) THEN 'NOT_CONFIGURED'::text
            WHEN (organization_effective_cost > monthly_ai_budget) THEN 'EXCEEDED'::text
            WHEN (organization_effective_cost >= (monthly_ai_budget * 0.8)) THEN 'WARNING'::text
            ELSE 'NORMAL'::text
        END)::character varying(30) AS budget_status,
    previous_period_effective_cost,
    (
        CASE
            WHEN ((previous_period_effective_cost IS NULL) OR (previous_period_effective_cost = (0)::numeric)) THEN NULL::numeric
            ELSE ((organization_effective_cost - previous_period_effective_cost) / previous_period_effective_cost)
        END)::numeric(9,4) AS cost_change_rate,
    (
        CASE
            WHEN (previous_period_effective_cost IS NULL) THEN 'NO_BASELINE'::text
            WHEN (previous_period_effective_cost = (0)::numeric) THEN 'ZERO_BASELINE'::text
            ELSE 'COMPARABLE'::text
        END)::character varying(30) AS comparison_status,
    (aggregation_status)::character varying(20) AS aggregation_status,
    stale,
    cohort_id,
    cohort_name,
    (cohort_effective_cost)::numeric(18,6) AS cohort_effective_cost,
    trainee_count,
    (cost_per_trainee)::numeric(18,6) AS cost_per_trainee,
    class_id,
    class_name,
    manager_names,
    class_trainee_count,
    started_session_count,
    (class_effective_cost)::numeric(18,6) AS class_effective_cost,
    (allocated_class_cost)::numeric(18,6) AS allocated_class_cost,
    (cohort_common_cost)::numeric(18,6) AS cohort_common_cost,
    (class_unallocated_cost)::numeric(18,6) AS class_unallocated_cost,
    (class_attribution_status)::character varying(30) AS class_attribution_status,
    (class_unallocated_reason_code)::character varying(100) AS class_unallocated_reason_code
   FROM all_rows;


--
-- Name: operator_curriculum_concept_distribution_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operator_curriculum_concept_distribution_view AS
 SELECT rm.snapshot_id,
    rm.curriculum_version_id,
    rm.teaches_id,
    rm.reached_level,
    (COALESCE((rm.dimension_snapshot ->> 'conceptName'::text), (t.canonical_name)::text))::character varying(200) AS concept_name_snapshot,
    (COALESCE(rm.numerator, rm.metric_value, (0)::numeric))::integer AS participant_count,
    rm.denominator,
    (
        CASE
            WHEN (rm.reached_level = ANY (ARRAY[0, 1, 2])) THEN COALESCE(rm.numerator, rm.metric_value, (0)::numeric)
            ELSE (0)::numeric
        END)::integer AS low_level_count,
    rm.aggregation_status,
    rm.aggregation_policy_version,
    rm.policy_parameter_snapshot
   FROM (public.report_metric rm
     LEFT JOIN public.teaches t ON ((t.teaches_id = rm.teaches_id)))
  WHERE (((rm.section_code)::text = 'CONCEPT_REACH_DISTRIBUTION'::text) AND ((rm.metric_grain_code)::text = 'CONCEPT_REACHED_LEVEL'::text));


--
-- Name: operator_curriculum_diagnosis_round_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operator_curriculum_diagnosis_round_view AS
 SELECT rm.snapshot_id,
    rm.source_assessment_round_id,
    rm.project_verification_concept_id,
    rm.project_id,
    rm.source_assessment_round_id AS round_id,
    r.round_name,
    rm.project_verification_concept_id AS concept_id,
    (COALESCE((rm.dimension_snapshot ->> 'conceptName'::text), (t.canonical_name)::text))::character varying(200) AS concept_name_snapshot,
    rm.reached_level,
    (COALESCE(rm.numerator, rm.metric_value, (0)::numeric))::integer AS participant_count,
    rm.denominator,
    rm.missing_count,
    rm.source_snapshot_version
   FROM (((public.report_metric rm
     LEFT JOIN public.project_assessment_round r ON ((r.assessment_round_id = rm.source_assessment_round_id)))
     LEFT JOIN public.project_verification_concept pvc ON ((pvc.project_concept_id = rm.project_verification_concept_id)))
     LEFT JOIN public.teaches t ON ((t.teaches_id = pvc.teaches_id)))
  WHERE (((rm.section_code)::text = 'ROUND_CONCEPT_RESULT'::text) AND ((rm.metric_grain_code)::text = ANY ((ARRAY['ROUND_CONCEPT'::character varying, 'ROUND_CONCEPT_REACHED_LEVEL'::character varying])::text[])));


--
-- Name: operator_curriculum_diagnosis_summary_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operator_curriculum_diagnosis_summary_view AS
 SELECT rs.snapshot_id,
    rm.curriculum_version_id,
    rpt.org_id,
    rpt.cohort_id,
    rpt.report_id,
    cv.material_id,
    cv.version_id,
    (COALESCE((rm.dimension_snapshot ->> 'curriculumName'::text), (cm.title)::text))::character varying(200) AS curriculum_name_snapshot,
    COALESCE(((rs.summary_payload ->> 'eligibleCount'::text))::integer, (rs.sample_count + rs.missing_count)) AS eligible_count,
    COALESCE(((rs.summary_payload ->> 'assessedCount'::text))::integer, rs.sample_count) AS assessed_count,
    rs.missing_count,
    (avg(rm.metric_value) OVER (PARTITION BY rs.snapshot_id, rm.curriculum_version_id))::numeric(10,4) AS average_reached_level,
    (
        CASE
            WHEN ((rs.completion_status)::text = 'FULL'::text) THEN 'COMPLETE'::text
            ELSE 'PARTIAL'::text
        END)::character varying(20) AS aggregation_status,
    min(rm.display_order) OVER (PARTITION BY rs.snapshot_id, rm.curriculum_version_id) AS display_order
   FROM ((((public.report rpt
     JOIN public.report_snapshot rs ON (((rs.report_id = rpt.report_id) AND rs.is_active)))
     JOIN public.report_metric rm ON (((rm.snapshot_id = rs.snapshot_id) AND ((rm.section_code)::text = 'CURRICULUM_DIAGNOSIS_SUMMARY'::text))))
     LEFT JOIN public.curriculum_version cv ON ((cv.version_id = rm.curriculum_version_id)))
     LEFT JOIN public.curriculum_material cm ON ((cm.material_id = cv.material_id)))
  WHERE ((rpt.report_type)::text = 'COHORT_CURRICULUM_DIAGNOSIS'::text);


--
-- Name: operator_curriculum_list_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operator_curriculum_list_view AS
 SELECT m.org_id,
    m.material_id,
    m.title,
    m.normalized_title,
    m.topic,
    m.material_type,
    m.created_at AS registered_at,
    m.deleted_at,
    v.version_id AS latest_version_id,
    v.version_no AS latest_version_no,
    (v.status)::character varying(100) AS latest_version_status,
    v.original_file_name,
    v.file_size_bytes,
    v.page_count,
    la.analysis_id AS latest_analysis_attempt_id,
    (la.status)::character varying(100) AS latest_analysis_attempt_status,
    la.requested_at AS latest_analysis_requested_at,
    la.failure_code AS latest_failure_code,
    (la.failure_stage)::text AS latest_failure_stage,
    (la.recovery_action)::text AS latest_recovery_action,
    ea.analysis_id AS effective_analysis_id,
    ea.analysis_version AS effective_analysis_version,
    ea.completed_at AS effective_analysis_completed_at,
    ea.fallback_used,
    (
        CASE
            WHEN (la.analysis_id IS NULL) THEN 'NOT_ANALYZED'::character varying
            WHEN (((la.status)::text = 'FAILED'::text) AND (ea.analysis_id IS NOT NULL)) THEN 'FAILED_USING_PREVIOUS'::character varying
            ELSE la.status
        END)::character varying(50) AS display_analysis_status,
    (
        CASE
            WHEN (ea.analysis_id IS NULL) THEN 'UNAVAILABLE'::text
            WHEN ea.fallback_used THEN 'FALLBACK'::text
            ELSE 'NORMAL'::text
        END)::character varying(100) AS analysis_quality_status,
    COALESCE(stats.section_count, 0) AS section_count,
    COALESCE(stats.teaching_item_count, 0) AS teaching_item_count,
    COALESCE(stats.distinct_teaches_count, 0) AS distinct_teaches_count,
    COALESCE(proj.linked_project_count, 0) AS linked_project_count,
    (COALESCE(proj.names, (ARRAY[]::text[])::character varying[]))::text[] AS linked_project_names,
    COALESCE(proj.items, '[]'::jsonb) AS linked_projects,
    'COMPLETE'::character varying(20) AS aggregation_status,
    CURRENT_TIMESTAMP AS as_of_at
   FROM (((((public.curriculum_material m
     LEFT JOIN LATERAL ( SELECT x.version_id,
            x.material_id,
            x.version_no,
            x.original_file_name,
            x.file_uri,
            x.mime_type,
            x.file_size_bytes,
            x.content_hash,
            x.page_count,
            x.status,
            x.created_by,
            x.created_at
           FROM public.curriculum_version x
          WHERE (x.material_id = m.material_id)
          ORDER BY x.version_no DESC, x.created_at DESC
         LIMIT 1) v ON (true))
     LEFT JOIN LATERAL ( SELECT x.analysis_id,
            x.version_id,
            x.model_id,
            x.retry_of_analysis_id,
            x.analysis_version,
            x.status,
            x.fallback_used,
            x.idempotency_key,
            x.request_fingerprint,
            x.request_reason,
            x.impact_acknowledged,
            x.requested_by,
            x.requested_at,
            x.started_at,
            x.completed_at,
            x.failed_at,
            x.failure_code,
            x.failure_stage,
            x.failure_reason,
            x.is_retryable,
            x.recovery_action,
            x.created_at,
            x.external_job_id
           FROM public.curriculum_analysis x
          WHERE (x.version_id = v.version_id)
          ORDER BY x.requested_at DESC, x.created_at DESC
         LIMIT 1) la ON (true))
     LEFT JOIN LATERAL ( SELECT x.analysis_id,
            x.version_id,
            x.model_id,
            x.retry_of_analysis_id,
            x.analysis_version,
            x.status,
            x.fallback_used,
            x.idempotency_key,
            x.request_fingerprint,
            x.request_reason,
            x.impact_acknowledged,
            x.requested_by,
            x.requested_at,
            x.started_at,
            x.completed_at,
            x.failed_at,
            x.failure_code,
            x.failure_stage,
            x.failure_reason,
            x.is_retryable,
            x.recovery_action,
            x.created_at,
            x.external_job_id
           FROM public.curriculum_analysis x
          WHERE ((x.version_id = v.version_id) AND ((x.status)::text = 'SUCCEEDED'::text))
          ORDER BY x.completed_at DESC, x.analysis_version DESC
         LIMIT 1) ea ON (true))
     LEFT JOIN LATERAL ( SELECT (count(DISTINCT s.section_id))::integer AS section_count,
            (count(map.mapping_id))::integer AS teaching_item_count,
            (count(DISTINCT map.teaches_id))::integer AS distinct_teaches_count
           FROM (public.curriculum_section s
             LEFT JOIN public.curriculum_teaches_mapping map ON (((map.source_analysis_id = s.source_analysis_id) AND (map.version_id = s.version_id))))
          WHERE ((s.version_id = v.version_id) AND (s.source_analysis_id = ea.analysis_id))) stats ON (true))
     LEFT JOIN LATERAL ( SELECT (count(DISTINCT p.project_id))::integer AS linked_project_count,
            array_agg(DISTINCT p.name ORDER BY p.name) AS names,
            jsonb_agg(DISTINCT jsonb_build_object('projectId', p.project_id, 'projectName', p.name, 'cohortId', p.cohort_id, 'status', p.lifecycle_status)) AS items
           FROM (public.project_curriculum pc
             JOIN public.project p ON ((p.project_id = pc.project_id)))
          WHERE ((pc.curriculum_version_id = v.version_id) AND (p.deleted_at IS NULL))) proj ON (true));


--
-- Name: operator_manager_list_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operator_manager_list_view AS
 WITH account_stats AS (
         SELECT u.org_id,
            (count(*))::integer AS account_count,
            ( SELECT (count(*))::integer AS count
                   FROM public.user_invitation ui
                  WHERE ((ui.org_id = u.org_id) AND ((ui.target_role_code)::text = 'MANAGER'::text) AND ((ui.status)::text = ANY ((ARRAY['PENDING'::character varying, 'SENT'::character varying, 'FAILED'::character varying])::text[])) AND (ui.accepted_at IS NULL) AND (ui.cancelled_at IS NULL))) AS pending_invitation_count
           FROM public.app_user u
          WHERE (((u.role_code)::text = 'MANAGER'::text) AND (u.deleted_at IS NULL))
          GROUP BY u.org_id
        ), assignment_summary AS (
         SELECT ma.manager_user_id,
            (count(*) FILTER (WHERE (((ma.status)::text = 'ACTIVE'::text) AND (ma.unassigned_at IS NULL))))::integer AS active_assignment_count,
            array_agg(DISTINCT c.cohort_id) FILTER (WHERE (((ma.status)::text = 'ACTIVE'::text) AND (ma.unassigned_at IS NULL))) AS assigned_cohort_ids,
            array_agg(DISTINCT ma.class_id) FILTER (WHERE (((ma.status)::text = 'ACTIVE'::text) AND (ma.unassigned_at IS NULL))) AS assigned_class_ids,
            array_agg(DISTINCT co.name ORDER BY co.name) FILTER (WHERE (((ma.status)::text = 'ACTIVE'::text) AND (ma.unassigned_at IS NULL))) AS assigned_cohort_names,
            array_agg(DISTINCT c.name ORDER BY c.name) FILTER (WHERE (((ma.status)::text = 'ACTIVE'::text) AND (ma.unassigned_at IS NULL))) AS assigned_class_names,
            (count(DISTINCT cm.user_id) FILTER (WHERE (((ma.status)::text = 'ACTIVE'::text) AND (ma.unassigned_at IS NULL) AND ((cm.status)::text = 'ACTIVE'::text) AND (cm.left_at IS NULL))))::integer AS assigned_trainee_count
           FROM ((((public.manager_assignment ma
             JOIN public.class c ON ((c.class_id = ma.class_id)))
             JOIN public.cohort co ON ((co.cohort_id = c.cohort_id)))
             LEFT JOIN public.class_membership csm ON (((csm.class_id = c.class_id) AND (csm.unassigned_at IS NULL))))
             LEFT JOIN public.cohort_member cm ON ((cm.cohort_member_id = csm.cohort_member_id)))
          GROUP BY ma.manager_user_id
        ), accounts AS (
         SELECT u.org_id,
            'ACCOUNT'::character varying(20) AS row_type,
            (u.name)::text AS name,
            (u.email)::text AS email,
            (u.status)::text AS display_status,
            COALESCE(u.updated_at, u.created_at) AS source_status_at,
            COALESCE(u.last_login_at, u.created_at) AS sort_at,
            u.user_id,
            (u.status)::text AS status,
            u.is_email_verified,
            u.last_login_at,
            u.inactivated_at,
            (u.inactivated_reason_code)::text AS inactivated_reason_code,
            NULL::uuid AS invitation_id,
            NULL::uuid AS target_cohort_id,
            NULL::uuid AS target_class_id,
            NULL::timestamp with time zone AS invited_at,
            NULL::timestamp with time zone AS sent_at,
            NULL::timestamp with time zone AS accepted_at,
            NULL::timestamp with time zone AS expired_at,
            NULL::text AS failure_stage,
            NULL::text AS failure_code,
            NULL::uuid AS current_token_id,
            NULL::text AS purpose,
            NULL::timestamp with time zone AS expires_at,
            NULL::timestamp with time zone AS used_at,
            NULL::text AS invalidated_reason,
            COALESCE(a.active_assignment_count, 0) AS active_assignment_count,
            COALESCE(a.assigned_cohort_ids, ARRAY[]::uuid[]) AS assigned_cohort_ids,
            COALESCE(a.assigned_class_ids, ARRAY[]::uuid[]) AS assigned_class_ids,
            COALESCE(a.assigned_cohort_names, (ARRAY[]::text[])::character varying[]) AS assigned_cohort_names,
            COALESCE(a.assigned_class_names, (ARRAY[]::text[])::character varying[]) AS assigned_class_names,
            COALESCE(a.assigned_trainee_count, 0) AS assigned_trainee_count,
            (COALESCE(a.active_assignment_count, 0) = 0) AS is_unassigned,
            ((u.status)::text = 'ACTIVE'::text) AS can_suspend,
            ((u.status)::text = 'INACTIVE'::text) AS can_reactivate,
            false AS can_resend,
            false AS can_cancel,
            NULL::text AS action_block_code,
            COALESCE(s.account_count, 0) AS account_count,
            COALESCE(s.pending_invitation_count, 0) AS pending_invitation_count,
            'COMPLETE'::text AS aggregation_status,
            CURRENT_TIMESTAMP AS as_of_at
           FROM ((public.app_user u
             LEFT JOIN assignment_summary a ON ((a.manager_user_id = u.user_id)))
             LEFT JOIN account_stats s ON ((s.org_id = u.org_id)))
          WHERE (((u.role_code)::text = 'MANAGER'::text) AND (u.deleted_at IS NULL))
        ), invites AS (
         SELECT ui.org_id,
            'INVITATION'::character varying(20) AS "varchar",
            NULL::text AS text,
            (ui.target_email)::text AS target_email,
            (ui.status)::text AS status,
            COALESCE(ui.updated_at, ui.invited_at) AS "coalesce",
            COALESCE(ui.sent_at, ui.invited_at) AS "coalesce",
            NULL::uuid AS uuid,
            NULL::text AS text,
            NULL::boolean AS bool,
            NULL::timestamp with time zone AS timestamptz,
            NULL::timestamp with time zone AS timestamptz,
            NULL::text AS text,
            ui.invitation_id,
            ui.target_cohort_id,
            ui.target_class_id,
            ui.invited_at,
            ui.sent_at,
            ui.accepted_at,
            ui.expired_at,
            (ui.failure_stage)::text AS failure_stage,
            (ui.failure_code)::text AS failure_code,
            t.token_id,
            (t.purpose)::text AS purpose,
            t.expires_at,
            t.used_at,
            t.invalidated_reason,
            0 AS "?column?",
            ARRAY[]::uuid[] AS "array",
            ARRAY[]::uuid[] AS "array",
            ARRAY[]::text[] AS "array",
            ARRAY[]::text[] AS "array",
            0 AS "?column?",
            true AS "?column?",
            false AS "?column?",
            false AS "?column?",
            (((ui.status)::text = ANY ((ARRAY['PENDING'::character varying, 'SENT'::character varying, 'FAILED'::character varying])::text[])) AND (ui.accepted_at IS NULL) AND (ui.cancelled_at IS NULL)) AS "?column?",
            ((ui.accepted_at IS NULL) AND (ui.cancelled_at IS NULL)) AS "?column?",
                CASE
                    WHEN (ui.accepted_at IS NOT NULL) THEN 'ALREADY_ACCEPTED'::text
                    WHEN (ui.cancelled_at IS NOT NULL) THEN 'CANCELLED'::text
                    ELSE NULL::text
                END AS "case",
            COALESCE(s.account_count, 0) AS "coalesce",
            COALESCE(s.pending_invitation_count, 0) AS "coalesce",
            'COMPLETE'::text AS "?column?",
            CURRENT_TIMESTAMP AS "current_timestamp"
           FROM ((public.user_invitation ui
             LEFT JOIN LATERAL ( SELECT x.token_id,
                    x.org_id,
                    x.user_id,
                    x.invitation_id,
                    x.target_email,
                    x.target_email_normalized,
                    x.purpose,
                    x.token_hash,
                    x.payload,
                    x.issued_at,
                    x.expires_at,
                    x.used_at,
                    x.invalidated_at,
                    x.invalidated_reason,
                    x.replaced_by_token_id,
                    x.issued_by,
                    x.issued_request_id,
                    x.used_request_id,
                    x.created_at
                   FROM public.one_time_token x
                  WHERE ((x.token_id = ui.current_token_id) OR ((x.invitation_id = ui.invitation_id) AND (x.replaced_by_token_id IS NULL)))
                  ORDER BY (x.token_id = ui.current_token_id) DESC, x.issued_at DESC
                 LIMIT 1) t ON (true))
             LEFT JOIN account_stats s ON ((s.org_id = ui.org_id)))
          WHERE (((ui.target_role_code)::text = 'MANAGER'::text) AND (ui.accepted_at IS NULL))
        ), z AS (
         SELECT accounts.org_id,
            accounts.row_type,
            accounts.name,
            accounts.email,
            accounts.display_status,
            accounts.source_status_at,
            accounts.sort_at,
            accounts.user_id,
            accounts.status,
            accounts.is_email_verified,
            accounts.last_login_at,
            accounts.inactivated_at,
            accounts.inactivated_reason_code,
            accounts.invitation_id,
            accounts.target_cohort_id,
            accounts.target_class_id,
            accounts.invited_at,
            accounts.sent_at,
            accounts.accepted_at,
            accounts.expired_at,
            accounts.failure_stage,
            accounts.failure_code,
            accounts.current_token_id,
            accounts.purpose,
            accounts.expires_at,
            accounts.used_at,
            accounts.invalidated_reason,
            accounts.active_assignment_count,
            accounts.assigned_cohort_ids,
            accounts.assigned_class_ids,
            accounts.assigned_cohort_names,
            accounts.assigned_class_names,
            accounts.assigned_trainee_count,
            accounts.is_unassigned,
            accounts.can_suspend,
            accounts.can_reactivate,
            accounts.can_resend,
            accounts.can_cancel,
            accounts.action_block_code,
            accounts.account_count,
            accounts.pending_invitation_count,
            accounts.aggregation_status,
            accounts.as_of_at
           FROM accounts
        UNION ALL
         SELECT invites.org_id,
            invites."varchar",
            invites.text,
            invites.target_email,
            invites.status,
            invites."coalesce",
            invites.coalesce_1 AS "coalesce",
            invites.uuid,
            invites.text_1 AS text,
            invites.bool,
            invites.timestamptz,
            invites.timestamptz_1 AS timestamptz,
            invites.text_2 AS text,
            invites.invitation_id,
            invites.target_cohort_id,
            invites.target_class_id,
            invites.invited_at,
            invites.sent_at,
            invites.accepted_at,
            invites.expired_at,
            invites.failure_stage,
            invites.failure_code,
            invites.token_id,
            invites.purpose,
            invites.expires_at,
            invites.used_at,
            invites.invalidated_reason,
            invites."?column?",
            invites."array",
            invites.array_1 AS "array",
            invites.array_2 AS "array",
            invites.array_3 AS "array",
            invites."?column?_1" AS "?column?",
            invites."?column?_2" AS "?column?",
            invites."?column?_3" AS "?column?",
            invites."?column?_4" AS "?column?",
            invites."?column?_5" AS "?column?",
            invites."?column?_6" AS "?column?",
            invites."case",
            invites.coalesce_2 AS "coalesce",
            invites.coalesce_3 AS "coalesce",
            invites."?column?_7" AS "?column?",
            invites."current_timestamp"
           FROM invites invites(org_id, "varchar", text, target_email, status, "coalesce", coalesce_1, uuid, text_1, bool, timestamptz, timestamptz_1, text_2, invitation_id, target_cohort_id, target_class_id, invited_at, sent_at, accepted_at, expired_at, failure_stage, failure_code, token_id, purpose, expires_at, used_at, invalidated_reason, "?column?", "array", array_1, array_2, array_3, "?column?_1", "?column?_2", "?column?_3", "?column?_4", "?column?_5", "?column?_6", "case", coalesce_2, coalesce_3, "?column?_7", "current_timestamp")
        )
 SELECT org_id,
    row_type,
    (name)::character varying(200) AS name,
    (email)::character varying(320) AS email,
    (display_status)::character varying(30) AS display_status,
    source_status_at,
    sort_at,
    user_id,
    (status)::character varying(30) AS status,
    is_email_verified,
    last_login_at,
    inactivated_at,
    (inactivated_reason_code)::character varying(30) AS inactivated_reason_code,
    invitation_id,
    target_cohort_id,
    target_class_id,
    invited_at,
    sent_at,
    accepted_at,
    expired_at,
    (failure_stage)::character varying(100) AS failure_stage,
    (failure_code)::character varying(100) AS failure_code,
    current_token_id,
    (purpose)::character varying(100) AS purpose,
    expires_at,
    used_at,
    invalidated_reason,
    active_assignment_count,
    assigned_cohort_ids,
    assigned_class_ids,
    (assigned_cohort_names)::text[] AS assigned_cohort_names,
    (assigned_class_names)::text[] AS assigned_class_names,
    assigned_trainee_count,
    is_unassigned,
    can_suspend,
    can_reactivate,
    can_resend,
    can_cancel,
    (action_block_code)::character varying(100) AS action_block_code,
    account_count,
    pending_invitation_count,
    (aggregation_status)::character varying(20) AS aggregation_status,
    as_of_at
   FROM z;


--
-- Name: operator_project_concept_candidate_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operator_project_concept_candidate_view AS
 SELECT p.org_id,
    p.project_id,
    v.material_id,
    v.version_id,
    m.source_analysis_id AS effective_analysis_id,
    m.section_id,
    (((m.page_start)::text || '-'::text) || (m.page_end)::text) AS page_range,
    m.mapping_id,
    m.teaches_id,
    m.extracted_name,
    m.source_description,
    (
        CASE
            WHEN ((m.source_description IS NULL) OR (btrim(m.source_description) = ''::text)) THEN 'MISSING'::text
            ELSE 'AVAILABLE'::text
        END)::character varying(30) AS description_status,
    COALESCE(hist.usage_count, 0) AS usage_count,
    hist.latest_project_id,
    (hist.latest_project_name)::character varying(200) AS latest_project_name,
    hist.latest_project_sequence_no,
    hist.latest_analysis_sequence_no,
    hist.average_reached_stage,
    COALESCE(hist.underperforming_class_count, 0) AS underperforming_class_count,
    COALESCE(hist.evaluated_trainee_count, 0) AS evaluated_trainee_count,
    (
        CASE
            WHEN (COALESCE(hist.evaluated_trainee_count, 0) = 0) THEN 'NO_RESULT'::text
            ELSE 'AVAILABLE'::text
        END)::character varying(100) AS result_coverage_status,
    COALESCE(hist.matched_team_count, 0) AS matched_team_count,
    COALESCE(hist.all_unmatched_team_count, 0) AS all_unmatched_team_count,
    COALESCE(hist.evidence_warning_codes, ARRAY[]::text[]) AS evidence_warning_codes,
    (((m.mapping_status)::text = 'ACTIVE'::text) AND ((t.status)::text = 'ACTIVE'::text)) AS selectable,
    (
        CASE
            WHEN ((m.mapping_status)::text <> 'ACTIVE'::text) THEN 'MAPPING_INACTIVE'::text
            WHEN ((t.status)::text <> 'ACTIVE'::text) THEN 'TEACHES_INACTIVE'::text
            ELSE NULL::text
        END)::character varying(100) AS unavailable_reason_code,
    (m.mapping_status)::character varying(100) AS source_mapping_status,
    'COMPLETE'::character varying(20) AS aggregation_status,
    CURRENT_TIMESTAMP AS as_of_at
   FROM (((((public.project p
     JOIN public.project_curriculum pc ON ((pc.project_id = p.project_id)))
     JOIN public.curriculum_version v ON ((v.version_id = pc.curriculum_version_id)))
     JOIN public.curriculum_teaches_mapping m ON ((m.version_id = v.version_id)))
     JOIN public.teaches t ON ((t.teaches_id = m.teaches_id)))
     LEFT JOIN LATERAL ( SELECT (count(DISTINCT pvc.project_concept_id))::integer AS usage_count,
            (array_agg(ph.project_id ORDER BY ph.sequence_no DESC))[1] AS latest_project_id,
            (array_agg(ph.name ORDER BY ph.sequence_no DESC))[1] AS latest_project_name,
            max(ph.sequence_no) AS latest_project_sequence_no,
            max(( SELECT s.analysis_sequence_no
                   FROM public.mini_project_round_sequence_view s
                  WHERE (s.assessment_round_id = r.assessment_round_id))) AS latest_analysis_sequence_no,
            (round(avg(
                CASE ap.best_success_stage
                    WHEN 'L4'::text THEN 4
                    WHEN 'L3'::text THEN 3
                    WHEN 'L2'::text THEN 2
                    WHEN 'L1'::text THEN 1
                    ELSE 0
                END), 2))::text AS average_reached_stage,
            0 AS underperforming_class_count,
            (count(DISTINCT ma.user_id))::integer AS evaluated_trainee_count,
            (count(DISTINCT ca.team_id))::integer AS matched_team_count,
            (count(DISTINCT ca.team_id) FILTER (WHERE ((ap.generation_status)::text = 'NOT_GENERATED'::text)))::integer AS all_unmatched_team_count,
            array_remove(ARRAY[
                CASE
                    WHEN (count(*) FILTER (WHERE (((ap.generation_status)::text = 'NOT_GENERATED'::text) AND ((ap.not_generated_reason_code)::text = 'NO_MATCHING_CODE_EVIDENCE'::text))) > 0) THEN 'NO_MATCHING_CODE_EVIDENCE'::text
                    ELSE NULL::text
                END], NULL::text) AS evidence_warning_codes
           FROM ((((((public.project_verification_concept pvc
             JOIN public.project_verification_concept_set pcs ON ((pcs.concept_set_id = pvc.concept_set_id)))
             JOIN public.project ph ON (((ph.project_id = pcs.project_id) AND (ph.org_id = p.org_id))))
             LEFT JOIN public.project_assessment_round r ON ((r.project_id = ph.project_id)))
             LEFT JOIN public.assessment_problem ap ON ((ap.project_verification_concept_id = pvc.project_concept_id)))
             LEFT JOIN public.code_analysis ca ON ((ca.analysis_id = ap.code_analysis_id)))
             LEFT JOIN public.measurement_attempt ma ON ((ma.code_analysis_id = ca.analysis_id)))
          WHERE ((pvc.teaches_id = m.teaches_id) AND (ph.project_id <> p.project_id))) hist ON (true))
  WHERE (p.deleted_at IS NULL);


--
-- Name: operator_project_detail_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operator_project_detail_view AS
 SELECT p.org_id,
    p.cohort_id,
    p.project_id,
    p.sequence_no,
    p.name,
    (p.project_category)::character varying(100) AS category,
    p.lifecycle_status,
    p.start_date,
    p.end_date,
    COALESCE(cur.version_ids, ARRAY[]::uuid[]) AS curriculum_version_ids,
    cs.concept_set_id AS active_concept_set_id,
    cs.version_no AS concept_set_version,
    COALESCE(concepts.items, '[]'::jsonb) AS verification_concepts,
    COALESCE(req.items, '[]'::jsonb) AS requirements,
    COALESCE(rounds.active_count, 0) AS active_round_count,
    COALESCE(rounds.items, '[]'::jsonb) AS rounds,
    rounds.display_round_id,
    rounds.submission_due_at,
    'ROUND_COMMON_WINDOW'::character varying(30) AS assessment_window_mode,
    NULL::integer AS assessment_window_hours,
    NULL::integer AS time_limit_sec,
    'ADVISORY'::character varying(100) AS time_enforcement_mode,
    'NOT_CONFIGURED'::character varying(100) AS policy_time_limit_status,
    ((p.lifecycle_status)::text <> 'CLOSED'::text) AS can_access_schedule,
    true AS can_access_status,
    array_remove(ARRAY[
        CASE
            WHEN ((NOT p.curriculum_not_applicable) AND (COALESCE(cardinality(cur.version_ids), 0) = 0)) THEN 'CURRICULUM_REQUIRED'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (COALESCE(concepts.concept_count, 0) <> 3) THEN 'THREE_CONCEPTS_REQUIRED'::text
            ELSE NULL::text
        END], NULL::text) AS tab_lock_reason_codes,
    (rounds.report_publish_mode)::character varying(100) AS report_publish_mode,
    rounds.report_publish_not_before_at,
    rounds.assessment_open_at AS round_assessment_open_at,
    rounds.assessment_due_at AS round_assessment_due_at
   FROM (((((public.project p
     LEFT JOIN LATERAL ( SELECT array_agg(pc.curriculum_version_id ORDER BY pc.sequence_no) AS version_ids
           FROM public.project_curriculum pc
          WHERE (pc.project_id = p.project_id)) cur ON (true))
     LEFT JOIN LATERAL ( SELECT x.concept_set_id,
            x.project_id,
            x.org_id,
            x.version_no,
            x.status,
            x.effective_from,
            x.effective_to,
            x.created_by,
            x.change_reason,
            x.created_at
           FROM public.project_verification_concept_set x
          WHERE ((x.project_id = p.project_id) AND ((x.status)::text = 'ACTIVE'::text) AND (x.effective_from <= CURRENT_TIMESTAMP) AND ((x.effective_to IS NULL) OR (x.effective_to > CURRENT_TIMESTAMP)))
          ORDER BY x.version_no DESC
         LIMIT 1) cs ON (true))
     LEFT JOIN LATERAL ( SELECT (count(*))::integer AS concept_count,
            jsonb_agg(jsonb_build_object('projectConceptId', c.project_concept_id, 'sequenceNo', c.sequence_no, 'teachesId', c.teaches_id, 'mappingId', c.source_mapping_id, 'name', t.canonical_name) ORDER BY c.sequence_no) AS items
           FROM (public.project_verification_concept c
             LEFT JOIN public.teaches t ON ((t.teaches_id = c.teaches_id)))
          WHERE (c.concept_set_id = cs.concept_set_id)) concepts ON (true))
     LEFT JOIN LATERAL ( SELECT jsonb_agg(jsonb_build_object('requirementId', r.requirement_id, 'key', r.requirement_key, 'sequenceNo', r.sequence_no, 'title', r.title, 'description', r.description) ORDER BY r.sequence_no) AS items
           FROM public.project_requirement r
          WHERE ((r.project_id = p.project_id) AND r.active AND (r.effective_from <= CURRENT_TIMESTAMP) AND ((r.effective_to IS NULL) OR (r.effective_to > CURRENT_TIMESTAMP)))) req ON (true))
     LEFT JOIN LATERAL ( SELECT (count(*) FILTER (WHERE (r.deleted_at IS NULL)))::integer AS active_count,
            jsonb_agg(jsonb_build_object('assessmentRoundId', r.assessment_round_id, 'roundNo', r.round_no, 'roundName', r.round_name, 'status', r.status, 'submissionDueAt', r.submission_due_at, 'isFinal', r.is_final, 'assessmentOpenAt', r.assessment_open_at, 'assessmentDueAt', r.assessment_due_at) ORDER BY r.round_no) FILTER (WHERE (r.deleted_at IS NULL)) AS items,
            (array_agg(r.assessment_round_id ORDER BY
                CASE
                    WHEN ((r.status)::text = ANY ((ARRAY['OPEN'::character varying, 'PLANNED'::character varying])::text[])) THEN 0
                    ELSE 1
                END, r.round_no))[1] AS display_round_id,
            (array_agg(r.submission_due_at ORDER BY
                CASE
                    WHEN ((r.status)::text = ANY ((ARRAY['OPEN'::character varying, 'PLANNED'::character varying])::text[])) THEN 0
                    ELSE 1
                END, r.round_no))[1] AS submission_due_at,
            (array_agg(r.report_publish_mode ORDER BY
                CASE
                    WHEN ((r.status)::text = ANY ((ARRAY['OPEN'::character varying, 'PLANNED'::character varying])::text[])) THEN 0
                    ELSE 1
                END, r.round_no))[1] AS report_publish_mode,
            (array_agg(r.report_publish_not_before_at ORDER BY
                CASE
                    WHEN ((r.status)::text = ANY ((ARRAY['OPEN'::character varying, 'PLANNED'::character varying])::text[])) THEN 0
                    ELSE 1
                END, r.round_no))[1] AS report_publish_not_before_at,
            (array_agg(r.assessment_open_at ORDER BY
                CASE
                    WHEN ((r.status)::text = ANY ((ARRAY['OPEN'::character varying, 'PLANNED'::character varying])::text[])) THEN 0
                    ELSE 1
                END, r.round_no))[1] AS assessment_open_at,
            (array_agg(r.assessment_due_at ORDER BY
                CASE
                    WHEN ((r.status)::text = ANY ((ARRAY['OPEN'::character varying, 'PLANNED'::character varying])::text[])) THEN 0
                    ELSE 1
                END, r.round_no))[1] AS assessment_due_at
           FROM public.project_assessment_round r
          WHERE ((r.project_id = p.project_id) AND (r.deleted_at IS NULL))) rounds ON (true))
  WHERE (p.deleted_at IS NULL);


--
-- Name: operator_project_list_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operator_project_list_view AS
 SELECT p.org_id,
    p.cohort_id,
    p.project_id,
    p.sequence_no AS project_sequence_no,
    p.name AS project_name,
    p.project_category,
    p.start_date,
    p.end_date,
    p.lifecycle_status,
    p.concept_source_mode,
    p.curriculum_not_applicable,
    (
        CASE
            WHEN ((p.lifecycle_status)::text = 'CLOSED'::text) THEN 'CLOSED'::text
            WHEN ((p.lifecycle_status)::text = ANY ((ARRAY['RUNNING'::character varying, 'ACTIVE'::character varying])::text[])) THEN 'RUNNING'::text
            WHEN ((p.curriculum_not_applicable OR (COALESCE(cur.cnt, 0) > 0)) AND (COALESCE(con.concept_count, 0) = 3) AND (COALESCE(rd.total_round_count, 0) > 0)) THEN 'READY'::text
            ELSE 'PREPARING'::text
        END)::character varying(30) AS project_management_status,
    array_remove(ARRAY[
        CASE
            WHEN ((NOT p.curriculum_not_applicable) AND (COALESCE(cur.cnt, 0) = 0)) THEN 'CURRICULUM_REQUIRED'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (COALESCE(con.concept_count, 0) <> 3) THEN 'THREE_CONCEPTS_REQUIRED'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (COALESCE(rd.total_round_count, 0) = 0) THEN 'ROUND_REQUIRED'::text
            ELSE NULL::text
        END], NULL::text) AS readiness_reason_codes,
    cardinality(array_remove(ARRAY[
        CASE
            WHEN ((NOT p.curriculum_not_applicable) AND (COALESCE(cur.cnt, 0) = 0)) THEN 'CURRICULUM_REQUIRED'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (COALESCE(con.concept_count, 0) <> 3) THEN 'THREE_CONCEPTS_REQUIRED'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (COALESCE(rd.total_round_count, 0) = 0) THEN 'ROUND_REQUIRED'::text
            ELSE NULL::text
        END], NULL::text)) AS readiness_reason_count,
    COALESCE(cur.items, '[]'::jsonb) AS curriculum_versions,
    cs.concept_set_id AS active_concept_set_id,
    COALESCE(con.concept_count, 0) AS verification_concept_count,
    COALESCE(con.items, '[]'::jsonb) AS verification_concepts,
    COALESCE(rd.active_round_count, 0) AS active_round_count,
    COALESCE(rd.total_round_count, 0) AS total_round_count,
    (
        CASE
            WHEN (((p.project_category)::text = 'MINI'::text) AND (COALESCE(rd.total_round_count, 0) = 1)) THEN 'VALID'::text
            WHEN ((p.project_category)::text = 'MINI'::text) THEN 'INVALID_MINI_ROUND_COUNT'::text
            WHEN (COALESCE(rd.total_round_count, 0) > 0) THEN 'VALID'::text
            ELSE 'EMPTY'::text
        END)::character varying(100) AS round_cardinality_status,
    rd.display_round_id,
    rd.display_round_no,
    rd.display_submission_due_at,
    'ANALYSIS_COMPLETED_PLUS_24H'::character varying(100) AS display_assessment_window_mode,
    '24'::text AS display_assessment_window_hours,
    (
        CASE
            WHEN (rd.display_submission_due_at IS NULL) THEN 'NOT_CONFIGURED'::text
            WHEN (rd.display_submission_due_at < CURRENT_TIMESTAMP) THEN 'PASSED'::text
            WHEN (rd.display_submission_due_at < (CURRENT_TIMESTAMP + '3 days'::interval)) THEN 'IMMINENT'::text
            ELSE 'NORMAL'::text
        END)::character varying(30) AS deadline_status,
        CASE
            WHEN (rd.display_submission_due_at IS NULL) THEN NULL::integer
            ELSE (ceil((EXTRACT(epoch FROM (rd.display_submission_due_at - CURRENT_TIMESTAMP)) / 86400.0)))::integer
        END AS remaining_deadline_days,
    ((rd.display_submission_due_at IS NOT NULL) AND (rd.display_submission_due_at < (CURRENT_TIMESTAMP + '3 days'::interval))) AS deadline_warning,
    (count(*) OVER (PARTITION BY p.cohort_id))::integer AS total_project_count,
    (count(*) FILTER (WHERE ((NOT ((p.curriculum_not_applicable OR (COALESCE(cur.cnt, 0) > 0)) AND (COALESCE(con.concept_count, 0) = 3) AND (COALESCE(rd.total_round_count, 0) > 0))) AND ((p.lifecycle_status)::text <> ALL ((ARRAY['RUNNING'::character varying, 'ACTIVE'::character varying, 'CLOSED'::character varying])::text[])))) OVER (PARTITION BY p.cohort_id))::integer AS preparing_project_count,
    (count(*) FILTER (WHERE ((p.curriculum_not_applicable OR (COALESCE(cur.cnt, 0) > 0)) AND (COALESCE(con.concept_count, 0) = 3) AND (COALESCE(rd.total_round_count, 0) > 0) AND ((p.lifecycle_status)::text <> ALL ((ARRAY['RUNNING'::character varying, 'ACTIVE'::character varying, 'CLOSED'::character varying])::text[])))) OVER (PARTITION BY p.cohort_id))::integer AS ready_project_count,
    (count(*) FILTER (WHERE ((p.lifecycle_status)::text = ANY ((ARRAY['RUNNING'::character varying, 'ACTIVE'::character varying])::text[]))) OVER (PARTITION BY p.cohort_id))::integer AS running_project_count,
    (count(*) FILTER (WHERE ((p.lifecycle_status)::text = 'CLOSED'::text)) OVER (PARTITION BY p.cohort_id))::integer AS closed_project_count,
    COALESCE(coh.class_count, 0) AS class_count,
    COALESCE(coh.trainee_count, 0) AS trainee_membership_count,
    'COMPLETE'::character varying(20) AS aggregation_status,
    CURRENT_TIMESTAMP AS as_of_at
   FROM (((((public.project p
     LEFT JOIN LATERAL ( SELECT (count(*))::integer AS cnt,
            jsonb_agg(jsonb_build_object('versionId', v.version_id, 'versionNo', v.version_no, 'title', m.title) ORDER BY pc.sequence_no) AS items
           FROM ((public.project_curriculum pc
             JOIN public.curriculum_version v ON ((v.version_id = pc.curriculum_version_id)))
             JOIN public.curriculum_material m ON ((m.material_id = v.material_id)))
          WHERE (pc.project_id = p.project_id)) cur ON (true))
     LEFT JOIN LATERAL ( SELECT x.concept_set_id,
            x.project_id,
            x.org_id,
            x.version_no,
            x.status,
            x.effective_from,
            x.effective_to,
            x.created_by,
            x.change_reason,
            x.created_at
           FROM public.project_verification_concept_set x
          WHERE ((x.project_id = p.project_id) AND ((x.status)::text = 'ACTIVE'::text))
          ORDER BY x.version_no DESC
         LIMIT 1) cs ON (true))
     LEFT JOIN LATERAL ( SELECT (count(*))::integer AS concept_count,
            jsonb_agg(jsonb_build_object('projectConceptId', x.project_concept_id, 'sequenceNo', x.sequence_no, 'teachesId', x.teaches_id, 'name', t.canonical_name) ORDER BY x.sequence_no) AS items
           FROM (public.project_verification_concept x
             LEFT JOIN public.teaches t ON ((t.teaches_id = x.teaches_id)))
          WHERE (x.concept_set_id = cs.concept_set_id)) con ON (true))
     LEFT JOIN LATERAL ( SELECT (count(*))::integer AS total_round_count,
            (count(*) FILTER (WHERE ((x.status)::text = ANY ((ARRAY['PLANNED'::character varying, 'OPEN'::character varying])::text[]))))::integer AS active_round_count,
            (array_agg(x.assessment_round_id ORDER BY
                CASE
                    WHEN ((x.status)::text = ANY ((ARRAY['OPEN'::character varying, 'PLANNED'::character varying])::text[])) THEN 0
                    ELSE 1
                END, x.round_no))[1] AS display_round_id,
            (array_agg(x.round_no ORDER BY
                CASE
                    WHEN ((x.status)::text = ANY ((ARRAY['OPEN'::character varying, 'PLANNED'::character varying])::text[])) THEN 0
                    ELSE 1
                END, x.round_no))[1] AS display_round_no,
            (array_agg(x.submission_due_at ORDER BY
                CASE
                    WHEN ((x.status)::text = ANY ((ARRAY['OPEN'::character varying, 'PLANNED'::character varying])::text[])) THEN 0
                    ELSE 1
                END, x.round_no))[1] AS display_submission_due_at
           FROM public.project_assessment_round x
          WHERE ((x.project_id = p.project_id) AND (x.deleted_at IS NULL))) rd ON (true))
     LEFT JOIN LATERAL ( SELECT (( SELECT count(*) AS count
                   FROM public.class c
                  WHERE ((c.cohort_id = p.cohort_id) AND (c.deleted_at IS NULL))))::integer AS class_count,
            (( SELECT count(*) AS count
                   FROM public.cohort_member cm
                  WHERE ((cm.cohort_id = p.cohort_id) AND ((cm.status)::text = 'ACTIVE'::text) AND (cm.left_at IS NULL))))::integer AS trainee_count) coh ON (true))
  WHERE (p.deleted_at IS NULL);


--
-- Name: operator_project_status_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operator_project_status_view AS
 SELECT p.org_id,
    p.cohort_id,
    p.project_id,
    r.assessment_round_id,
    c.class_id,
    (COALESCE(ms.names, (ARRAY[]::text[])::character varying[]))::text[] AS manager_names,
    COALESCE(ms.manager_count, 0) AS manager_count,
        CASE
            WHEN (COALESCE(ms.manager_count, 0) = 0) THEN 'MANAGER_NOT_ASSIGNED'::text
            ELSE NULL::text
        END AS manager_missing_warning,
    COALESCE(stats.eligible_trainee_count, 0) AS eligible_trainee_count,
    COALESCE(stats.submission_target_team_count, 0) AS submission_target_team_count,
    COALESCE(stats.submission_covered_trainee_count, 0) AS submission_covered_trainee_count,
    COALESCE(stats.analysis_succeeded_team_count, 0) AS analysis_succeeded_team_count,
    COALESCE(stats.analysis_failed_team_count, 0) AS analysis_failed_team_count,
    COALESCE(stats.analysis_succeeded_trainee_count, 0) AS analysis_succeeded_trainee_count,
    COALESCE(stats.analysis_failed_trainee_count, 0) AS analysis_failed_trainee_count,
    COALESCE(stats.prepared_problem_count, 0) AS prepared_problem_count,
    COALESCE(stats.prepared_question_count, 0) AS prepared_question_count,
    (
        CASE
            WHEN (COALESCE(stats.prepared_problem_count, 0) = 0) THEN 'NOT_READY'::text
            WHEN (COALESCE(stats.prepared_problem_count, 0) >= 3) THEN 'READY'::text
            ELSE 'PARTIAL'::text
        END)::character varying(100) AS problem_set_completion_status,
    COALESCE(stats.assessment_eligible_trainee_count, 0) AS assessment_eligible_trainee_count,
    COALESCE(stats.assessment_completed_trainee_count, 0) AS assessment_completed_trainee_count,
    GREATEST((COALESCE(stats.eligible_trainee_count, 0) - COALESCE(stats.assessment_eligible_trainee_count, 0)), 0) AS assessment_not_ready_count,
    COALESCE(stats.own_commit_ready_trainee_count, 0) AS own_commit_ready_trainee_count,
    COALESCE(stats.insufficient_own_commit_evidence_count, 0) AS insufficient_own_commit_evidence_count,
    COALESCE(stats.analysis_failure_codes, ARRAY[]::text[]) AS analysis_failure_codes,
    'COMPLETE'::character varying(20) AS aggregation_status,
    CURRENT_TIMESTAMP AS as_of_at
   FROM ((((public.project p
     JOIN public.project_assessment_round r ON (((r.project_id = p.project_id) AND (r.deleted_at IS NULL))))
     JOIN public.class c ON (((c.cohort_id = p.cohort_id) AND (c.deleted_at IS NULL))))
     LEFT JOIN LATERAL ( SELECT (count(*))::integer AS manager_count,
            array_agg(u.name ORDER BY u.name) AS names
           FROM (public.manager_assignment ma
             JOIN public.app_user u ON ((u.user_id = ma.manager_user_id)))
          WHERE ((ma.class_id = c.class_id) AND ((ma.status)::text = 'ACTIVE'::text) AND (ma.unassigned_at IS NULL))) ms ON (true))
     LEFT JOIN LATERAL ( SELECT (( SELECT count(*) AS count
                   FROM public.project_membership pm
                  WHERE ((pm.project_id = p.project_id) AND (pm.class_id = c.class_id) AND ((pm.status)::text = 'ACTIVE'::text))))::integer AS eligible_trainee_count,
            (( SELECT count(*) AS count
                   FROM public.team t
                  WHERE ((t.project_id = p.project_id) AND (t.class_id = c.class_id) AND (t.deleted_at IS NULL))))::integer AS submission_target_team_count,
            (( SELECT count(DISTINCT pm.user_id) AS count
                   FROM (((public.submission s
                     JOIN public.team t ON ((t.team_id = s.team_id)))
                     JOIN public.team_membership tm ON (((tm.team_id = t.team_id) AND (tm.to_at IS NULL))))
                     JOIN public.project_membership pm ON ((pm.project_membership_id = tm.project_membership_id)))
                  WHERE ((t.project_id = p.project_id) AND (t.class_id = c.class_id) AND (s.assessment_round_id = r.assessment_round_id) AND s.is_current)))::integer AS submission_covered_trainee_count,
            (( SELECT count(DISTINCT aj.team_id) AS count
                   FROM (public.analysis_job aj
                     JOIN public.team t ON ((t.team_id = aj.team_id)))
                  WHERE ((t.project_id = p.project_id) AND (t.class_id = c.class_id) AND (aj.assessment_round_id = r.assessment_round_id) AND ((aj.status)::text = 'SUCCEEDED'::text))))::integer AS analysis_succeeded_team_count,
            (( SELECT count(DISTINCT aj.team_id) AS count
                   FROM (public.analysis_job aj
                     JOIN public.team t ON ((t.team_id = aj.team_id)))
                  WHERE ((t.project_id = p.project_id) AND (t.class_id = c.class_id) AND (aj.assessment_round_id = r.assessment_round_id) AND ((aj.status)::text = 'FAILED'::text))))::integer AS analysis_failed_team_count,
            (( SELECT count(DISTINCT pm.user_id) AS count
                   FROM (((public.analysis_job aj
                     JOIN public.team t ON ((t.team_id = aj.team_id)))
                     JOIN public.team_membership tm ON (((tm.team_id = t.team_id) AND (tm.to_at IS NULL))))
                     JOIN public.project_membership pm ON ((pm.project_membership_id = tm.project_membership_id)))
                  WHERE ((t.class_id = c.class_id) AND (aj.assessment_round_id = r.assessment_round_id) AND ((aj.status)::text = 'SUCCEEDED'::text))))::integer AS analysis_succeeded_trainee_count,
            (( SELECT count(DISTINCT pm.user_id) AS count
                   FROM (((public.analysis_job aj
                     JOIN public.team t ON ((t.team_id = aj.team_id)))
                     JOIN public.team_membership tm ON (((tm.team_id = t.team_id) AND (tm.to_at IS NULL))))
                     JOIN public.project_membership pm ON ((pm.project_membership_id = tm.project_membership_id)))
                  WHERE ((t.class_id = c.class_id) AND (aj.assessment_round_id = r.assessment_round_id) AND ((aj.status)::text = 'FAILED'::text))))::integer AS analysis_failed_trainee_count,
            (( SELECT count(*) AS count
                   FROM ((public.assessment_problem ap
                     JOIN public.code_analysis ca ON ((ca.analysis_id = ap.code_analysis_id)))
                     JOIN public.team t ON ((t.team_id = ca.team_id)))
                  WHERE ((ca.assessment_round_id = r.assessment_round_id) AND (t.class_id = c.class_id) AND ((ap.generation_status)::text = 'GENERATED'::text))))::integer AS prepared_problem_count,
            (( SELECT count(*) AS count
                   FROM (((public.problem_stage ps
                     JOIN public.assessment_problem ap ON ((ap.problem_id = ps.problem_id)))
                     JOIN public.code_analysis ca ON ((ca.analysis_id = ap.code_analysis_id)))
                     JOIN public.team t ON ((t.team_id = ca.team_id)))
                  WHERE ((ca.assessment_round_id = r.assessment_round_id) AND (t.class_id = c.class_id))))::integer AS prepared_question_count,
            (( SELECT count(DISTINCT ma.user_id) AS count
                   FROM (public.measurement_attempt ma
                     JOIN public.project_membership pm ON (((pm.user_id = ma.user_id) AND (pm.project_id = p.project_id))))
                  WHERE ((ma.assessment_round_id = r.assessment_round_id) AND (pm.class_id = c.class_id) AND (ma.assessment_open_at IS NOT NULL))))::integer AS assessment_eligible_trainee_count,
            (( SELECT count(DISTINCT ma.user_id) AS count
                   FROM (public.measurement_attempt ma
                     JOIN public.project_membership pm ON (((pm.user_id = ma.user_id) AND (pm.project_id = p.project_id))))
                  WHERE ((ma.assessment_round_id = r.assessment_round_id) AND (pm.class_id = c.class_id) AND ((ma.attempt_type)::text = 'INITIAL'::text) AND ((ma.status)::text = 'COMPLETED'::text))))::integer AS assessment_completed_trainee_count,
            (( SELECT count(DISTINCT ap.target_user_id) AS count
                   FROM ((public.assessment_problem ap
                     JOIN public.measurement_attempt ma ON ((ma.attempt_id = ap.measurement_attempt_id)))
                     JOIN public.project_membership pm ON (((pm.user_id = ma.user_id) AND (pm.project_id = p.project_id))))
                  WHERE ((ma.assessment_round_id = r.assessment_round_id) AND (pm.class_id = c.class_id) AND ((ap.problem_scope)::text = 'INDIVIDUAL_OWN_COMMIT'::text) AND ((ap.generation_status)::text = 'GENERATED'::text))))::integer AS own_commit_ready_trainee_count,
            (( SELECT count(DISTINCT ma.user_id) AS count
                   FROM (public.measurement_attempt ma
                     JOIN public.project_membership pm ON (((pm.user_id = ma.user_id) AND (pm.project_id = p.project_id))))
                  WHERE ((ma.assessment_round_id = r.assessment_round_id) AND (pm.class_id = c.class_id) AND ((ma.terminal_reason_code)::text = 'INSUFFICIENT_OWN_COMMIT_EVIDENCE'::text))))::integer AS insufficient_own_commit_evidence_count,
            ( SELECT array_agg(DISTINCT aj.failure_reason) FILTER (WHERE (aj.failure_reason IS NOT NULL)) AS array_agg
                   FROM (public.analysis_job aj
                     JOIN public.team t ON ((t.team_id = aj.team_id)))
                  WHERE ((aj.assessment_round_id = r.assessment_round_id) AND (t.class_id = c.class_id) AND ((aj.status)::text = 'FAILED'::text))) AS analysis_failure_codes) stats ON (true))
  WHERE (p.deleted_at IS NULL);


--
-- Name: organization_grading_calibration; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.organization_grading_calibration (
    organization_calibration_id uuid DEFAULT gen_random_uuid() NOT NULL,
    calibration_version_id uuid NOT NULL,
    org_id uuid NOT NULL,
    status character varying(30) NOT NULL,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    failure_code character varying(100),
    failure_reason text,
    failed_at timestamp with time zone,
    retry_count integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT ck_org_grading_calibration_completed_at CHECK ((((status)::text <> 'SUCCEEDED'::text) OR (completed_at IS NOT NULL))),
    CONSTRAINT ck_org_grading_calibration_failed_fields CHECK ((((status)::text <> 'FAILED'::text) OR ((failure_code IS NOT NULL) AND (failed_at IS NOT NULL)))),
    CONSTRAINT ck_org_grading_calibration_failure_code_format CHECK (((failure_code IS NULL) OR ((failure_code)::text ~ '^[A-Z][A-Z0-9_]{0,99}$'::text))),
    CONSTRAINT ck_organization_grading_calibration_retry_count CHECK ((retry_count >= 0)),
    CONSTRAINT ck_organization_grading_calibration_status CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'RUNNING'::character varying, 'SUCCEEDED'::character varying, 'FAILED'::character varying])::text[])))
);


--
-- Name: TABLE organization_grading_calibration; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.organization_grading_calibration IS '하나의 플랫폼 캘리브레이션 작업을 기관별로 나누어 진행한 상태 기록입니다. 각 기관이 대기·진행·성공·실패 중 어디에 있는지와 재시도 횟수를 따로 관리합니다. | 정의서명: OrganizationGradingCalibration | 제약·비고: • UNIQUE(calibration_version_id, org_id) • 상태: PENDING / RUNNING / SUCCEEDED / FAILED • SUCCEEDED이면 completed_at 필수 • FAILED이면 failure_code·failed_at 필수 • retry_count >= 0 • 파기 완료 기관은 생성 대상에서 제외 • 기관별 상태를 독립 조회·재시도할 수 있도록 org_id 직접 RLS 적용 • created_at은 기관별 대상 행 생성 시각, updated_at은 최신 상태 변경 시각이며 deleted_at은 사용하지 않음 • failure_code는 SYS.ORGANIZATION_GRADING_CALIBRATION_FAILURE_CODE 영문 대문자·숫자·밑줄 1~100자의 확장형 서비스 코드 카탈로그를 사용 • RUNNING이면 started_at, SUCCEEDED이면 completed_at, FAILED이면 failure_code와 failed_at이 필수입니다. • UNIQUE(calibration_version_id, org_id)로 같은 버전·기관의 중복 작업 행을 막습니다. • 이미 파기 완료된 기관은 새 캘리브레이션 대상에서 제외합니다. • 일부 기관 행 생성에 실패하면 플랫폼 채점 정책 변경 전체를 롤백하여 반쪽짜리 대상 목록을 남기지 않습니다.';


