-- Name: storage_usage_snapshot; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.storage_usage_snapshot (
    snapshot_id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    measurement_batch_id uuid NOT NULL,
    used_bytes bigint NOT NULL,
    file_count integer DEFAULT 0 NOT NULL,
    captured_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    storage_category character varying(100) DEFAULT 'ORG_TOTAL'::character varying NOT NULL,
    storage_scope character varying(100) DEFAULT 'ORG_TOTAL'::character varying NOT NULL,
    source_type character varying(100) NOT NULL,
    measurement_method character varying(100) NOT NULL,
    source_ref text,
    calculation_version integer DEFAULT 1 NOT NULL,
    source_watermark text,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT ck_storage_usage_snapshot_calculation_version CHECK ((calculation_version > 0)),
    CONSTRAINT ck_storage_usage_snapshot_file_count CHECK ((file_count >= 0)),
    CONSTRAINT ck_storage_usage_snapshot_measurement_method_format CHECK (((measurement_method)::text ~ '^[A-Z][A-Z0-9_]{0,99}$'::text)),
    CONSTRAINT ck_storage_usage_snapshot_source_type CHECK (((source_type)::text = ANY ((ARRAY['DB_METADATA'::character varying, 'DB_SYSTEM_CATALOG'::character varying, 'CLOUD_API'::character varying, 'CLOUD_INVENTORY'::character varying, 'CLOUD_METRIC'::character varying])::text[]))),
    CONSTRAINT ck_storage_usage_snapshot_storage_category CHECK (((storage_category)::text = ANY ((ARRAY['ORG_TOTAL'::character varying, 'CODE_ARTIFACT'::character varying, 'SESSION_TRANSCRIPT'::character varying, 'SCORE_EVIDENCE'::character varying, 'REPORT_EXPORT'::character varying, 'CURRICULUM_PDF'::character varying, 'DATABASE'::character varying])::text[]))),
    CONSTRAINT ck_storage_usage_snapshot_storage_scope_not_blank CHECK ((length(TRIM(BOTH FROM storage_scope)) > 0)),
    CONSTRAINT ck_storage_usage_snapshot_used_bytes CHECK ((used_bytes >= 0))
);


--
-- Name: TABLE storage_usage_snapshot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.storage_usage_snapshot IS '기관이 파일과 데이터 저장 공간을 얼마나 쓰고 있었는지 특정 시점에 재어 둔 기록입니다. 체중계의 측정값처럼 원본 파일 자체가 아니라 저장 범주별 바이트 수와 파일 수, 측정 방법을 보존합니다. | 정의서명: StorageUsageSnapshot | 제약·비고: • 성공한 측정값만 적재 • UNIQUE(measurement_batch_id, storage_category, storage_scope) • used_bytes·file_count는 0 이상, calculation_version > 0 • 카테고리: ORG_TOTAL / CODE_ARTIFACT / SESSION_TRANSCRIPT / SCORE_EVIDENCE / REPORT_EXPORT / CURRICULUM_PDF / DATABASE • 원천 유형: DB_METADATA / DB_SYSTEM_CATALOG / CLOUD_API / CLOUD_INVENTORY / CLOUD_METRIC • 화면 범주는 동일 measurement_batch_id·captured_at·calculation_version의 완전한 세트만 합산 • 저장량 상한 판정은 최신 ORG_TOTAL 행 1건 사용 • 원천 비밀값·서명 URL 저장 금지 • file_count=0이 실제 파일 0인지 원천에서 파일 수를 제공하지 않은 것인지는 measurement_method로 구분합니다. • 화면의 필수 저장 범주 행이 빠지면 0으로 채우지 않고 집계 실패로 처리합니다. • storage_category=''ORG_TOTAL'' 행은 기관 전체 한도 판정용이며 세부 범주와 다시 더하지 않습니다. • 성공한 측정값만 저장하고 측정 실패·재시도 정보는 OrganizationUsageSnapshot 또는 집계 작업 로그에서 관리합니다.';


