    (current_token_purpose)::character varying(50) AS current_token_purpose,
    current_token_expires_at,
    current_token_used_at,
    current_token_invalidated_at,
    current_token_invalidated_reason,
    can_suspend,
    can_reactivate,
    can_resend,
    can_cancel,
    (action_block_code)::character varying(100) AS action_block_code,
    active_operator_count,
    pending_operator_invitation_count,
    (operator_bootstrap_status)::character varying(30) AS operator_bootstrap_status
   FROM z;


--
-- Name: super_admin_organization_settings_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.super_admin_organization_settings_view AS
 SELECT o.org_id,
    o.name,
    (o.status)::character varying(30) AS lifecycle_status,
    p.policy_id AS current_policy_id,
    p.policy_version,
    p.effective_from AS policy_effective_from,
    p.monthly_ai_budget,
    p.monthly_token_limit,
    p.retention_days,
    (p.default_disclosure_scope)::character varying(30) AS default_disclosure_scope,
    NULL::character varying(30) AS question_generation_tier_code,
    NULL::character varying(30) AS summary_tier_code,
    p.allow_github_integration,
    p.allow_zip_submission,
    p.enable_big_project_contribution_analysis,
    (COALESCE(p.currency_code, 'USD'::character varying))::character varying(3) AS currency_code,
    p.storage_limit_bytes,
    p.allow_manager_invite,
    p.allow_data_export,
    ((o.status)::text = 'ACTIVE'::text) AS can_suspend,
    ((o.status)::text = 'SUSPENDED'::text) AS can_activate,
    ((o.status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'SUSPENDED'::character varying])::text[])) AS can_request_deletion,
    ((o.status)::text <> 'DELETED'::text) AS policy_update_allowed
   FROM (public.organization o
     LEFT JOIN LATERAL ( SELECT x.policy_id,
            x.org_id,
            x.policy_version,
            x.monthly_ai_budget,
            x.currency_code,
            x.monthly_token_limit,
            x.storage_limit_bytes,
            x.retention_days,
            x.default_disclosure_scope,
            x.code_session_tier_code,
            x.allow_manager_invite,
            x.allow_data_export,
            x.allow_zip_submission,
            x.allow_github_integration,
            x.enable_big_project_contribution_analysis,
            x.effective_from,
            x.effective_to,
            x.status,
            x.created_by,
            x.created_at,
            x.updated_by,
            x.updated_at
           FROM public.organization_policy x
          WHERE ((x.org_id = o.org_id) AND ((x.status)::text = 'ACTIVE'::text) AND (x.effective_from <= CURRENT_TIMESTAMP) AND ((x.effective_to IS NULL) OR (x.effective_to > CURRENT_TIMESTAMP)))
          ORDER BY x.policy_version DESC, x.effective_from DESC
         LIMIT 1) p ON (true))
  WHERE (o.deleted_at IS NULL);


--
-- Name: super_admin_organization_usage_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.super_admin_organization_usage_view AS
 WITH latest AS (
         SELECT DISTINCT ON (organization_usage_snapshot.org_id) organization_usage_snapshot.usage_snapshot_id,
            organization_usage_snapshot.org_id,
            organization_usage_snapshot.period_type,
            organization_usage_snapshot.period_start_at,
            organization_usage_snapshot.period_end_at,
            organization_usage_snapshot.as_of_at,
            organization_usage_snapshot.active_trainee_count,
            organization_usage_snapshot.completed_session_count,
            organization_usage_snapshot.grading_execution_count,
            organization_usage_snapshot.published_report_count,
            organization_usage_snapshot.ai_call_count,
            organization_usage_snapshot.input_token_count,
            organization_usage_snapshot.output_token_count,
            organization_usage_snapshot.cached_token_count,
            organization_usage_snapshot.unpriced_call_count,
            organization_usage_snapshot.unpriced_input_token_count,
            organization_usage_snapshot.unpriced_output_token_count,
            organization_usage_snapshot.cost_completeness_status,
            organization_usage_snapshot.estimated_cost,
            organization_usage_snapshot.actual_cost,
            organization_usage_snapshot.effective_cost,
            organization_usage_snapshot.currency_code,
            organization_usage_snapshot.aggregation_status,
            organization_usage_snapshot.failure_stage,
            organization_usage_snapshot.failure_code,
            organization_usage_snapshot.failure_reason,
            organization_usage_snapshot.failed_at,
            organization_usage_snapshot.is_retryable,
            organization_usage_snapshot.source_watermark,
            organization_usage_snapshot.calculation_version,
            organization_usage_snapshot.created_at
           FROM public.organization_usage_snapshot
          ORDER BY organization_usage_snapshot.org_id, organization_usage_snapshot.period_end_at DESC, organization_usage_snapshot.as_of_at DESC, organization_usage_snapshot.created_at DESC
        ), prev AS (
         SELECT l.org_id,
            ( SELECT x.effective_cost
                   FROM public.organization_usage_snapshot x
                  WHERE ((x.org_id = l.org_id) AND (x.period_end_at <= l.period_start_at))
                  ORDER BY x.period_end_at DESC, x.as_of_at DESC
                 LIMIT 1) AS effective_cost
           FROM latest l
        ), succ AS (
         SELECT organization_usage_snapshot.org_id,
            max(organization_usage_snapshot.as_of_at) FILTER (WHERE ((organization_usage_snapshot.aggregation_status)::text = ANY ((ARRAY['COMPLETE'::character varying, 'SUCCESS'::character varying])::text[]))) AS last_successful_as_of_at
           FROM public.organization_usage_snapshot
          GROUP BY organization_usage_snapshot.org_id
        ), policy AS (
         SELECT DISTINCT ON (organization_policy.org_id) organization_policy.policy_id,
            organization_policy.org_id,
            organization_policy.policy_version,
            organization_policy.monthly_ai_budget,
            organization_policy.currency_code,
            organization_policy.monthly_token_limit,
            organization_policy.storage_limit_bytes,
            organization_policy.retention_days,
            organization_policy.default_disclosure_scope,
            organization_policy.code_session_tier_code,
            organization_policy.allow_manager_invite,
            organization_policy.allow_data_export,
            organization_policy.allow_zip_submission,
            organization_policy.allow_github_integration,
            organization_policy.enable_big_project_contribution_analysis,
            organization_policy.effective_from,
            organization_policy.effective_to,
            organization_policy.status,
            organization_policy.created_by,
            organization_policy.created_at,
            organization_policy.updated_by,
            organization_policy.updated_at
           FROM public.organization_policy
          WHERE (((organization_policy.status)::text = 'ACTIVE'::text) AND (organization_policy.effective_from <= CURRENT_TIMESTAMP) AND ((organization_policy.effective_to IS NULL) OR (organization_policy.effective_to > CURRENT_TIMESTAMP)))
          ORDER BY organization_policy.org_id, organization_policy.policy_version DESC, organization_policy.effective_from DESC
        ), storage_latest_batch AS (
         SELECT DISTINCT ON (storage_usage_snapshot.org_id) storage_usage_snapshot.org_id,
            storage_usage_snapshot.measurement_batch_id,
            storage_usage_snapshot.captured_at
           FROM public.storage_usage_snapshot
          ORDER BY storage_usage_snapshot.org_id, storage_usage_snapshot.captured_at DESC, storage_usage_snapshot.created_at DESC
        ), st AS (
         SELECT s.org_id,
            (sum(s.used_bytes) FILTER (WHERE ((s.storage_category)::text = 'CODE_ARTIFACT'::text)))::bigint AS code_artifact_storage_bytes,
            (sum(s.used_bytes) FILTER (WHERE ((s.storage_category)::text = 'SESSION_TRANSCRIPT'::text)))::bigint AS session_transcript_storage_bytes,
            (sum(s.used_bytes) FILTER (WHERE ((s.storage_category)::text = 'SCORE_EVIDENCE'::text)))::bigint AS score_evidence_storage_bytes,
            (sum(s.used_bytes) FILTER (WHERE ((s.storage_category)::text = 'REPORT_EXPORT'::text)))::bigint AS report_export_storage_bytes,
            (sum(s.used_bytes))::bigint AS display_storage_total_bytes
           FROM (public.storage_usage_snapshot s
             JOIN storage_latest_batch b ON (((b.org_id = s.org_id) AND (b.measurement_batch_id = s.measurement_batch_id))))
          GROUP BY s.org_id
        ), ab AS (
         SELECT a.org_id,
            a.feature_code,
            m.model_id,
            (count(*))::integer AS ai_call_count,
            (sum(a.input_token_count))::bigint AS input_token_count,
            (sum(a.output_token_count))::bigint AS output_token_count,
            (sum(a.cached_token_count))::bigint AS cached_token_count,
            sum(COALESCE(a.actual_cost, a.estimated_cost, (0)::numeric)) AS effective_cost,
            (count(*) FILTER (WHERE ((a.pricing_status)::text = 'UNPRICED'::text)))::integer AS unpriced_call_count,
            (sum(a.input_token_count) FILTER (WHERE ((a.pricing_status)::text = 'UNPRICED'::text)))::bigint AS unpriced_input_token_count,
            (sum(a.output_token_count) FILTER (WHERE ((a.pricing_status)::text = 'UNPRICED'::text)))::bigint AS unpriced_output_token_count
           FROM ((public.ai_usage a
             JOIN latest l ON ((l.org_id = a.org_id)))
             LEFT JOIN public.ai_model m ON (((m.model_code)::text = (a.model_code)::text)))
          WHERE ((a.occurred_at >= l.period_start_at) AND (a.occurred_at < l.period_end_at))
          GROUP BY a.org_id, a.feature_code, m.model_id
        )
 SELECT u.org_id,
    u.period_start_at,
    u.period_end_at,
    u.as_of_at,
    (COALESCE(u.currency_code, p.currency_code, 'USD'::character varying))::character varying(3) AS currency_code,
    COALESCE(st.code_artifact_storage_bytes, (0)::bigint) AS code_artifact_storage_bytes,
    COALESCE(st.session_transcript_storage_bytes, (0)::bigint) AS session_transcript_storage_bytes,
    COALESCE(st.score_evidence_storage_bytes, (0)::bigint) AS score_evidence_storage_bytes,
    COALESCE(st.report_export_storage_bytes, (0)::bigint) AS report_export_storage_bytes,
    COALESCE(st.display_storage_total_bytes, (0)::bigint) AS display_storage_total_bytes,
    p.storage_limit_bytes AS policy_storage_total_bytes,
    u.active_trainee_count,
    u.completed_session_count,
    u.grading_execution_count,
    u.published_report_count,
    ab.feature_code,
    ab.model_id,
    COALESCE((ab.ai_call_count)::bigint, u.ai_call_count) AS ai_call_count,
    COALESCE(ab.input_token_count, u.input_token_count) AS input_token_count,
    COALESCE(ab.output_token_count, u.output_token_count) AS output_token_count,
    COALESCE(ab.cached_token_count, u.cached_token_count) AS cached_token_count,
    (COALESCE(ab.effective_cost, u.effective_cost))::numeric(18,6) AS effective_cost,
    COALESCE((ab.unpriced_call_count)::bigint, u.unpriced_call_count) AS unpriced_call_count,
    COALESCE(ab.unpriced_input_token_count, u.unpriced_input_token_count) AS unpriced_input_token_count,
    COALESCE(ab.unpriced_output_token_count, u.unpriced_output_token_count) AS unpriced_output_token_count,
    u.cost_completeness_status,
    p.monthly_ai_budget,
    (
        CASE
            WHEN ((p.monthly_ai_budget IS NULL) OR (p.monthly_ai_budget = (0)::numeric)) THEN NULL::numeric
            ELSE (u.effective_cost / p.monthly_ai_budget)
        END)::numeric(9,4) AS budget_utilization_rate,
    (
        CASE
            WHEN (p.monthly_ai_budget IS NULL) THEN NULL::numeric
            ELSE (p.monthly_ai_budget - u.effective_cost)
        END)::numeric(18,6) AS budget_remaining,
    (
        CASE
            WHEN (p.monthly_ai_budget IS NULL) THEN 'NOT_CONFIGURED'::text
            WHEN (u.effective_cost > p.monthly_ai_budget) THEN 'EXCEEDED'::text
            WHEN (u.effective_cost >= (p.monthly_ai_budget * 0.8)) THEN 'WARNING'::text
            ELSE 'NORMAL'::text
        END)::character varying(30) AS budget_status,
    prev.effective_cost AS previous_period_effective_cost,
    (
        CASE
            WHEN ((prev.effective_cost IS NULL) OR (prev.effective_cost = (0)::numeric)) THEN NULL::numeric
            ELSE ((u.effective_cost - prev.effective_cost) / prev.effective_cost)
        END)::numeric(9,4) AS cost_change_rate,
    (
        CASE
            WHEN (prev.effective_cost IS NULL) THEN 'NO_BASELINE'::text
            WHEN (prev.effective_cost = (0)::numeric) THEN 'ZERO_BASELINE'::text
            ELSE 'COMPARABLE'::text
        END)::character varying(30) AS comparison_status,
    u.aggregation_status,
    u.failure_stage,
    u.failure_code,
    succ.last_successful_as_of_at,
    (u.as_of_at < (CURRENT_TIMESTAMP - '24:00:00'::interval)) AS stale
   FROM (((((latest u
     LEFT JOIN policy p ON ((p.org_id = u.org_id)))
     LEFT JOIN prev ON ((prev.org_id = u.org_id)))
     LEFT JOIN succ ON ((succ.org_id = u.org_id)))
     LEFT JOIN st ON ((st.org_id = u.org_id)))
     LEFT JOIN ab ON ((ab.org_id = u.org_id)));


--
-- Name: super_admin_platform_model_settings_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.super_admin_platform_model_settings_view AS
 SELECT m.model_id,
    m.model_code,
    m.provider,
    m.provider_model_code,
    m.display_name,
    (m.status)::character varying(30) AS status,
    m.input_unit_price,
    m.output_unit_price,
    m.cached_input_unit_price,
    m.currency_code,
    m.price_unit_token_count,
    m.price_effective_from,
    (
        CASE
            WHEN ((m.input_unit_price IS NULL) OR (m.output_unit_price IS NULL) OR (m.currency_code IS NULL)) THEN 'INCOMPLETE'::text
            ELSE 'COMPLETE'::text
        END)::character varying(30) AS price_completeness_status,
    ((m.input_unit_price IS NOT NULL) AND (m.output_unit_price IS NOT NULL) AND (m.currency_code IS NOT NULL)) AS pricing_complete,
    (
        CASE
            WHEN ((m.status)::text <> 'ACTIVE'::text) THEN 'MODEL_INACTIVE'::text
            WHEN ((m.input_unit_price IS NULL) OR (m.output_unit_price IS NULL)) THEN 'PRICE_INCOMPLETE'::text
            ELSE NULL::text
        END)::character varying(100) AS model_unavailable_reason_code,
    gp.grading_policy_id AS active_grading_policy_id,
    gp.policy_version AS grading_policy_version,
    gp.model_id AS active_grading_model_id,
    cv.calibration_version_id AS active_calibration_version_id,
    cv.status AS calibration_status,
    COALESCE(cs.target_count, 0) AS calibration_target_org_count,
    COALESCE(cs.pending_count, 0) AS calibration_pending_org_count,
    COALESCE(cs.running_count, 0) AS calibration_running_org_count,
    COALESCE(cs.succeeded_count, 0) AS calibration_succeeded_org_count,
    COALESCE(cs.failed_count, 0) AS calibration_failed_org_count,
    tp.feature_code,
    tp.tier_code,
    tp.tier_policy_id,
    tp.model_id AS tier_model_id,
    (count(*) FILTER (WHERE ((m.input_unit_price IS NULL) OR (m.output_unit_price IS NULL))) OVER ())::integer AS unpriced_model_count
   FROM ((((public.ai_model m
     LEFT JOIN LATERAL ( SELECT x.grading_policy_id,
            x.policy_version,
            x.model_id,
            x.status,
            x.effective_from,
            x.effective_to,
            x.changed_by,
            x.change_reason,
            x.created_at,
            x.updated_at
           FROM public.platform_grading_model_policy x
          WHERE (((x.status)::text = 'ACTIVE'::text) AND (x.effective_from <= CURRENT_TIMESTAMP) AND ((x.effective_to IS NULL) OR (x.effective_to > CURRENT_TIMESTAMP)))
          ORDER BY x.policy_version DESC, x.effective_from DESC
         LIMIT 1) gp ON (true))
     LEFT JOIN LATERAL ( SELECT x.calibration_version_id,
            x.grading_policy_id,
            x.version_code,
            x.status,
            x.started_at,
            x.completed_at,
            x.created_by,
            x.failure_code,
            x.failure_reason,
            x.failed_at,
            x.created_at,
            x.updated_at
           FROM public.platform_grading_calibration_version x
          WHERE (x.grading_policy_id = gp.grading_policy_id)
          ORDER BY x.created_at DESC, x.version_code DESC
         LIMIT 1) cv ON (true))
     LEFT JOIN LATERAL ( SELECT (count(*))::integer AS target_count,
            (count(*) FILTER (WHERE ((x.status)::text = 'PENDING'::text)))::integer AS pending_count,
            (count(*) FILTER (WHERE ((x.status)::text = 'RUNNING'::text)))::integer AS running_count,
            (count(*) FILTER (WHERE ((x.status)::text = 'SUCCEEDED'::text)))::integer AS succeeded_count,
            (count(*) FILTER (WHERE ((x.status)::text = 'FAILED'::text)))::integer AS failed_count
           FROM public.organization_grading_calibration x
          WHERE (x.calibration_version_id = cv.calibration_version_id)) cs ON (true))
     LEFT JOIN public.platform_ai_tier_model_policy tp ON (((tp.model_id = m.model_id) AND ((tp.status)::text = 'ACTIVE'::text) AND (tp.effective_from <= CURRENT_TIMESTAMP) AND ((tp.effective_to IS NULL) OR (tp.effective_to > CURRENT_TIMESTAMP)))));


--
-- Name: trainee_home_round_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.trainee_home_round_view AS
 SELECT a.user_id AS trainee_user_id,
    a.org_id,
    a.cohort_id,
    a.class_id AS class_id_at_round,
    cl.name AS class_name,
    a.team_id AS team_id_at_round,
    tm.team_number,
    tm.name AS team_name,
    a.project_id,
    p.name AS project_name,
    p.project_category,
    a.assessment_round_id,
    a.round_no,
    a.round_name,
    a.round_status,
    COALESCE(cur.version_ids, ARRAY[]::uuid[]) AS curriculum_version_ids,
    (COALESCE(cur.names, (ARRAY[]::text[])::character varying[]))::text[] AS curriculum_display_names,
    a.source_submission_id AS current_submission_id,
    a.submission_method,
    a.submission_status,
    a.submitted_at,
    a.submission_due_at,
    (array_remove(ARRAY['GITHUB_URL'::text,
        CASE
            WHEN COALESCE(pol.allow_zip_submission, false) THEN 'ZIP_WITH_GITLOG'::text
            ELSE NULL::text
        END], NULL::text))::text AS available_submission_methods,
    ((a.submission_due_at > CURRENT_TIMESTAMP) AND (a.primary_session_status IS NULL)) AS can_submit,
    ((a.source_submission_id IS NOT NULL) AND (a.submission_due_at > CURRENT_TIMESTAMP) AND (a.primary_session_status IS NULL)) AS can_resubmit,
        CASE
            WHEN (a.source_submission_id IS NULL) THEN 'NOT_SUBMITTED'::text
            WHEN ((a.analysis_status)::text = ANY ((ARRAY['QUEUED'::character varying, 'RUNNING'::character varying])::text[])) THEN 'ANALYZING'::text
            WHEN ((a.analysis_status)::text = 'FAILED'::text) THEN 'FAILED'::text
            WHEN ((a.analysis_status)::text = 'SUCCEEDED'::text) THEN 'COMPLETED'::text
            ELSE 'WAITING'::text
        END AS analysis_phase,
    a.analysis_job_id AS latest_analysis_job_id,
    a.analysis_status AS analysis_job_status,
    ma.code_analysis_id,
    (
        CASE
            WHEN ((a.analysis_status)::text = 'FAILED'::text) THEN 'ANALYSIS_FAILED'::text
            ELSE NULL::text
        END)::character varying(100) AS analysis_failure_code,
    COALESCE(probs.problem_count, 0) AS prepared_problem_count,
    COALESCE(probs.question_count, 0) AS prepared_question_count,
    (probs.problem_scope)::character varying(100) AS problem_scope,
    a.primary_attempt_id AS initial_attempt_id,
    a.primary_attempt_status AS initial_attempt_status,
    a.primary_terminal_reason_code AS initial_terminal_reason_code,
    a.primary_assessment_open_at AS assessment_open_at,
    a.primary_assessment_close_at AS assessment_close_at,
    r.assessment_open_at AS round_assessment_open_at,
    r.assessment_due_at AS round_assessment_due_at,
    a.primary_session_id AS initial_session_id,
    a.primary_session_status AS initial_session_status,
    ma.terminal_at AS initial_terminal_at,
    a.latest_retry_attempt_id,
    a.latest_retry_status,
    a.latest_review_attempt_id,
    a.latest_review_status AS review_status,
    rev.review_due_at,
    COALESCE(rvc.completed_count, 0) AS completed_review_count,
    rev.review_source_report_id,
    rev.review_source_report_snapshot_id,
    rpt.report_id,
    gr.status AS report_generation_status,
    (
        CASE
            WHEN (rpt.published_at IS NOT NULL) THEN 'PUBLISHED'::text
            WHEN ((gr.status)::text = ANY ((ARRAY['QUEUED'::character varying, 'RUNNING'::character varying, 'RETRYING'::character varying])::text[])) THEN 'GENERATING'::text
            ELSE 'NOT_PUBLISHED'::text
        END)::character varying(100) AS report_publish_status,
    rpt.trainee_release_status,
    r.report_publish_mode,
    r.report_publish_not_before_at,
    (
        CASE
            WHEN (rs.snapshot_id IS NULL) THEN 'UNAVAILABLE'::text
            WHEN ((rs.completion_status)::text = 'FULL'::text) THEN 'AVAILABLE'::text
            ELSE 'PARTIAL'::text
        END)::character varying(100) AS explanation_status,
    notify.reason_code AS latest_notification_reason_code,
    (notify.status)::character varying(100) AS latest_notification_status,
    array_remove(ARRAY[
        CASE
            WHEN ((a.submission_deadline_status)::text = 'MISSED'::text) THEN 'SUBMISSION_DEADLINE_PASSED'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((a.analysis_status)::text = 'FAILED'::text) THEN 'ANALYSIS_FAILED'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((a.primary_assessment_close_at < CURRENT_TIMESTAMP) AND ((a.primary_attempt_status)::text <> 'COMPLETED'::text)) THEN 'ASSESSMENT_WINDOW_CLOSED'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((a.primary_terminal_reason_code)::text = ANY ((ARRAY['INSUFFICIENT_PROBLEM_EVIDENCE'::character varying, 'INSUFFICIENT_OWN_COMMIT_EVIDENCE'::character varying])::text[])) THEN 'PROBLEM_NOT_GENERATED'::text
            ELSE NULL::text
        END], NULL::text) AS warning_codes,
    (
        CASE
            WHEN ((a.latest_review_attempt_id IS NOT NULL) AND ((a.latest_review_status)::text <> ALL ((ARRAY['COMPLETED'::character varying, 'FAILED'::character varying, 'EXPIRED'::character varying])::text[]))) THEN 'REVIEW_REQUIRED'::text
            WHEN ((a.primary_attempt_status)::text = 'COMPLETED'::text) THEN 'ASSESSMENT_COMPLETED'::text
            WHEN (((a.primary_terminal_reason_code)::text = ANY ((ARRAY['NOT_ATTENDED'::character varying, 'SESSION_INCOMPLETE'::character varying])::text[])) OR ((a.primary_assessment_close_at IS NOT NULL) AND (a.primary_assessment_close_at < CURRENT_TIMESTAMP))) THEN 'ASSESSMENT_WINDOW_CLOSED'::text
            WHEN (((a.primary_session_status)::text = ANY ((ARRAY['IN_PROGRESS'::character varying, 'PAUSED'::character varying])::text[])) OR ((a.primary_attempt_status)::text = 'SESSION_IN_PROGRESS'::text)) THEN 'ASSESSMENT_IN_PROGRESS'::text
            WHEN (((a.primary_attempt_status)::text = ANY ((ARRAY['SESSION_READY'::character varying, 'NOT_STARTED'::character varying])::text[])) AND (a.primary_assessment_open_at IS NOT NULL)) THEN 'ASSESSMENT_AVAILABLE'::text
            WHEN ((a.analysis_status)::text = 'FAILED'::text) THEN 'ANALYSIS_FAILED'::text
            WHEN ((a.source_submission_id IS NULL) AND (CURRENT_TIMESTAMP > a.submission_due_at)) THEN 'SUBMISSION_MISSED'::text
            WHEN (a.source_submission_id IS NULL) THEN 'SUBMISSION_REQUIRED'::text
            ELSE 'ANALYZING'::text
        END)::character varying(100) AS representative_status,
    (
        CASE
            WHEN ((a.latest_review_attempt_id IS NOT NULL) AND ((a.latest_review_status)::text <> ALL ((ARRAY['COMPLETED'::character varying, 'FAILED'::character varying, 'EXPIRED'::character varying])::text[]))) THEN 'START_REVIEW'::text
            WHEN (((a.primary_attempt_status)::text = 'COMPLETED'::text) AND ((rpt.trainee_release_status)::text = 'RELEASED'::text)) THEN 'VIEW_REPORT'::text
            WHEN ((a.primary_attempt_status)::text = 'COMPLETED'::text) THEN 'WAIT_FOR_REPORT'::text
            WHEN (((a.primary_session_status)::text = ANY ((ARRAY['IN_PROGRESS'::character varying, 'PAUSED'::character varying])::text[])) AND ((a.primary_assessment_close_at IS NULL) OR (a.primary_assessment_close_at > CURRENT_TIMESTAMP))) THEN 'RESUME_ASSESSMENT'::text
            WHEN (((a.primary_attempt_status)::text = ANY ((ARRAY['SESSION_READY'::character varying, 'NOT_STARTED'::character varying])::text[])) AND (a.primary_assessment_open_at IS NOT NULL) AND ((a.primary_assessment_close_at IS NULL) OR (a.primary_assessment_close_at > CURRENT_TIMESTAMP))) THEN 'START_ASSESSMENT'::text
            WHEN (((a.analysis_status)::text = 'FAILED'::text) AND (a.submission_due_at > CURRENT_TIMESTAMP)) THEN
            CASE
                WHEN ((a.submission_method)::text = 'ZIP_WITH_GITLOG'::text) THEN 'RESUBMIT_ZIP'::text
                ELSE 'RESUBMIT_REPOSITORY'::text
            END
            WHEN ((a.primary_terminal_reason_code)::text = ANY ((ARRAY['NOT_ATTENDED'::character varying, 'SESSION_INCOMPLETE'::character varying, 'NOT_SUBMITTED'::character varying])::text[])) THEN 'CONTACT_MANAGER'::text
            WHEN ((a.source_submission_id IS NULL) AND (CURRENT_TIMESTAMP > a.submission_due_at)) THEN 'CONTACT_MANAGER'::text
            WHEN (a.source_submission_id IS NULL) THEN 'SUBMIT_CODE'::text
            WHEN ((a.analysis_status)::text = ANY ((ARRAY['QUEUED'::character varying, 'RUNNING'::character varying])::text[])) THEN 'WAIT_FOR_ANALYSIS'::text
            ELSE 'NONE'::text
        END)::character varying(100) AS default_action_code,
    (
        CASE
            WHEN ((a.submission_due_at < CURRENT_TIMESTAMP) AND (a.source_submission_id IS NULL)) THEN 'SUBMISSION_DEADLINE_PASSED'::text
            WHEN ((a.primary_assessment_close_at < CURRENT_TIMESTAMP) AND ((a.primary_attempt_status)::text <> 'COMPLETED'::text)) THEN 'ASSESSMENT_WINDOW_CLOSED'::text
            ELSE NULL::text
        END)::character varying(100) AS action_unavailable_reason_code,
    mgr.manager_user_id,
    mgr.manager_name,
    a.aggregation_status,
    CURRENT_TIMESTAMP AS as_of_at,
    au.commit_email_status
   FROM ((((((((((((((((public.assessment_round_attendance a
     JOIN public.project p ON ((p.project_id = a.project_id)))
     JOIN public.project_assessment_round r ON ((r.assessment_round_id = a.assessment_round_id)))
     LEFT JOIN public.class cl ON ((cl.class_id = a.class_id)))
     LEFT JOIN public.team tm ON ((tm.team_id = a.team_id)))
     LEFT JOIN public.app_user au ON ((au.user_id = a.user_id)))
     LEFT JOIN public.measurement_attempt ma ON ((ma.attempt_id = a.primary_attempt_id)))
     LEFT JOIN LATERAL ( SELECT array_agg(pc.curriculum_version_id ORDER BY pc.sequence_no) AS version_ids,
            array_agg(m.title ORDER BY pc.sequence_no) AS names
           FROM ((public.project_curriculum pc
             JOIN public.curriculum_version v ON ((v.version_id = pc.curriculum_version_id)))
             JOIN public.curriculum_material m ON ((m.material_id = v.material_id)))
          WHERE (pc.project_id = a.project_id)) cur ON (true))
     LEFT JOIN LATERAL ( SELECT (count(DISTINCT ps.problem_id))::integer AS problem_count,
            (count(DISTINCT ps.problem_stage_id))::integer AS question_count,
            max((ap.problem_scope)::text) AS problem_scope
           FROM (public.assessment_problem ap
             LEFT JOIN public.problem_stage ps ON (((ps.problem_id = ap.problem_id) AND (ps.session_id = a.primary_session_id) AND ((ap.generation_status)::text = 'GENERATED'::text))))
          WHERE ((ap.measurement_attempt_id = a.primary_attempt_id) OR ((ap.code_analysis_id = ma.code_analysis_id) AND ((ap.problem_scope)::text = 'TEAM_SHARED_PROBLEM'::text)))) probs ON (true))
     LEFT JOIN public.measurement_attempt rev ON ((rev.attempt_id = a.latest_review_attempt_id)))
     LEFT JOIN LATERAL ( SELECT x.report_id,
            x.org_id,
            x.cohort_id,
            x.class_id,
            x.user_id,
            x.assessment_round_id,
            x.report_type,
            x.lifecycle_status,
            x.scheduled_publish_at,
            x.published_at,
            x.trainee_release_status,
            x.trainee_disclosure_scope,
            x.trainee_released_at,
            x.trainee_released_by
           FROM public.report x
          WHERE ((x.user_id = a.user_id) AND (x.assessment_round_id = a.assessment_round_id))
          ORDER BY
                CASE
                    WHEN ((x.lifecycle_status)::text = 'ACTIVE'::text) THEN 0
                    ELSE 1
                END, x.published_at DESC NULLS LAST
         LIMIT 1) rpt ON (true))
     LEFT JOIN LATERAL ( SELECT x.generation_run_id,
            x.report_id,
            x.trigger_type,
            x.idempotency_key,
            x.calculation_version,
            x.status,
            x.failure_reason,
            x.execution_no,
            x.started_at,
            x.completed_at,
            x.request_fingerprint
           FROM public.report_generation_run x
          WHERE (x.report_id = rpt.report_id)
          ORDER BY x.execution_no DESC
         LIMIT 1) gr ON (true))
     LEFT JOIN public.report_snapshot rs ON (((rs.report_id = rpt.report_id) AND rs.is_active)))
     LEFT JOIN LATERAL ( SELECT x.reason_code,
            x.status
           FROM public.reminder_dispatch x
          WHERE ((x.assessment_round_id = a.assessment_round_id) AND (x.user_id = a.user_id))
          ORDER BY x.sent_at DESC NULLS LAST, x.created_at DESC
         LIMIT 1) notify ON (true))
     LEFT JOIN LATERAL ( SELECT x.policy_id,
            x.org_id,
            x.policy_version,
            x.monthly_ai_budget,
            x.currency_code,
            x.monthly_token_limit,
            x.storage_limit_bytes,
            x.retention_days,
            x.default_disclosure_scope,
            x.code_session_tier_code,
            x.allow_manager_invite,
            x.allow_data_export,
            x.allow_zip_submission,
            x.allow_github_integration,
            x.enable_big_project_contribution_analysis,
            x.effective_from,
            x.effective_to,
            x.status,
            x.created_by,
            x.created_at,
            x.updated_by,
            x.updated_at
           FROM public.organization_policy x
          WHERE ((x.org_id = a.org_id) AND ((x.status)::text = 'ACTIVE'::text))
          ORDER BY x.policy_version DESC
         LIMIT 1) pol ON (true))
     LEFT JOIN LATERAL ( SELECT (count(*))::integer AS completed_count
           FROM public.measurement_attempt x
          WHERE ((x.assessment_round_id = a.assessment_round_id) AND (x.user_id = a.user_id) AND ((x.attempt_type)::text = 'REVIEW'::text) AND ((x.status)::text = 'COMPLETED'::text))) rvc ON (true))
     LEFT JOIN LATERAL ( SELECT x.manager_user_id,
            u.name AS manager_name
           FROM (public.manager_assignment x
             JOIN public.app_user u ON ((u.user_id = x.manager_user_id)))
          WHERE ((x.class_id = a.class_id) AND ((x.status)::text = 'ACTIVE'::text))
          ORDER BY x.assigned_at DESC
         LIMIT 1) mgr ON (true));


--
-- Name: trainee_report_archive_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.trainee_report_archive_view AS
 SELECT rpt.org_id,
    rpt.cohort_id,
    rpt.user_id,
    ar.project_id,
    rpt.assessment_round_id,
    rpt.report_id,
    rs.snapshot_id,
    rpt.report_type,
    rpt.published_at,
    rpt.trainee_released_at,
    rs.as_of_at,
    COALESCE((rs.summary_payload -> 'curriculumVersions'::text), '[]'::jsonb) AS curriculum_versions,
    COALESCE((rs.summary_payload -> 'conceptItems'::text), '[]'::jsonb) AS concept_display_snapshots,
    COALESCE((rs.summary_payload -> 'classSnapshot'::text), '{}'::jsonb) AS class_snapshot,
    COALESCE((rs.summary_payload -> 'teamSnapshot'::text), '{}'::jsonb) AS team_snapshot,
    (rs.summary_payload ->> 'reviewSummary'::text) AS review_summary,
    rs.completion_status,
    rpt.trainee_disclosure_scope AS disclosure_scope
   FROM ((public.report rpt
     JOIN public.report_snapshot rs ON ((rs.report_id = rpt.report_id)))
     LEFT JOIN public.project_assessment_round ar ON ((ar.assessment_round_id = rpt.assessment_round_id)))
  WHERE ((rpt.user_id IS NOT NULL) AND (rpt.published_at IS NOT NULL));


--
-- Name: trainee_report_problem_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.trainee_report_problem_view AS
 WITH review_map AS (
         SELECT measurement_attempt.source_attempt_id,
            (array_agg(measurement_attempt.attempt_id ORDER BY measurement_attempt.attempt_sequence_no DESC, measurement_attempt.updated_at DESC) FILTER (WHERE ((measurement_attempt.attempt_type)::text = 'REVIEW'::text)))[1] AS review_attempt_id
           FROM public.measurement_attempt
          GROUP BY measurement_attempt.source_attempt_id
        )
 SELECT rpt.user_id,
    rpt.report_id,
    rs.snapshot_id,
    re.problem_id,
    re.problem_stage_id,
    ap.project_verification_concept_id,
    (COALESCE((re.subject_display_snapshot ->> 'conceptName'::text), (t.canonical_name)::text))::character varying(200) AS concept_display_name,
    COALESCE(re.display_order, pvc.sequence_no) AS concept_display_order,
    ap.problem_scope,
    COALESCE(re.axis_code, ps.axis_code) AS axis_code,
    (ap.best_success_stage)::character varying(100) AS confirmed_through_axis_code,
    (
        CASE ap.best_success_stage
            WHEN 'L1'::text THEN 'L2'::text
            WHEN 'L2'::text THEN 'L3'::text
            WHEN 'L3'::text THEN 'L4'::text
            WHEN 'L4'::text THEN NULL::text
            ELSE 'L1'::text
        END)::character varying(100) AS next_unconfirmed_axis_code,
    (COALESCE(ap.best_success_stage, 'L0'::character varying))::character varying(100) AS reach_display_code,
    ((((ps.question_answer_text IS NOT NULL))::integer + ((ps.first_hint_answer_text IS NOT NULL))::integer) + ((ps.second_hint_answer_text IS NOT NULL))::integer) AS answer_count,
    jsonb_build_array(jsonb_build_object('type', 'QUESTION', 'answer', ps.question_answer_text, 'score', ps.question_score, 'passed', ps.question_passed), jsonb_build_object('type', 'FIRST_HINT', 'answer', ps.first_hint_answer_text, 'score', ps.first_hint_score, 'passed', ps.first_hint_passed), jsonb_build_object('type', 'SECOND_HINT', 'answer', ps.second_hint_answer_text, 'score', ps.second_hint_score, 'passed', ps.second_hint_passed)) AS own_answer_items,
    (COALESCE((re.trace_payload -> 'curriculumLocation'::text), '{}'::jsonb))::text AS curriculum_location,
    re.evidence_summary AS result_explanation,
    re.quote_excerpt AS answer_excerpt,
    ((re.decision_code)::text = 'REVIEW_REQUIRED'::text) AS review_required,
    (COALESCE(re.decision_code, 'NOT_REQUIRED'::character varying))::character varying(100) AS review_status,
    rm.review_attempt_id,
    COALESCE((re.trace_payload -> 'reviewBeforeAfterItems'::text), '[]'::jsonb) AS review_before_after_items,
    ((re.evidence_summary IS NOT NULL) OR (re.quote_excerpt IS NOT NULL)) AS has_explanation_content,
    (
        CASE
            WHEN (re.evidence_id IS NULL) THEN 'UNAVAILABLE'::text
            WHEN ((re.evidence_summary IS NULL) AND (re.quote_excerpt IS NULL)) THEN 'EMPTY'::text
            ELSE 'AVAILABLE'::text
        END)::character varying(100) AS explanation_status,
    (((rpt.trainee_release_status)::text = 'RELEASED'::text) AND ((rpt.trainee_disclosure_scope)::text = ANY ((ARRAY['SUMMARY'::character varying, 'FULL'::character varying])::text[]))) AS can_view_explanation
   FROM ((((((((public.report rpt
     JOIN public.report_snapshot rs ON (((rs.report_id = rpt.report_id) AND rs.is_active)))
     JOIN public.report_evidence re ON ((re.snapshot_id = rs.snapshot_id)))
     LEFT JOIN public.assessment_problem ap ON ((ap.problem_id = re.problem_id)))
     LEFT JOIN public.problem_stage ps ON ((ps.problem_stage_id = re.problem_stage_id)))
     LEFT JOIN public.project_verification_concept pvc ON ((pvc.project_concept_id = ap.project_verification_concept_id)))
     LEFT JOIN public.teaches t ON ((t.teaches_id = pvc.teaches_id)))
     LEFT JOIN public.measurement_attempt initial_ma ON ((initial_ma.attempt_id = ap.measurement_attempt_id)))
     LEFT JOIN review_map rm ON ((rm.source_attempt_id = initial_ma.attempt_id)))
  WHERE ((rpt.user_id IS NOT NULL) AND ((re.evidence_category)::text = ANY ((ARRAY['ANSWER_EXCERPT'::character varying, 'RESULT_EXPLANATION'::character varying, 'CURRICULUM_LOCATION'::character varying])::text[])));


--
-- Name: trainee_report_round_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.trainee_report_round_view AS
 SELECT rpt.org_id,
    rpt.cohort_id,
    rpt.user_id,
    p.project_id,
    p.name AS project_name,
    r.assessment_round_id,
    r.round_name,
    r.round_no,
    COALESCE(ma.terminal_at, r.report_publish_not_before_at) AS round_ended_at,
    ma.attempt_id,
    ma.status AS attempt_status,
    ma.terminal_reason_code,
    ma.validity_review_status,
    rpt.report_id,
    rs.snapshot_id,
    gr.status AS report_generation_status,
    rpt.trainee_release_status,
    rpt.trainee_disclosure_scope,
    (
        CASE
            WHEN ((rpt.trainee_release_status)::text = 'RELEASED'::text) THEN 'VIEWABLE'::text
            WHEN ((gr.status)::text = ANY ((ARRAY['QUEUED'::character varying, 'RUNNING'::character varying, 'RETRYING'::character varying])::text[])) THEN 'GENERATING'::text
            WHEN (rpt.report_id IS NULL) THEN 'NOT_CREATED'::text
            ELSE 'WITHHELD'::text
        END)::character varying(100) AS round_report_view_status,
    r.report_publish_not_before_at,
    rpt.published_at,
    rpt.trainee_released_at,
    rev.status AS review_status,
    rev.review_due_at,
    (((rpt.trainee_release_status)::text = 'RELEASED'::text) AND (rs.snapshot_id IS NOT NULL)) AS can_view_report,
    true AS can_contact_manager,
    COALESCE(rs.as_of_at, CURRENT_TIMESTAMP) AS as_of_at
   FROM ((((((public.report rpt
     JOIN public.project_assessment_round r ON ((r.assessment_round_id = rpt.assessment_round_id)))
     JOIN public.project p ON ((p.project_id = r.project_id)))
     LEFT JOIN public.measurement_attempt ma ON (((ma.assessment_round_id = r.assessment_round_id) AND (ma.user_id = rpt.user_id) AND ((ma.attempt_type)::text = 'INITIAL'::text))))
     LEFT JOIN public.report_snapshot rs ON (((rs.report_id = rpt.report_id) AND rs.is_active)))
     LEFT JOIN LATERAL ( SELECT x.generation_run_id,
            x.report_id,
            x.trigger_type,
            x.idempotency_key,
            x.calculation_version,
            x.status,
            x.failure_reason,
            x.execution_no,
            x.started_at,
            x.completed_at,
            x.request_fingerprint
           FROM public.report_generation_run x
          WHERE (x.report_id = rpt.report_id)
          ORDER BY x.execution_no DESC
         LIMIT 1) gr ON (true))
     LEFT JOIN LATERAL ( SELECT x.attempt_id,
            x.org_id,
            x.cohort_id,
            x.assessment_round_id,
            x.project_id,
            x.user_id,
            x.assessment_contract_version,
            x.source_submission_id,
            x.code_analysis_id,
            x.attempt_type,
            x.source_attempt_id,
            x.attempt_sequence_no,
            x.assigned_at,
            x.assigned_by,
            x.review_source_report_id,
            x.review_source_report_snapshot_id,
            x.review_due_at,
            x.status,
            x.terminal_reason_code,
            x.terminal_at,
            x.analysis_completed_at,
            x.assessment_open_at,
            x.assessment_close_at,
            x.validity_review_status,
            x.validity_trigger_reason_code,
            x.validity_decision_reason_code,
            x.validity_decision_note,
            x.validity_review_started_at,
            x.validity_reviewed_by,
            x.validity_reviewed_at,
            x.row_version,
            x.updated_at
           FROM public.measurement_attempt x
          WHERE ((x.source_attempt_id = ma.attempt_id) AND ((x.attempt_type)::text = 'REVIEW'::text))
          ORDER BY x.attempt_sequence_no DESC
         LIMIT 1) rev ON (true))
  WHERE (rpt.user_id IS NOT NULL);


--
-- Name: trainee_report_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.trainee_report_view AS
 SELECT rpt.org_id,
    rpt.cohort_id,
    rpt.user_id,
    p.project_id,
    rpt.assessment_round_id,
    p.name AS project_name,
    r.round_name,
    rpt.report_id,
    rpt.report_type,
    rpt.lifecycle_status,
    gr.status AS report_generation_status,
    rs.snapshot_id,
    rs.completion_status,
    rpt.published_at,
    rpt.trainee_release_status,
    rpt.trainee_disclosure_scope,
    rpt.trainee_released_at,
    (
        CASE
            WHEN (((rpt.trainee_release_status)::text = 'RELEASED'::text) AND (rs.snapshot_id IS NOT NULL)) THEN 'VIEWABLE'::text
            WHEN ((gr.status)::text = ANY ((ARRAY['QUEUED'::character varying, 'RUNNING'::character varying, 'RETRYING'::character varying])::text[])) THEN 'GENERATING'::text
            WHEN (rpt.published_at IS NULL) THEN 'NOT_PUBLISHED'::text
            ELSE 'WITHHELD'::text
        END)::character varying(100) AS round_report_view_status,
    (((rpt.trainee_release_status)::text = 'RELEASED'::text) AND (rs.snapshot_id IS NOT NULL)) AS can_view_report,
    (((rpt.trainee_release_status)::text = 'RELEASED'::text) AND ((rpt.trainee_disclosure_scope)::text = 'FULL'::text)) AS can_view_own_answers,
    (((rpt.trainee_release_status)::text = 'RELEASED'::text) AND ((rpt.trainee_disclosure_scope)::text = ANY ((ARRAY['SUMMARY'::character varying, 'FULL'::character varying])::text[]))) AS can_view_curriculum_location,
    COALESCE((rs.summary_payload -> 'conceptItems'::text), '[]'::jsonb) AS concept_items,
    (rs.summary_payload ->> 'reviewSummary'::text) AS review_summary,
    rs.as_of_at,
    rs.calculation_version
   FROM ((((public.report rpt
     LEFT JOIN LATERAL ( SELECT x.generation_run_id,
            x.report_id,
            x.trigger_type,
            x.idempotency_key,
            x.calculation_version,
            x.status,
            x.failure_reason,
            x.execution_no,
            x.started_at,
            x.completed_at,
            x.request_fingerprint
           FROM public.report_generation_run x
          WHERE (x.report_id = rpt.report_id)
          ORDER BY x.execution_no DESC
         LIMIT 1) gr ON (true))
     LEFT JOIN public.report_snapshot rs ON (((rs.report_id = rpt.report_id) AND rs.is_active)))
     LEFT JOIN public.project_assessment_round r ON ((r.assessment_round_id = rpt.assessment_round_id)))
     LEFT JOIN public.project p ON ((p.project_id = r.project_id)))
  WHERE (rpt.user_id IS NOT NULL);


--
-- Name: messages; Type: TABLE; Schema: realtime; Owner: -
--

CREATE TABLE realtime.messages (
    topic text NOT NULL,
    extension text NOT NULL,
    payload jsonb,
    event text,
    private boolean DEFAULT false,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    inserted_at timestamp without time zone DEFAULT now() NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    binary_payload bytea
)
PARTITION BY RANGE (inserted_at);


--
-- Name: schema_migrations; Type: TABLE; Schema: realtime; Owner: -
--

CREATE TABLE realtime.schema_migrations (
    version bigint NOT NULL,
    inserted_at timestamp(0) without time zone
);


--
-- Name: subscription; Type: TABLE; Schema: realtime; Owner: -
--

CREATE TABLE realtime.subscription (
    id bigint NOT NULL,
    subscription_id uuid NOT NULL,
    entity regclass NOT NULL,
    filters realtime.user_defined_filter[] DEFAULT '{}'::realtime.user_defined_filter[] NOT NULL,
    claims jsonb NOT NULL,
    claims_role regrole GENERATED ALWAYS AS (realtime.to_regrole((claims ->> 'role'::text))) STORED NOT NULL,
    created_at timestamp without time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    action_filter text DEFAULT '*'::text,
    selected_columns text[],
    CONSTRAINT subscription_action_filter_check CHECK ((action_filter = ANY (ARRAY['*'::text, 'INSERT'::text, 'UPDATE'::text, 'DELETE'::text])))
);


--
-- Name: subscription_id_seq; Type: SEQUENCE; Schema: realtime; Owner: -
--

ALTER TABLE realtime.subscription ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME realtime.subscription_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: buckets; Type: TABLE; Schema: storage; Owner: -
--

CREATE TABLE storage.buckets (
    id text NOT NULL,
    name text NOT NULL,
    owner uuid,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    public boolean DEFAULT false,
    avif_autodetection boolean DEFAULT false,
    file_size_limit bigint,
    allowed_mime_types text[],
    owner_id text,
    type storage.buckettype DEFAULT 'STANDARD'::storage.buckettype NOT NULL
);


--
-- Name: COLUMN buckets.owner; Type: COMMENT; Schema: storage; Owner: -
--

COMMENT ON COLUMN storage.buckets.owner IS 'Field is deprecated, use owner_id instead';


--
-- Name: buckets_analytics; Type: TABLE; Schema: storage; Owner: -
--

CREATE TABLE storage.buckets_analytics (
    name text NOT NULL,
    type storage.buckettype DEFAULT 'ANALYTICS'::storage.buckettype NOT NULL,
    format text DEFAULT 'ICEBERG'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    deleted_at timestamp with time zone
);


--
-- Name: buckets_vectors; Type: TABLE; Schema: storage; Owner: -
--

CREATE TABLE storage.buckets_vectors (
    id text NOT NULL,
    type storage.buckettype DEFAULT 'VECTOR'::storage.buckettype NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: migrations; Type: TABLE; Schema: storage; Owner: -
--

CREATE TABLE storage.migrations (
    id integer NOT NULL,
    name character varying(100) NOT NULL,
    hash character varying(40) NOT NULL,
    executed_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP
);


--
-- Name: objects; Type: TABLE; Schema: storage; Owner: -
--

CREATE TABLE storage.objects (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    bucket_id text,
    name text,
    owner uuid,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    last_accessed_at timestamp with time zone DEFAULT now(),
    metadata jsonb,
    path_tokens text[] GENERATED ALWAYS AS (string_to_array(name, '/'::text)) STORED,
    version text,
    owner_id text,
    user_metadata jsonb
);


--
-- Name: COLUMN objects.owner; Type: COMMENT; Schema: storage; Owner: -
--

COMMENT ON COLUMN storage.objects.owner IS 'Field is deprecated, use owner_id instead';


--
-- Name: s3_multipart_uploads; Type: TABLE; Schema: storage; Owner: -
--

CREATE TABLE storage.s3_multipart_uploads (
    id text NOT NULL,
    in_progress_size bigint DEFAULT 0 NOT NULL,
    upload_signature text NOT NULL,
    bucket_id text NOT NULL,
    key text NOT NULL COLLATE pg_catalog."C",
    version text NOT NULL,
    owner_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    user_metadata jsonb,
    metadata jsonb
);


--
-- Name: s3_multipart_uploads_parts; Type: TABLE; Schema: storage; Owner: -
--

CREATE TABLE storage.s3_multipart_uploads_parts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    upload_id text NOT NULL,
    size bigint DEFAULT 0 NOT NULL,
    part_number integer NOT NULL,
    bucket_id text NOT NULL,
    key text NOT NULL COLLATE pg_catalog."C",
    etag text NOT NULL,
    owner_id text,
    version text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: vector_indexes; Type: TABLE; Schema: storage; Owner: -
--

CREATE TABLE storage.vector_indexes (
    id text DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL COLLATE pg_catalog."C",
    bucket_id text NOT NULL,
    data_type text NOT NULL,
    dimension integer NOT NULL,
    distance_metric text NOT NULL,
    metadata_configuration jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


