CREATE UNIQUE INDEX uq_report_active_user ON public.report USING btree (assessment_round_id, user_id, report_type) WHERE (((lifecycle_status)::text = 'ACTIVE'::text) AND (user_id IS NOT NULL) AND (class_id IS NULL));


--
-- Name: uq_report_generation_run_active; Type: INDEX; Schema: public; Owner: -
--

CREATE UNIQUE INDEX uq_report_generation_run_active ON public.report_generation_run USING btree (report_id, trigger_type) WHERE ((status)::text = ANY ((ARRAY['QUEUED'::character varying, 'RUNNING'::character varying, 'RETRYING'::character varying])::text[]));


--
-- Name: uq_report_snapshot_active; Type: INDEX; Schema: public; Owner: -
--

CREATE UNIQUE INDEX uq_report_snapshot_active ON public.report_snapshot USING btree (report_id) WHERE (is_active = true);


--
-- Name: uq_repository_active_per_team; Type: INDEX; Schema: public; Owner: -
--

CREATE UNIQUE INDEX uq_repository_active_per_team ON public.repository USING btree (team_id) WHERE ((status)::text = 'ACTIVE'::text);


--
-- Name: uq_submission_current; Type: INDEX; Schema: public; Owner: -
--

CREATE UNIQUE INDEX uq_submission_current ON public.submission USING btree (team_id, assessment_round_id) WHERE (is_current = true);


--
-- Name: uq_teaches_active_normalized_name; Type: INDEX; Schema: public; Owner: -
--

CREATE UNIQUE INDEX uq_teaches_active_normalized_name ON public.teaches USING btree (org_id, normalized_name) WHERE ((status)::text = 'ACTIVE'::text);


--
-- Name: uq_team_membership_active; Type: INDEX; Schema: public; Owner: -
--

CREATE UNIQUE INDEX uq_team_membership_active ON public.team_membership USING btree (project_membership_id) WHERE (to_at IS NULL);


--
-- Name: uq_user_invitation_accepted_user_not_null; Type: INDEX; Schema: public; Owner: -
--

CREATE UNIQUE INDEX uq_user_invitation_accepted_user_not_null ON public.user_invitation USING btree (accepted_user_id) WHERE (accepted_user_id IS NOT NULL);


--
-- Name: uq_user_invitation_current_token_not_null; Type: INDEX; Schema: public; Owner: -
--

CREATE UNIQUE INDEX uq_user_invitation_current_token_not_null ON public.user_invitation USING btree (current_token_id) WHERE (current_token_id IS NOT NULL);


--
-- Name: uq_user_invitation_incomplete; Type: INDEX; Schema: public; Owner: -
--

CREATE UNIQUE INDEX uq_user_invitation_incomplete ON public.user_invitation USING btree (org_id, target_email_normalized, target_role_code) NULLS NOT DISTINCT WHERE ((status)::text = ANY ((ARRAY['PENDING'::character varying, 'SENT'::character varying, 'DELIVERY_FAILED'::character varying, 'EXPIRED'::character varying])::text[]));


